const BLOCKS = {
  b_sk:{name:"Скорость",lede:"Короткие отрезки, максимальное усилие, длинный отдых. Работаем свежими, а не на терпении.",levels:{
    sk_n:{level:"Новичок",vol:"1300–1600 м",w:[
      {n:1,vol:1300,note:"Первая скоростная тренировка устроена максимально просто: короткие отрезки, много отдыха, каж…",story:"Первая скоростная тренировка устроена максимально просто: короткие отрезки, много отдыха, каждый отрезок в полную силу. Быстро плыть — это отдельный навык, и учиться ему нужно на свежих мышцах. Если к концу серии вы плывёте медленнее, чем в начале, значит отдыхали мало, а не старались плохо.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[100,"100м ноги кроль с доской"],[100,"4х25м i20: нечётные — упражнение на кроль «на боку 6 ударов, смена рук через пронос», чётные — плавание чуть быстрее"]],main:[[200,"8х25м основным стилем в полную силу, i45","Отдых обязательно выдерживать полностью, даже если кажется, что вы уже готовы. Скорость тренируется отдыхом не меньше, чем работой."],[100,"100м откупка: 50м на спине двумя руками одновременно + 50м кроль длинным гребком — вернуть дыхание"],[100,"4х25м основной стиль в полную силу, i45","На своём стиле следите не за темпом, а за тем, чтобы движения не превращались в суету. Быстро — это длинно и мощно, а не часто и мелко."],[100,"100м откупка: 50м брасс с долгим скольжением + 50м на спине, ноги мягко"],[100,"4х25м основным стилем в полную силу, i45","Последние отрезки — проверка. Если они заметно медленнее первых, в следующий раз сделайте серию короче."]],cool:[[100,"100м спина спокойно, руки вдоль тела"],[100,"100м произвольно, дыхание свободное"],[100,"100м брасс с долгим скольжением"]]},
      {n:2,vol:1350,note:"У большинства начинающих ноги не толкают, а тормозят",story:"У большинства начинающих ноги не толкают, а тормозят. Здесь мы разбираем их отдельно и коротко: несколько быстрых отрезков с полным отдыхом. Цель не выносливость ног, а умение работать ими часто и от бедра — именно это потом добавляет скорость в кроле.",warm:[[200,"200м спокойно: 50м дельфин + 50м спина + 50м брасс + 50м кроль"],[100,"100м ноги дельфин на спине, руки в стрелке"],[100,"4х25м ноги в ластах, i20"]],main:[[200,"8х25м ноги кроль с доской в полную силу, i45","Колени не должны выходить из воды. Движение идёт от бедра, стопа расслаблена и вытянута — как только на поверхности появились колени, отдохните подольше."],[100,"100м откупка: кроль в лёгком темпе, дыхание на 3 гребка — расслабить плечи"],[150,"6х25м ноги на спине без доски в полную силу, i45","Руки вдоль тела, живот подобран, таз у поверхности. На спине сразу видно, если ноги работают вниз, а не назад: тело начинает складываться."],[100,"100м откупка: на спине, руки вдоль тела, ноги мягко — не разгоняться"],[100,"4х25м ноги кроль в ластах с максимальной частотой, i30","Ласты помогают почувствовать правильное движение. Запомните это ощущение — без ласт нужно повторить его же, только медленнее."]],cool:[[100,"100м спина: работа двумя руками одновременно, ноги почти без усилия"],[100,"100м кроль на минимальное число гребков"],[100,"100м ноги дельфин на спине, руки в стрелке, мягко"]]},
      {n:3,vol:1300,note:"Скорость начинается не с усилия, а с разгона",story:"Скорость начинается не с усилия, а с разгона. Три способа набрать её — с места, с толчка и по гребкам — и все на очень коротких отрезках, чтобы техника не успевала рассыпаться. Отдых полный: пока дыхание не вернулось, следующий отрезок смысла не имеет.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[100,"100м ноги кроль с доской, спокойно"],[100,"4х25м i20: толчок и скольжение в стрелке до полной остановки — настраиваем выход со стенки"]],main:[[200,"8х25м основным стилем с места, отдых 40 сек: вытянуться в стрелку у бортика, ноги стенки не касаются — толчка нет, до стенки в полную силу","Без толчка скорость приходится набирать руками. Первые гребки короткие и частые — длинный появляется, только когда тело уже поехало."],[100,"100м откупка: 50м на спине двумя руками одновременно + 50м брасс на скольжение"],[100,"4х25м основным стилем с толчка, отдых 40 сек: под водой 5м в стрелке, выход и до стенки в полную силу","Под водой не гребём — держим стрелку и ждём, пока скорость от толчка начнёт падать. Начала — выходим и плывём."],[100,"100м откупка: кроль в лёгком темпе, дыхание на 3 гребка"],[100,"4х25м основным стилем по гребкам, отдых 40 сек: первые 5 гребков спокойно, дальше до конца отрезка в полную силу","Считать гребки проще, чем метры, и переключение получается резче. Сбились со счёта — начните счёт заново на следующем отрезке."]],cool:[[100,"100м на спине двумя руками одновременно, спокойно"],[100,"100м брасс с долгим скольжением"],[100,"100м произвольно, дыхание свободное"]]},
      {n:4,vol:1500,note:"Тот же приём, что и у старших уровней, но проще: сначала плывём с сопротивлением, потом без н…",story:"Тот же приём, что и у старших уровней, но проще: сначала плывём с сопротивлением, потом без него, в конце — в ластах. Парашют не нужен, хватит обычной футболки. Задача не устать, а почувствовать разницу: после футболки вода перестаёт казаться густой.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[100,"100м ноги кроль с доской, спокойно"],[100,"4х25м i20: через одну — кроль на минимальное число гребков и ноги кроль, руки в стрелке"]],main:[[200,"4х50м в футболке, отдых 45 сек: 25м в полную силу основным стилем + 25м кроль свободно","Футболка — самое простое сопротивление, ничего покупать не нужно. Гребок станет тяжёлым, но частоту стараемся не терять."],[100,"100м откупка: 50м на спине двумя руками одновременно + 50м брасс на скольжение"],[200,"4х50м без инвентаря, отдых 45 сек: 25м в полную силу основным стилем + 25м кроль свободно","Та же серия без футболки. Должно стать заметно легче — именно за этим ощущением мы и приходили."],[100,"100м откупка: кроль в лёгком темпе, дыхание на 3 гребка"],[100,"4х25м основным стилем в ластах, отдых 45 сек, в полную силу","В ластах вы плывёте быстрее, чем умеете сами. Руками работаем как обычно, не частим — ноги сделают остальное."],[100,"100м откупка: 50м брасс + 50м спина спокойно"]],cool:[[100,"100м на спине двумя руками одновременно, спокойно"],[100,"100м брасс с долгим скольжением"],[100,"100м произвольно, дыхание свободное"]]},
      {n:5,vol:1300,note:"Поворот — самое дешёвое место, где начинающий выигрывает время: техника плавания строится мес…",story:"Поворот — самое дешёвое место, где начинающий выигрывает время: техника плавания строится месяцами, а стенка отдаёт секунды почти сразу. Сначала разбираем заход, потом выход, и только в конце соединяем. Отрезки по 25 метров, чтобы на каждый приходился ровно один разворот.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[100,"100м ноги дельфин на спине, руки в стрелке, спокойно"],[100,"4х25м кроль i20: подход к стенке спокойно, кувырок и толчок в полную силу, скольжение в стрелке, дальше свободно"]],main:[[150,"6х25м кроль, отдых 40 сек: последние 5м перед стенкой в полную силу, дальше кувырок и скольжение — работаем заход","Почти все тормозят перед бортиком заранее. Последний гребок остаётся полным, и только после него начинается группировка."],[100,"100м откупка: 50м на спине двумя руками одновременно + 50м брасс на скольжение"],[150,"6х25м основным стилем, отдых 40 сек: толчок, скольжение в стрелке и первые 10м в полную силу — работаем выход","После толчка тело вытянуто: одна кисть на другой, голова между руками. Гребок начинается только после всплытия — грести под водой на подъёме бесполезно."],[100,"100м откупка: кроль в лёгком темпе, дыхание на 3 гребка"],[100,"2х50м основным стилем, отдых 60 сек: 5м до поворота и 5м после в полную силу, остальное спокойно"]],cool:[[100,"4х25м скольжения от бортика до полной остановки, руки в стрелке"],[100,"100м брасс с долгим скольжением"],[100,"100м произвольно, дыхание свободное"]]},
      {n:6,vol:1300,note:"Плыть быстро даже полтинник начинающему тяжело: техника разваливается к середине",story:"Плыть быстро даже полтинник начинающему тяжело: техника разваливается к середине. Поэтому отрезок разбивается паузами — сначала частыми, потом реже, и только в конце плывётся целиком. Между попытками много спокойного плавания: быстро получается только на свежих силах.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[100,"100м ноги кроль с доской, спокойно"],[100,"4х25м основным стилем i20: через одну — свободно и с ускорением на последних 10м"]],main:[[100,"100м основным стилем дробно: 4х25м в полную силу с паузой 15 секунд","Каждый четвертак — отдельная попытка. Пауза даёт отдышаться и оттолкнуться заново, поэтому все четыре должны получиться одинаковыми."],[150,"150м откупка: 50м на спине двумя руками одновременно + 100м кроль в лёгком темпе"],[50,"50м основным стилем дробно: 2х25м в полную силу с паузой 10 секунд","Пауза стала короче, держать тяжелее. Если второй четвертак заметно медленнее — отдохните перед следующим заданием подольше."],[150,"150м откупка: 50м брасс с долгим скольжением + 50м спина + 50м кроль длинным гребком"],[50,"50м основным стилем в полную силу целиком, отдых до полного восстановления","Тот же полтинник без пауз. Он будет тяжелее — это нормально и как раз показывает, сколько скорости держится без остановки."],[100,"100м откупка: кроль в лёгком темпе, дыхание на 3 гребка"]],cool:[[100,"100м брасс с долгим скольжением"],[100,"100м на спине двумя руками одновременно, спокойно"],[100,"100м произвольно, дыхание свободное"]]},
      {n:7,vol:1300,note:"Для начинающего в старте важна не сила толчка, а вход в воду: если тело шлёпнуло по поверхнос…",story:"Для начинающего в старте важна не сила толчка, а вход в воду: если тело шлёпнуло по поверхности, скорость пропадает мгновенно и толкаться было незачем. Отрезки очень короткие, отдыха много — работаем над качеством, а не над усталостью.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[100,"100м ноги дельфин на спине, руки в стрелке, спокойно"],[100,"4х25м кроль i30: со старта — акцент на сильный толчок от тумбочки, дальше спокойно"]],main:[[150,"6х25м основным стилем со старта, отдых 60 сек: прыжок, скольжение в стрелке до 7 метров и 3 гребка быстро, дальше спокойно"],[150,"150м откупка: 50м на спине двумя руками одновременно + 100м кроль в лёгком темпе"],[100,"4х25м основным стилем со старта, отдых 60 сек: прыжок, скольжение до 7 метров, выход и до стенки быстро","Под водой не гребём — держим стрелку. Первый гребок начинается после всплытия: грести на подъёме бесполезно, это гасит скорость прыжка."],[100,"100м откупка: кроль в лёгком темпе, дыхание на 3 гребка"],[100,"2х50м основным стилем со старта, отдых 90 сек: 1-я — 25м быстро + 25м спокойно, 2-я — 50м быстро"]],cool:[[100,"100м брасс с долгим скольжением"],[100,"100м на спине двумя руками одновременно, спокойно"],[100,"4х25м скольжения от бортика до полной остановки, руки в стрелке"]],safe:"Прыгать только там, где глубина это позволяет, и только с бортика, если тумбочки нет. В незнакомом бассейне сначала посмотрите разметку глубин."},
      {n:8,vol:1500,note:"Плыть на одной скорости умеют все, а переключаться — почти никто",story:"Плыть на одной скорости умеют все, а переключаться — почти никто. Сначала разгоняемся ступенями, потом меняем темп внутри отрезка, в конце меняем стиль на ходу. Дельфина в ступенях нет: на этом уровне он съедает технику быстрее, чем приносит пользы.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[100,"100м ноги дельфин на спине, руки в стрелке, спокойно"],[100,"4х25м i20: через одну — спина и кроль"]],main:[[300,"3 серии по 4х25м i30, каждая серия своим стилем — спина, брасс, кроль: 1-й отрезок спокойно, 2-й средне, 3-й быстро, 4-й максимум","Ступени должны быть примерно одинаковыми. Если первый отрезок уже быстрый, расти будет некуда — начинайте спокойнее, чем кажется нужным."],[100,"100м откупка: 50м ноги брасс на спине, руки в стрелке + 50м брасс на скольжение"],[200,"4х50м, отдых 45 сек: 25м быстро основным стилем + 25м кроль спокойно","Спокойная половина — не выключение. Тело остаётся вытянутым, гребок длинным: учимся сбрасывать усилие, не теряя положения."],[100,"100м откупка: 50м кроль на минимальное число гребков + 50м спина спокойно"],[100,"2х50м, отдых 45 сек: 25м спина в полную силу + 25м основным стилем спокойно","Смена стиля на ходу. Переключаемся с первого гребка, без раскачки — именно это потом выручает в комплексе."]],cool:[[100,"100м брасс с долгим скольжением"],[100,"100м на спине двумя руками одновременно, спокойно"],[100,"4х25м скольжения от бортика до полной остановки, руки в стрелке"]]},
      {n:9,vol:1400,note:"У начинающего вдох обычно не поворот, а подъём: голова идёт вверх, ноги проваливаются, скорос…",story:"У начинающего вдох обычно не поворот, а подъём: голова идёт вверх, ноги проваливаются, скорость исчезает. Поэтому работаем не над тем, чтобы дышать реже, а над тем, чтобы вдох был дешёвым. Никаких задержек — только короткие отрезки и внимание к голове.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[100,"100м кроль, вдох в обе стороны, спокойно"],[100,"4х25м кроль i20: через одну — вдох в правую и в левую сторону"]],main:[[150,"6х25м основным стилем, отдых 40 сек: три вдоха на отрезок, быстро","Три вдоха на двадцать пять метров — это не задержка, а просто чуть реже обычного. Одна щека остаётся в воде: если голова пошла вверх, дышите как привыкли."],[150,"150м откупка: 50м на спине двумя руками одновременно + 100м кроль в лёгком темпе"],[100,"4х25м основным стилем, отдых 40 сек: последние 5м без дыхания, быстро","Пять метров до стенки без вдоха — столько выдерживает любой. Это привычка не поднимать голову на финише."],[100,"100м откупка: кроль в лёгком темпе, дыхание свободное"],[100,"2х50м основным стилем, отдых 60 сек: быстро, дыхание привычное"],[100,"100м откупка: 50м брасс с долгим скольжением + 50м спина спокойно"]],cool:[[100,"100м брасс с долгим скольжением"],[100,"100м на спине двумя руками одновременно, спокойно"],[100,"4х25м скольжения от бортика до полной остановки, руки в стрелке"]]},
      {n:10,vol:1450,note:"Почти все начинающие перед стенкой сбавляют и поднимают голову, чтобы посмотреть, далеко ли д…",story:"Почти все начинающие перед стенкой сбавляют и поднимают голову, чтобы посмотреть, далеко ли до неё. Финиш — это привычка делать ровно наоборот: разогнаться и дотянуться, не глядя. Отрезки короткие, чтобы на каждый пришёлся один финиш.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[100,"100м ноги кроль с доской, спокойно"],[100,"4х25м основным стилем i20: финиш с ускорением"]],main:[[150,"6х25м основным стилем, отдых 40 сек: финиш с ускорением на последних 10м","Не смотрим на стенку — она никуда не денется. Взгляд вниз, рука дотягивается сама."],[150,"150м откупка: 50м на спине двумя руками одновременно + 100м кроль в лёгком темпе"],[100,"4х25м основным стилем, отдых 40 сек: в полную силу, последние 5м без дыхания","Пять метров без вдоха — столько выдерживает любой. Это привычка не поднимать голову перед касанием."],[150,"150м откупка: кроль в лёгком темпе, дыхание свободное"],[200,"4х50м, отдых 40 сек: 35м кроль свободно + 15м в полную силу основным стилем на финиш","Здесь финиш длиннее и приходит на уставшие руки."]],cool:[[100,"100м брасс с долгим скольжением"],[100,"100м на спине двумя руками одновременно, спокойно"],[100,"4х25м скольжения от бортика до полной остановки, руки в стрелке"]]},
      {n:11,vol:1400,note:"Колобашка выключает ноги, и вся работа остаётся на руках",story:"Колобашка выключает ноги, и вся работа остаётся на руках. Для начинающего это лучший способ почувствовать, что такое опора: без ног обмануть себя не получится. Колобашка обязательна. Отрезки короткие, потому что руки устают быстро, а плавать быстро уставшими руками смысла нет.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[100,"100м руки кроль с колобашкой спокойно"],[100,"4х25м i20: через одну — упражнение на кроль «плавание на кулаках» и кроль свободно"]],main:[[200,"8х25м руки кроль с колобашкой, отдых 40 сек: каждая 3-я в полную силу, остальные спокойно","Без ног таз проваливается. Держите его у поверхности напряжением живота."],[150,"150м откупка: 50м на спине двумя руками одновременно + 100м кроль в лёгком темпе"],[100,"4х25м руки кроль с колобашкой и в маленьких лопатках, отдых 40 сек: в полную силу","С лопатками легко потащить воду прямой рукой. Локоть остаётся выше кисти."],[150,"150м откупка: 50м брасс с долгим скольжением + 100м спина спокойно"],[100,"4х25м основным стилем в полной координации, отдых 40 сек: в полную силу","Колобашку снимаем. Должно стать заметно легче — это и есть вклад ног."]],cool:[[100,"100м брасс с долгим скольжением"],[100,"100м на спине двумя руками одновременно, спокойно"],[100,"4х25м скольжения от бортика до полной остановки, руки в стрелке"]]},
      {n:12,vol:1400,note:"Чтобы плыть быстро, нужно хотя бы раз почувствовать, что такое быстро",story:"Чтобы плыть быстро, нужно хотя бы раз почувствовать, что такое быстро. Ласты дают скорость выше вашей собственной, и тело запоминает положение на этой скорости: таз высоко, тело ровное. Дальше повторяем то же ощущение без ласт — сразу, пока оно не ушло.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[100,"100м ноги дельфин в ластах на спине, руки в стрелке, спокойно"],[100,"4х25м в ластах i20: через одну — спина и кроль"]],main:[[200,"8х25м основным стилем в ластах, отдых 40 сек: в полную силу с высокой частотой гребка","В ластах тело едет само — задача запомнить, как высоко идёт таз и каким ровным становится положение."],[150,"150м откупка: 50м ноги брасс на спине, руки в стрелке + 100м кроль в лёгком темпе"],[200,"4х50м, отдых 60 сек: нечётные в ластах, чётные без ласт, все в полную силу основным стилем","Ласты снимаем в паузе. Без них будет заметно тяжелее — это нормально. Главное держать то же положение тела, а не ту же скорость."],[150,"150м откупка: 50м брасс с долгим скольжением + 100м спина спокойно"]],cool:[[100,"100м в ластах спокойно: 50м на спине + 50м кроль"],[100,"100м руки кроль с колобашкой спокойно"],[100,"4х25м скольжения от бортика до полной остановки, руки в стрелке"]]},
      {n:13,vol:1400,note:"Скорость складывается из двух вещей: как часто вы гребёте и сколько проплываете за один гребок",story:"Скорость складывается из двух вещей: как часто вы гребёте и сколько проплываете за один гребок. Новичок обычно улучшает одно за счёт другого и стоит на месте. Сегодня пробуем то и другое по отдельности, а в конце соединяем. Считаем только гребки — это несложно и делается само.",warm:[[200,"200м спокойно: 100м кроль + 100м ноги брасс с доской"],[100,"4х25м скольжения от бортика до полной остановки, руки в стрелке"],[100,"4х25м кроль i20 на минимальное число гребков"]],main:[[200,"4х50м основным стилем, режим 1:30: на минимальное число гребков","Запомните число — оно понадобится в конце. Гребков становится меньше, когда рука дольше тянется вперёд, а не когда вы делаете паузу."],[100,"100м откупка: спина двумя руками одновременно — плечи опустить"],[100,"4х25м основным стилем, отдых 40 сек: через одну — на минимальное число гребков и максимально быстро, разгоняем темп","Два соседних отрезка про противоположное. На быстром продвижение упадёт, и это нормально: сейчас важна только частота."],[100,"100м откупка: 50м брасс с долгим скольжением + 50м спина спокойно"],[100,"4х25м основным стилем, отдых 40 сек: держим число гребков из первой серии, но быстрее","Соединяем. То же количество гребков, но каждый — активнее. Если число поехало вверх, значит поторопились: сбавьте и попробуйте ещё раз."],[100,"100м откупка: 50м кроль на минимальное число гребков + 50м спина спокойно"]],cool:[[100,"4х25м кроль на минимальное число гребков, i20"],[100,"100м кроль в лёгком темпе — следим только за тем, чтобы рука доходила до бедра"],[100,"100м ноги брасс на спине, руки в стрелке"]]},
      {n:14,vol:1500,note:"Комплексное плавание пугает переходами: кажется, что нужно успеть слишком много",story:"Комплексное плавание пугает переходами: кажется, что нужно успеть слишком много. На деле переход — это одно касание и один разворот, и он прекрасно тренируется отдельно. Дельфина сегодня нет: на этом уровне он съедает силы раньше, чем начнётся работа над переходами. Берём два — со спины на брасс и с брасса на кроль.",warm:[[200,"200м спокойно: 100м спина + 100м брасс"],[100,"100м ноги брасс с доской, спокойно"],[100,"4х25м i20: через одну — спина и брасс"]],main:[[200,"4х50м i45: 25м спина в полную силу + 25м брасс спокойно — работаем переход"],[150,"150м откупка: 50м на спине двумя руками одновременно + 100м кроль в лёгком темпе"],[200,"4х50м i45: 25м брасс в полную силу + 25м кроль спокойно — работаем переход"],[150,"150м откупка: 50м брасс с долгим скольжением + 100м спина спокойно"],[100,"2х50м i60: 25м спина + 25м брасс, оба быстро — переход на скорости","Теперь обе половины в полную силу. Переход остаётся тем же, просто подходим к нему уже разогнавшись."]],cool:[[200,"200м спокойно: 100м спина + 100м брасс с долгим скольжением"],[100,"4х25м скольжения от бортика до полной остановки, руки в стрелке"]]},
      {n:15,vol:1600,note:"Раньше перед каждым быстрым отрезком вы успевали отдышаться",story:"Раньше перед каждым быстрым отрезком вы успевали отдышаться. Сегодня отдых становится короче, и скорость приходится держать уже уставшим. Отрезки остаются короткими — тяжело будет не от их длины, а от того, что пауз мало.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[100,"100м ноги кроль с доской, спокойно"],[100,"4х25м i20: через одну — кроль свободно и основным стилем с ускорением на последних 10м"]],main:[[100,"4х25м основным стилем, все в полную силу. Отдых убывает: первые две по 45 сек, последние две по 30","Скорость должна остаться той же, а отдыха становится меньше. Если последняя заметно медленнее — начните серию спокойнее, а не терпите."],[250,"250м откупка: 50м на спине двумя руками одновременно + 100м брасс с долгим скольжением + 100м кроль в лёгком темпе"],[200,"4х50м, отдых 30 сек: 35м кроль ровно + 15м в полную силу основным стилем","Ускорение приходит в конце отрезка, когда уже не свежий. Пятнадцать метров — немного, и именно поэтому их надо проплыть одинаково во всех четырёх."],[150,"150м откупка: 50м брасс с долгим скольжением + 100м спина спокойно"],[100,"100м без отдыха: каждые 25м — первые 10м в полную силу основным стилем, дальше кроль свободно","Пауз нет совсем. Разгоняться приходится из движения — сначала будет непривычно."],[100,"100м откупка: кроль в лёгком темпе, дыхание свободное"]],cool:[[200,"200м спокойно: 100м спина + 100м брасс с долгим скольжением"],[100,"4х25м скольжения от бортика до полной остановки, руки в стрелке"]]}
    ]},
    sk_s:{level:"Средний",vol:"1800–2350 м",w:[
      {n:1,vol:1800,note:"Самая честная скоростная тренировка: короткие отрезки, полный отдых, максимальная скорость",story:"Самая честная скоростная тренировка: короткие отрезки, полный отдых, максимальная скорость. Половина работы кролем, половина — своим стилем, потому что скорость нужна не только в кроле. Задача не терпеть, а каждый раз стартовать свежим: если время падает к концу серии, не хватило отдыха, а не характера.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[200,"200м ноги кроль с доской спокойно"],[200,"200м спокойно: 50м дельфин + 50м спина + 50м брасс + 50м кроль"],[100,"4х25м i20: нечётные — упражнение на спину «3 гребка на груди, 3 гребка на спине», чётные — плавание в прогресс"]],main:[[200,"8х25м основным стилем в полную силу, режим 1:00","Считайте гребки на каждом отрезке. К концу серии их число не должно вырасти больше чем на один-два: если выросло, скорость держится частотой, а гребок уже разваливается."],[200,"200м откупка: 100м на спине двумя руками одновременно + 100м кроль длинным гребком — дыхание свободное"],[200,"4х50м основной стиль в полную силу, режим 2:00","На своём стиле техника рассыпается первой. Следите за длиной гребка, а не за частотой: на скорости выигрывает тот, кто остаётся техничным."],[100,"100м откупка: 50м на спине двумя руками одновременно + 50м кроль длинным гребком — вернуть дыхание"],[100,"4х25м основным стилем в полную силу, режим 1:00","Последние отрезки — проверка. Если они медленнее первых, в следующий раз сокращайте серию, а не отдых."]],cool:[[100,"100м спина спокойно, руки вдоль тела"],[100,"100м произвольно, дыхание свободное"],[100,"100м брасс с долгим скольжением"]]},
      {n:2,vol:1900,note:"Ноги дают до трети скорости в спринте, но тренируют их обычно медленно и долго",story:"Ноги дают до трети скорости в спринте, но тренируют их обычно медленно и долго. Здесь наоборот: короткие максимальные отрезки, высокая частота и разные положения тела. После такой тренировки обычный кроль ощущается легче, потому что ноги перестают быть тормозом и начинают толкать.",warm:[[200,"200м спокойно: 100м кроль с дыханием 3/3 + 100м брасс на длинное скольжение"],[200,"200м спокойно: 100м спина, руки вдоль тела + 100м кроль на минимальное число гребков"],[200,"4х50м ноги кроль в ластах в прогресс, i30"],[100,"4х25м ноги дельфин на спине в ластах, i20"]],main:[[200,"8х25м ноги кроль без доски в полную силу, режим 1:00","Колени не выходят из воды, движение идёт от бедра. На высокой частоте это теряется первым: как только на поверхности появились колени, добавьте себе 15 секунд отдыха."],[200,"200м откупка: 100м брасс с долгим скольжением + 100м спина, ноги мягко"],[300,"6х50м ноги с доской, режим 1:30: 25м дельфин на груди максимум + 25м на спине свободно","Дельфин на максимуме идёт от груди и таза, а не от коленей. Стопы вместе, амплитуда небольшая — удар должен быть быстрым, а не размашистым."],[100,"100м откупка: 50м брасс с долгим скольжением + 50м на спине, ноги мягко"],[100,"4х25м ноги кроль с доской в полную силу, режим 1:00","С доской видно, куда уходит усилие. Если доска прыгает и вы плывёте медленно — работа идёт вверх-вниз, а не назад."]],cool:[[100,"100м кроль на минимальное число гребков"],[100,"100м ноги дельфин на спине, руки в стрелке, мягко"],[100,"100м на спине двумя руками одновременно, спокойно"]]},
      {n:3,vol:2100,note:"Тот же разбор разгона, что и у продвинутых, но короче и без задержки дыхания на пятнадцати ме…",story:"Тот же разбор разгона, что и у продвинутых, но короче и без задержки дыхания на пятнадцати метрах: на этом уровне она съедает технику быстрее, чем приносит пользы. Отдых полный и в секундах, а не по режиму.",warm:[[200,"200м спокойно: 100м кроль с дыханием 3/3 + 100м брасс на длинное скольжение"],[200,"8х25м i20: толчок, 5 ударов дельфином под водой, выход и до стенки быстро"],[200,"4х50м основным стилем i30: 25м с места в полную силу + 25м свободно"]],main:[[200,"8х25м основным стилем с места, отдых 40 сек: вытянуться в стрелку у бортика, ноги стенки не касаются — толчка нет, разгон только руками, до стенки максимум","Стенка не помогает — видно чистую работу рук. Первые три гребка короткие и частые: длинный появляется, только когда скорость уже набрана. Если к концу серии отрезок ощущается заметно тяжелее, отдыхайте дольше."],[100,"100м откупка: 50м кроль на минимальное число гребков + 50м спина спокойно"],[200,"4х50м с толчка, отдых 45 сек: под водой 7–8м дельфином, выход и 10м максимум, остаток свободно","Выход из-под воды — единственное место, где вы плывёте быстрее, чем умеете. Дышать на этих десяти метрах не нужно: вдох гасит скорость сильнее, чем экономит силы."],[100,"100м откупка: на спине, руки вдоль тела, ноги мягко"],[200,"4х50м основным стилем по гребкам, отдых 45 сек: 5 гребков на 80%, 5 на 90%, дальше максимум до 25 метров","Отрезок делится не метрами, а гребками, и переключаться приходится по ощущению. Считайте про себя: сбились — и серия превратилась в обычный полтинник."],[100,"100м откупка: кроль в лёгком темпе, дыхание на 3 гребка"],[200,"200м основным стилем: первые 10м каждой полусотни в полную силу, дальше свободно","Сборка. Задача не проплыть быстро всё, а каждый раз выйти на скорость заново и не потерять положение тела, когда усилие сбрасывается."],[100,"100м откупка: 50м брасс на скольжение + 50м спина спокойно"]],cool:[[200,"200м в трубке спокойно: 100м ноги брасс + 100м ноги кроль"],[100,"4х25м скольжения от бортика до полной остановки, руки в стрелке"]]},
      {n:4,vol:2100,note:"Три круга одной серии: с сопротивлением, без ничего и в ластах",story:"Три круга одной серии: с сопротивлением, без ничего и в ластах. Смысл не в усталости, а в переходе между кругами — после тяжёлого чистый ощущается легче, а после ластов обычная скорость кажется медленной.",warm:[[200,"200м по 50м: кроль с дыханием 3/3 + кроль с дыханием 5/5 + кроль с дыханием 7/7 + спина в полной координации"],[200,"200м спокойно: 100м брасс на длинное скольжение + 100м на спине двумя руками одновременно"],[200,"8х25м i20: через одну — кроль на минимальное число гребков и ноги кроль, руки в стрелке"],[100,"100м ноги дельфин на спине в ластах, i30"]],main:[[200,"4х50м с парашютом, отдых 45 сек: 25м в полную силу основным стилем + 25м кроль свободно","С сопротивлением гребок сам становится длиннее и медленнее. Задача обратная: удержать привычную частоту, даже если продвижение почти пропало."],[100,"100м откупка: на спине, руки вдоль тела, ноги мягко"],[200,"4х50м без инвентаря, отдых 45 сек: 25м в полную силу основным стилем + 25м кроль свободно","Тот же отрезок без сопротивления. Первые метры покажутся пустыми — это нормально, просто рука привыкла к большему."],[100,"100м откупка: 50м брасс на скольжение + 50м спина спокойно"],[200,"4х50м в ластах, отдых 45 сек: 25м в полную силу основным стилем + 25м кроль свободно","Здесь вы плывёте быстрее, чем умеете. Ласты нужны не для ног, а чтобы тело побывало на скорости, которой само не даёт. Гребок держим тем же, не частим."],[100,"100м откупка: кроль в лёгком темпе, дыхание на 3 гребка"],[100,"2х50м основным стилем без инвентаря, отдых 60 сек, в полную силу — проверяем, осталась ли скорость","Если после ластов полтинник ощущается быстрее обычного — это и есть результат тренировки, и держится он примерно двадцать минут."]],cool:[[200,"200м спокойно: 100м спина + 100м брасс с долгим скольжением"],[100,"4х25м скольжения от бортика до полной остановки, руки в стрелке"],[100,"100м на спине, руки вдоль тела, ноги мягко"]]},
      {n:5,vol:1900,note:"Стенка разобрана на три части: сам разворот, заход и выход",story:"Стенка разобрана на три части: сам разворот, заход и выход. Скорость здесь почти не стоит сил — вы не плывёте быстрее, вы перестаёте тормозить перед бортиком.",warm:[[200,"200м по 50м: дельфин — спина — брасс — кроль, спокойно"],[200,"200м ноги дельфин на спине, руки в стрелке, i30"],[200,"8х25м i20: подход к стенке спокойно, кувырок и толчок в полную силу, 4 удара дельфином под водой быстро, дальше свободно"]],main:[[200,"4х50м основным стилем «пятёрка вокруг стенки», отдых 40 сек: 5м до поворота и 5м после — в полную силу, остальное свободно"],[100,"100м откупка: на спине, руки вдоль тела, ноги мягко"],[200,"4х50м основным стилем, отдых 45 сек: первые 25м спокойно, вторые 25м в полную силу — работаем выход","Скорость второй половины закладывается до стенки."],[100,"100м откупка: 50м брасс на скольжение + 50м спина спокойно"],[200,"4х50м основным стилем, отдых 45 сек: первые 25м в полную силу, вторые 25м спокойно — работаем заход","Самая частая ошибка — сбросить скорость перед стенкой, чтобы «удобно» развернуться. Заходим на полном ходу, стопы ставим на глубине 30–40 см."],[100,"100м откупка: кроль в лёгком темпе, дыхание на 3 гребка"],[100,"2х50м основным стилем в полную силу, отдых 60 сек — собираем заход и выход вместе"]],cool:[[200,"200м спокойно: 100м спина + 100м брасс с долгим скольжением"],[100,"4х25м скольжения от бортика до полной остановки, руки в стрелке"]]},
      {n:6,vol:1950,note:"Максимум держится недолго, дальше начинается терпение",story:"Максимум держится недолго, дальше начинается терпение. Дробные отрезки обходят это: сотня разбивается паузами, и каждый кусок остаётся спринтом. Каждая дробная делается один раз, а между ними много спокойного плавания — без него следующая попытка не получится.",warm:[[200,"200м спокойно: 100м кроль, вдох в обе стороны + 100м брасс на скольжение"],[200,"8х25м основным стилем i20: через одну — свободно и с ускорением на последних 10м"],[200,"4х50м основным стилем i30, в прогресс от первой к четвёртой"]],main:[[100,"100м основным стилем дробно: 4х25м в полную силу с паузой 10 секунд после каждых 25м","Пауза короткая — ровно чтобы оттолкнуться от стенки заново. Задача проплыть четвёртый четвертак так же, как первый: проверяется не сила, а то, насколько ровно держится скорость."],[250,"250м откупка: 100м на спине двумя руками одновременно + 150м кроль в лёгком темпе"],[100,"100м основным стилем дробно: 2х50м в полную силу с паузой 15 секунд","Пауз меньше, куски длиннее — держать тяжелее. Второй полтинник не должен просесть по длине гребка больше чем на пару гребков."],[250,"250м откупка: 50м брасс с долгим скольжением + 100м спина + 100м кроль длинным гребком"],[100,"100м основным стилем в полную силу целиком, отдых до полного восстановления","Та же сотня, но без пауз, и ощущается она совсем иначе. Чем ближе это ощущение к дробной, тем лучше скорость держится на дистанции."],[250,"250м откупка: 100м ноги брасс на спине, руки в стрелке + 150м спина спокойно"]],cool:[[200,"200м спокойно: 100м спина + 100м брасс с долгим скольжением"],[100,"100м на спине двумя руками одновременно, спокойно"]]},
      {n:7,vol:1900,note:"Старт даёт скорость, которую сами вы развить не можете, — и вся задача в том, чтобы не растер…",story:"Старт даёт скорость, которую сами вы развить не можете, — и вся задача в том, чтобы не растерять её в первые секунды. Разбираем по частям: толчок от тумбочки, вход в воду, подводная часть, первые гребки. Ориентир — метры и число гребков, а не время. Подводная часть короче, чем у продвинутых: пятнадцать метров под водой на этом уровне обычно значит задержку дыхания дольше, чем человек готов держать.",warm:[[200,"200м спокойно: 100м кроль + 100м брасс на длинное скольжение"],[200,"200м ноги дельфин в ластах на боку, смена стороны каждые 25м"],[200,"8х25м кроль i30: со старта — акцент на сильный толчок от тумбочки, дальше спокойно"]],main:[[150,"6х25м основным стилем со старта, отдых 60 сек: прыжок, подводная часть до 10 метров и 3 гребка в полную силу, дальше до 25 метров спокойно"],[200,"200м откупка: 100м на спине двумя руками одновременно + 100м кроль длинным гребком"],[200,"4х50м основным стилем со старта, отдых 60 сек: прыжок, подводная часть до 10 метров и 5 гребков быстро, дальше спокойно"],[150,"150м откупка: 50м брасс с долгим скольжением + 100м спина спокойно"],[200,"4х50м основным стилем со старта, отдых 90 сек: 1-я — 10м подводная часть и 3 гребка быстро, 2-я — 25м быстро + 25м спокойно, 3-я — 35м быстро + 15м спокойно, 4-я — 50м быстро","Каждая следующая пятидесятка держит скорость дольше предыдущей. Если четвёртая разваливается — значит, третья уже была на пределе, и в следующий раз лесенку стоит начать спокойнее."],[100,"100м откупка: кроль в лёгком темпе, дыхание на 3 гребка"]],cool:[[200,"200м спокойно: 100м спина + 100м брасс с долгим скольжением"],[100,"4х25м скольжения от бортика до полной остановки, руки в стрелке"]]},
      {n:8,vol:2250,note:"Три разных переключения: ступенями внутри серии, между быстрым и спокойным внутри отрезка и м…",story:"Три разных переключения: ступенями внутри серии, между быстрым и спокойным внутри отрезка и между стилями на ходу. Спокойные участки — не отдых, а проверка, умеете ли вы сбрасывать усилие, не теряя положения.",warm:[[200,"200м спокойно: 50м дельфин + 50м спина + 50м брасс + 50м кроль"],[200,"200м ноги дельфин в ластах, i30"],[200,"8х25м i20: через одну — дельфин и кроль"]],main:[[400,"4 серии по 4х25м i30, каждая серия своим стилем — дельфин, спина, брасс, кроль: 1-й отрезок спокойно, 2-й средне, 3-й быстро, 4-й максимум","Ступени должны быть ровными: разница между соседними примерно одинаковая. Если первый отрезок уже быстрый, расти некуда — начинайте спокойнее, чем кажется нужным."],[200,"200м откупка: 100м на спине двумя руками одновременно + 100м кроль длинным гребком"],[300,"4х75м основным стилем, отдых 45 сек: 25м быстро / 25м спокойно / 25м быстро","Спокойный участок — не отдых, а удержание положения. Тело остаётся высоко, гребок длинный. Если провалились — второе ускорение уже не получится."],[150,"150м откупка: 50м брасс с долгим скольжением + 100м спина спокойно"],[100,"2х50м, отдых 45 сек: 25м дельфин в полную силу + 25м основным стилем спокойно"],[100,"100м откупка: кроль в лёгком темпе, дыхание на 3 гребка"]],cool:[[200,"200м спокойно: 100м спина + 100м брасс с долгим скольжением"],[100,"100м кроль на минимальное число гребков"],[100,"4х25м скольжения от бортика до полной остановки, руки в стрелке"]]},
      {n:9,vol:2100,note:"Каждый вдох в спринте стоит скорости, и задача не убрать его, а сделать дешевле",story:"Каждый вдох в спринте стоит скорости, и задача не убрать его, а сделать дешевле. Три способа: реже дышать на коротком отрезке, дышать в обе стороны и не дышать на последних метрах перед стенкой. Долгих задержек здесь нет — всё на коротком.",warm:[[200,"200м спокойно: 100м кроль, вдох в обе стороны + 100м спина"],[200,"4х50м кроль i30: через одну — дыхание 3/3 и дыхание 5/5"],[200,"8х25м кроль i20: через одну — на задержке дыхания и с произвольным дыханием"]],main:[[150,"6х25м основным стилем, отдых 40 сек: два вдоха на отрезок, в полную силу","На двадцати пяти метрах два вдоха — это немного, но выполнимо. Если начали задыхаться, дышите три раза: терпеть здесь нечего, задача в скорости, а не в задержке."],[150,"150м откупка: 50м брасс с долгим скольжением + 100м спина спокойно"],[200,"4х50м основным стилем, отдых 45 сек: вдох строго в обе стороны, через три гребка, быстро","Слабая сторона вылезет сразу — на неё и смотрим. Если на одну сторону вдох получается длиннее, там теряется и гребок."],[150,"150м откупка: 50м ноги брасс на спине, руки в стрелке + 100м кроль в лёгком темпе"],[200,"4х50м основным стилем, отдых 45 сек: последние 10м без дыхания, в полную силу","Десять метров без вдоха перед стенкой — это всё, что нужно на финише. Вдох в последних метрах поднимает голову и стоит больше, чем даёт."],[150,"150м откупка: кроль в лёгком темпе, дыхание свободное"],[100,"2х50м основным стилем, отдых 60 сек: в полную силу, дыхание привычное"],[100,"100м откупка: 50м на спине двумя руками одновременно + 50м брасс на скольжение"]],cool:[[200,"200м спокойно: 100м спина + 100м брасс с долгим скольжением"],[100,"4х25м скольжения от бортика до полной остановки, руки в стрелке"]]},
      {n:10,vol:2250,note:"Финиш тренируют реже всего: до него доходят уже уставшими",story:"Финиш тренируют реже всего: до него доходят уже уставшими. Сегодня он стоит в середине, на свежих руках, и разбирается по частям — не сбавить перед стенкой, не вдохнуть в последних метрах, дотянуться до касания.",warm:[[200,"200м спокойно: 100м кроль + 100м брасс на длинное скольжение"],[200,"200м кроль i30: последние 10м каждые 50 метров чуть быстрее"],[200,"200м ноги дельфин в ластах, i30"],[100,"4х25м основным стилем i20: финиш с ускорением"]],main:[[300,"6х50м, отдых 45 сек: 35м кроль свободно + 15м в полную силу основным стилем на финиш","Ускорение начинается не от стенки, а заранее: если включаться на последних трёх метрах, разгоняться уже некогда."],[150,"150м откупка: 50м брасс с долгим скольжением + 100м спина спокойно"],[100,"4х25м основным стилем, отдых 45 сек: в полную силу, последние 5м без дыхания","Вдох перед самой стенкой поднимает голову и тормозит сильнее, чем кажется. Касаемся вытянутой рукой, не подгребая под себя."],[100,"100м откупка: 50м ноги брасс на спине, руки в стрелке + 50м кроль в лёгком темпе"],[200,"2х100м, отдых 60 сек: 75м кроль ровно + 25м в полную силу основным стилем","Здесь финиш длиннее, и удержать его тяжелее."],[100,"100м откупка: кроль в лёгком темпе, дыхание свободное"],[200,"4х50м, отдых 30 сек: 35м кроль свободно + 15м в полную силу основным стилем на финиш","Та же серия, что в начале, но на уставших руках и с коротким отдыхом — именно так финиш выглядит в заплыве."]],cool:[[200,"200м спокойно: 100м спина + 100м брасс с долгим скольжением"],[100,"100м кроль на минимальное число гребков"],[100,"4х25м скольжения от бортика до полной остановки, руки в стрелке"]]},
      {n:11,vol:2100,note:"Колобашка выключает ноги, и вся скорость остаётся на руках",story:"Колобашка выключает ноги, и вся скорость остаётся на руках. Без неё тренировки нет — на быстром отрезке ноги включаются сами, и проверить руки не получится. В конце серия в полной координации: по разнице станет видно, сколько добавляют ноги.",warm:[[200,"200м спокойно: 100м спина в полной координации + 100м брасс на минимальное число гребков"],[200,"200м руки кроль с колобашкой спокойно — настраиваем захват"],[200,"8х25м i20: через одну — упражнение на кроль «плавание на кулаках» и кроль свободно"],[100,"4х25м руки кроль с колобашкой i20, в прогресс"]],main:[[200,"8х25м руки кроль с колобашкой, отдых 40 сек: каждая 3-я в полную силу, остальные спокойно","Без ног таз проваливается. Держите его у поверхности напряжением живота: если тело складывается, гребок толкает воду вниз, а не назад."],[150,"150м откупка: 50м брасс с долгим скольжением + 100м спина спокойно"],[200,"4х50м руки кроль с колобашкой и в маленьких лопатках, отдых 45 сек: 25м максимум + 25м свободно","С лопатками легко протащить воду прямой рукой. Локоть остаётся выше кисти."],[150,"150м откупка: 50м ноги брасс на спине, руки в стрелке + 100м кроль в лёгком темпе"],[100,"2х50м руки кроль с колобашкой без лопаток, отдых 60 сек, в полную силу","Ради этой серии лопатки и надевались. Если без них рука проскальзывает, значит захват держался на инвентаре."],[100,"100м откупка: кроль в лёгком темпе, дыхание свободное"],[100,"2х50м основным стилем в полной координации, отдых 60 сек, в полную силу","Колобашку снимаем. Разница с предыдущей серией — вклад ног."]],cool:[[200,"200м спокойно: 100м спина + 100м брасс с долгим скольжением"],[100,"100м кроль на минимальное число гребков"],[100,"4х25м скольжения от бортика до полной остановки, руки в стрелке"]]},
      {n:12,vol:2200,note:"Ласты дают скорость выше собственной, и тело запоминает частоту гребка на этой скорости",story:"Ласты дают скорость выше собственной, и тело запоминает частоту гребка на этой скорости. Запоминает ненадолго, поэтому отрезки чередуются: в ластах и сразу без них, ласты снимаются в паузе.",warm:[[200,"200м спокойно: 4х50м — кроль, спина, брасс, кроль, дыхание свободное"],[200,"200м ноги дельфин в ластах на спине, руки в стрелке, i30"],[200,"4х50м основным стилем в ластах в прогресс, i30"],[100,"4х25м в ластах i20: через одну — проныр дельфином под водой и кроль"]],main:[[200,"8х25м основным стилем в ластах, отдых 40 сек: в полную силу с высокой частотой гребка"],[200,"200м откупка: 100м брасс с долгим скольжением + 100м спина, ноги мягко"],[300,"6х50м, отдых 60 сек: нечётные в ластах, чётные без ласт, все в полную силу основным стилем"],[200,"200м откупка: 100м на спине двумя руками одновременно + 100м кроль длинным гребком"],[100,"2х50м основным стилем без ласт, отдых 60 сек: в полную силу"],[100,"100м откупка: на спине, руки вдоль тела, ноги мягко"]],cool:[[200,"200м спокойно: 4х50м — брасс, спина, кроль, спина"],[100,"100м руки кроль с колобашкой спокойно"],[100,"4х25м скольжения от бортика до полной остановки, руки в стрелке"]]},
      {n:13,vol:2350,note:"Скорость — это частота гребка, умноженная на его длину, и улучшать их по отдельности бесполез…",story:"Скорость — это частота гребка, умноженная на его длину, и улучшать их по отдельности бесполезно: одно съедает другое. Сегодня разводим по разным сериям, а в конце сводим. Считаем гребки — часы не нужны.",warm:[[200,"200м спокойно: 100м кроль + 100м на спине двумя руками одновременно"],[200,"200м спокойно: 100м ноги дельфин на спине, руки в стрелке + 100м кроль"],[200,"4х50м кроль i30 на минимальное число гребков"],[100,"4х25м кроль i20: через одну — на минимум гребков и на задержке дыхания"]],main:[[300,"6х50м основным стилем, режим 1:30: на минимальное число гребков","Запомните число — оно понадобится в конце. Гребков становится меньше за счёт вытягивания вперёд, а не за счёт паузы после гребка."],[200,"200м откупка: 100м спина спокойно + 100м брасс с долгим скольжением"],[150,"6х25м основным стилем, отдых 40 сек: через одну — на минимальное число гребков и максимально быстро, разгоняем темп","Два соседних отрезка про противоположное, и переключаться приходится сразу. На быстром продвижение упадёт — это нормально."],[200,"200м откупка: 50м ноги брасс на спине, руки в стрелке + 150м кроль в лёгком темпе"],[300,"6х50м основным стилем, режим 1:20: держим число гребков из первой серии","Здесь всё и сходится: то же число гребков, но в режиме, который заставляет торопиться."],[100,"100м откупка: на спине, руки вдоль тела, ноги мягко"]],cool:[[200,"4х50м кроль на минимальное число гребков, i20"],[100,"100м брасс с долгим скольжением"],[100,"4х25м скольжения от бортика до полной остановки, руки в стрелке"]]},
      {n:14,vol:2300,note:"В комплексе секунды теряются не в стилях, а на переходах между ними",story:"В комплексе секунды теряются не в стилях, а на переходах между ними. Переход — это одно касание и один разворот, но делать его приходится на скорости и уставшим. Сегодня разбираем все три перехода по очереди, а в конце собираем в сотню.",warm:[[200,"200м спокойно: 100м брасс + 100м спина, следим за длиной скольжения"],[200,"200м комплекс по 50м в порядке комплекса: дельфин — спина — брасс — кроль, спокойно"],[200,"200м ноги комплекс без доски: дельфин — спина — брасс — кроль по 50м, i30"],[100,"4х25м i20: по одному отрезку каждым стилем в порядке комплекса"]],main:[[200,"4х50м, режим 1:45: 25м дельфин в полную силу + 25м спина спокойно — работаем переход"],[150,"150м откупка: 50м брасс с долгим скольжением + 100м спина спокойно"],[200,"4х50м, режим 1:45: 25м спина в полную силу + 25м брасс спокойно — работаем переход"],[150,"150м откупка: 50м ноги брасс на спине, руки в стрелке + 100м кроль в лёгком темпе"],[200,"4х50м, режим 1:45: 25м брасс в полную силу + 25м кроль спокойно — работаем переход"],[100,"100м откупка: на спине, руки вдоль тела, ноги мягко"],[200,"2х100м комплекс, отдых 90 сек: последние 5м каждого стиля и первые 5м следующего — в полную силу","Три перехода подряд, и к третьему уже тяжело — там обычно и теряется больше всего."]],cool:[[200,"200м спокойно: 100м кроль на минимальное число гребков + 100м спина, руки вдоль тела"],[100,"100м брасс с долгим скольжением"],[100,"4х25м скольжения от бортика до полной остановки, руки в стрелке"]]},
      {n:15,vol:2200,note:"До этого каждый быстрый отрезок начинался на свежих силах",story:"До этого каждый быстрый отрезок начинался на свежих силах. На дистанции так не бывает: второй отрезок всегда идёт на неубранном дыхании. Сегодня отдых убывает от серии к серии, а в конце исчезает совсем. Задача — не дотерпеть, а не дать скорости просесть.",warm:[[300,"300м спокойно: 100м кроль + 100м спина + 100м брасс"],[200,"200м ноги дельфин в ластах на спине, руки в стрелке, i30"],[200,"8х25м i20: через одну — кроль свободно и основным стилем с ускорением на последних 10м"]],main:[[150,"6х25м основным стилем, все в полную силу. Отдых убывает: первые две по 45 сек, вторые две по 30, последние две по 20","Скорость должна остаться одинаковой, а отдыха становится всё меньше. К последней паре дыхание уже не возвращается — это и есть работа."],[350,"350м откупка: 100м спина спокойно + 100м брасс с долгим скольжением + 150м кроль в лёгком темпе"],[200,"2х100м, отдых 30 сек: 75м кроль ровно + 25м в полную силу основным стилем","Вторая сотня начинается на неубранном дыхании. Последние двадцать пять метров в обеих должны быть одинаковыми."],[200,"200м откупка: 100м ноги брасс на спине, руки в стрелке + 100м кроль в лёгком темпе"],[100,"100м без отдыха: каждые 25м — первые 10м в полную силу основным стилем, дальше кроль свободно","Пауз нет. Ускорение включается из движения и на усталости."],[100,"100м откупка: на спине, руки вдоль тела, ноги мягко"]],cool:[[200,"200м спокойно: 100м спина + 100м брасс с долгим скольжением"],[100,"100м кроль на минимальное число гребков"],[100,"4х25м скольжения от бортика до полной остановки, руки в стрелке"]]}
    ]},
    sk_p:{level:"Продвинутый",vol:"2200–3000 м",w:[
      {n:1,vol:2400,note:"Самая честная скоростная тренировка: короткие отрезки, полный отдых, максимальная скорость",story:"Самая честная скоростная тренировка: короткие отрезки, полный отдых, максимальная скорость. Первая половина кролем, вторая — основным стилем. Задача не терпеть, а каждый раз стартовать свежим: если время падает к концу серии, не хватило отдыха, а не характера.",warm:[[null,"300м спокойно: 100м кроль + 100м спина + 100м брасс"],[null,"8х25м i20: нечётные — упражнение на брасс «руки брасс / ноги кроль», чётные — брасс на минимальное число гребков"],[null,"4х50м ноги кроль в ластах, в прогресс от первой к четвёртой, режим 1:15"],[null,"200м на спине двумя руками одновременно"]],main:[[null,"8х25м основным стилем, режим 1:15: нечётные максимально быстро, чётные спокойно","Считайте гребки. К концу серии их число не должно вырасти больше чем на один-два: если выросло, скорость держится частотой, а гребок уже разваливается."],[null,"300м откупка: 100м на спине двумя руками одновременно + 100м брасс с долгим скольжением + 100м кроль длинным гребком"],[null,"4х50м основной стиль в полную силу, режим 2:00","На своём стиле техника рассыпается первой. Следите за длиной гребка, а не за частотой: на дистанции выигрывает тот, кто на скорости остаётся техничным."],[null,"200м откупка: 100м на спине двумя руками одновременно + 100м кроль длинным гребком — дыхание свободное"],[null,"4х50м, режим 1:30: 25м максимум основным стилем + 25м кроль свободно","Вторая половина — не выключение, а спокойное продолжение. Тело остаётся вытянутым, гребок длинным: учимся сбрасывать усилие, не теряя положения."]],cool:[[null,"100м спина спокойно, руки вдоль тела"],[null,"4х50м кроль на минимальное число гребков, i20 — не разгоняясь, только за счёт длины"],[null,"100м произвольно, дыхание свободное"]]},
      {n:2,vol:2200,note:"Ноги дают до трети скорости в спринте, но тренируют их обычно медленно и долго",story:"Ноги дают до трети скорости в спринте, но тренируют их обычно медленно и долго. Здесь наоборот: короткие максимальные отрезки, предельная частота и разные положения тела. После такой тренировки обычный кроль ощущается легче, потому что ноги перестают быть тормозом и начинают толкать.",warm:[[null,"300м спокойно: 150м кроль + 150м спина"],[null,"200м ноги с доской спокойно: 100м кроль + 100м брасс"],[null,"4х50м ноги кроль в ластах в прогресс, i30"],[null,"4х25м ноги брасс на спине, руки вдоль туловища, i20"]],main:[[null,"12х25м ноги кроль без доски на 90% от максимума, режим 1:15"],[null,"200м откупка: 100м брасс с долгим скольжением + 100м спина, ноги мягко"],[null,"6х50м ноги с доской, режим 1:30: 25м дельфин на груди максимум + 25м на спине свободно","Дельфин на максимуме идёт от груди и таза, а не от коленей. Стопы вместе, амплитуда небольшая — так удар получается быстрым, а не размашистым."],[null,"200м откупка: 50м ноги брасс на спине, руки в стрелке + 150м кроль в лёгком темпе"]],cool:[[null,"200м спина: работа двумя руками одновременно, ноги почти без усилия"],[null,"100м брасс с долгим скольжением"],[null,"100м произвольно спокойно"]]},
      {n:3,vol:2600,note:"Спринт выигрывается в первые секунды, а тренируют обычно всё остальное",story:"Спринт выигрывается в первые секунды, а тренируют обычно всё остальное. Сегодня разгон разбирается на части: с места, из-под воды, по гребкам и на поворот — а в конце собирается обратно внутри длинного отрезка. Отдых полный и в секундах, а не по режиму: если очередной отрезок медленнее предыдущего, вы тренируете уже терпение, а не скорость.",warm:[[null,"400м спокойно: 100м кроль + 100м спина + 100м брасс + 100м кроль на минимальное число гребков"],[null,"8х25м в ластах, i20: толчок, 7 ударов дельфином под водой, выход и до стенки быстро (без ласт — 10 ударов)"],[null,"4х25м основным стилем с места, i30: вытянуться в стрелку у бортика, толчка нет — первые 5 гребков в полную силу, дальше свободно"]],main:[[null,"8х25м основным стилем с места, отдых 45 сек: вытянуться в стрелку у бортика, ноги стенки не касаются — толчка нет, разгон только руками, до стенки максимум","Стенка не помогает — видно чистую работу рук. Первые три гребка короткие и частые: длинный гребок появляется, только когда скорость уже набрана. Если к концу серии отрезок ощущается заметно тяжелее, отдыхайте дольше."],[null,"200м откупка: 100м спина спокойно + 100м брасс на длинное скольжение"],[null,"6х50м с толчка, отдых 60 сек: под водой 10–12м дельфином, выход и 15м максимум без дыхания, остаток свободно","Выход из-под воды — единственное место, где вы плывёте быстрее, чем умеете. Вдох на первых пятнадцати метрах гасит скорость сильнее, чем экономит силы."],[null,"100м откупка: кроль в лёгком темпе, дыхание на 3 гребка — расслабить плечи"],[null,"4х50м основным стилем по гребкам, отдых 60 сек: 5 гребков на 80%, 5 на 90%, дальше максимум до 25 метров","Отрезок делится не метрами, а гребками, и переключаться приходится по ощущению. Сбились со счёта — серия превратилась в обычный полтинник."],[null,"100м откупка: на спине, руки вдоль тела, ноги мягко — не разгоняться"],[null,"4х50м основным стилем на поворот, отдых 60 сек: 10м до стенки и 10м после — максимум, остальное свободно","Поворот — половина дистанции в коротком бассейне. Вход делаем на скорости: тормозить перед стенкой привычнее, но именно это и стоит секунд."],[null,"300м основным стилем: первые 10м каждой сотни в полную силу, дальше свободно","Сборка. Задача не проплыть сотню быстро, а каждый раз выйти на скорость заново и не потерять положение тела, когда усилие сбрасывается."]],cool:[[null,"200м в трубке спокойно: 100м ноги брасс + 100м ноги кроль"],[null,"100м на спине двумя руками одновременно, спокойно"]]},
      {n:4,vol:2500,note:"Скорость — это в первую очередь ощущение, а ощущение нужно чем-то сдвинуть",story:"Скорость — это в первую очередь ощущение, а ощущение нужно чем-то сдвинуть. Сегодня три круга одной и той же серии: с сопротивлением, без ничего и в ластах. Смысл не в том, чтобы устать, а в том, что происходит между кругами: чистый круг после тяжёлого ощущается легче, а после ластов обычная скорость кажется медленной. Последняя серия проверяет, осталось ли что-нибудь от этого ощущения.",warm:[[null,"200м по 50м: кроль с дыханием 3/3 + кроль с дыханием 5/5 + кроль с дыханием 7/7 + спина в полной координации"],[null,"8х25м i20: через одну — кроль на минимальное число гребков и ноги кроль, руки в стрелке"],[null,"200м ноги дельфин на спине в ластах, i30"]],main:[[null,"6х50м с парашютом, отдых 45 сек: 25м в полную силу основным стилем + 25м кроль свободно","С сопротивлением гребок сам становится длиннее и медленнее. Задача обратная: удержать привычную частоту, даже если продвижение почти пропало."],[null,"100м откупка: на спине, руки вдоль тела, ноги мягко"],[null,"6х50м без инвентаря, отдых 45 сек: 25м в полную силу основным стилем + 25м кроль свободно","Тот же отрезок без сопротивления. Первые метры будут казаться пустыми — это нормально, вода никуда не делась, просто рука привыкла к большему."],[null,"100м откупка: 50м брасс на скольжение + 50м спина спокойно"],[null,"6х50м в ластах, отдых 45 сек: 25м в полную силу основным стилем + 25м кроль свободно","Здесь вы плывёте быстрее, чем умеете. Ласты нужны не для ног, а чтобы тело побывало на скорости, которой само не даёт. Гребок держим тем же, не частим."],[null,"100м откупка: кроль в лёгком темпе, дыхание на 3 гребка"],[null,"4х50м основным стилем без инвентаря, отдых 60 сек, в полную силу","Проверка. Если после ластов полтинник ощущается быстрее обычного — это и есть результат тренировки, и держится он примерно двадцать минут."],[null,"200м кроль свободно: держим ту частоту, что была в ластах","Не скорость, а именно частоту. Скорость упадёт сама, а привычка к частому гребку — то, что стоит унести из воды."]],cool:[[null,"200м спокойно: 100м спина + 100м брасс с долгим скольжением"],[null,"100м на спине, руки вдоль тела, ноги мягко"]]},
      {n:5,vol:2300,note:"В 25-метровом бассейне поворотов больше, чем прямых кусков, но тренируют обычно только прямые",story:"В 25-метровом бассейне поворотов больше, чем прямых кусков, но тренируют обычно только прямые. Сегодня стенка разобрана на части: сам разворот, заход, выход — и в конце сотни, где всё это встречается три раза подряд. Скорость здесь почти не стоит сил: вы не плывёте быстрее, вы просто перестаёте тормозить.",warm:[[null,"200м по 50м: дельфин — спина — брасс — кроль, спокойно"],[null,"200м ноги дельфин на спине, руки в стрелке, i30 — готовим ноги к работе под водой"],[null,"8х25м i20: подход к стенке спокойно, кувырок и толчок в полную силу, 5 ударов дельфином под водой быстро, дальше свободно"]],main:[[null,"4х50м основным стилем «пятёрка вокруг стенки», отдых 40 сек: 5м до поворота и 5м после — в полную силу, остальное свободно"],[null,"100м откупка: на спине, руки вдоль тела, ноги мягко"],[null,"6х50м основным стилем, отдых 45 сек: первые 25м спокойно, вторые 25м в полную силу — работаем выход","Скорость второй половины закладывается до стенки."],[null,"100м откупка: 50м брасс на скольжение + 50м спина спокойно"],[null,"6х50м основным стилем, отдых 45 сек: первые 25м в полную силу, вторые 25м спокойно — работаем заход","Самая частая ошибка — сбросить скорость перед стенкой, чтобы «удобно» развернуться. Заходим на полном ходу, стопы ставим на глубине 30–40 см."],[null,"100м откупка: кроль в лёгком темпе, дыхание на 3 гребка"],[null,"3х100м основным стилем, отдых 60 сек: вокруг каждого поворота 10м до и 10м после в полную силу, остальное свободно","В сотне три поворота — три шанса. К третьему станет тяжело, и сдаёт обычно заход: подплывать начинаешь, а не влетать."]],cool:[[null,"200м спокойно: 100м спина + 100м брасс с долгим скольжением"],[null,"4х25м скольжения от бортика до полной остановки, руки в стрелке"]]},
      {n:6,vol:2500,note:"Максимум держится секунд десять, дальше начинается терпение",story:"Максимум держится секунд десять, дальше начинается терпение. Дробные отрезки обходят это: сотня разбивается паузами, и каждый кусок остаётся настоящим спринтом, а не доживанием. Каждая дробная делается один раз — повторить её по-настоящему всё равно не выйдет, а вполсилы значит потерять смысл. Поэтому между ними много спокойного плавания: оно здесь не добивка объёма, а условие, без которого следующая сотня не получится.",warm:[[null,"200м спокойно: 100м кроль, вдох в обе стороны + 100м брасс на скольжение"],[null,"8х25м основным стилем i20: через одну — свободно и с ускорением на последних 10м"],[null,"4х50м основным стилем i30, в прогресс от первой к четвёртой"]],main:[[null,"100м основным стилем дробно: 4х25м в полную силу с паузой 10 секунд после каждых 25м","Пауза короткая — ровно чтобы оттолкнуться от стенки заново. Задача проплыть четвёртый четвертак так же, как первый: здесь проверяется не сила, а то, насколько ровно держится скорость."],[null,"300м откупка: 100м на спине двумя руками одновременно + 100м брасс с долгим скольжением + 100м кроль длинным гребком"],[null,"100м основным стилем дробно: 2х50м в полную силу с паузой 15 секунд","Пауз меньше, куски длиннее — держать тяжелее. Второй полтинник не должен просесть по длине гребка больше чем на пару гребков."],[null,"300м откупка: 150м спина спокойно + 150м кроль в лёгком темпе, дыхание свободное"],[null,"100м основным стилем в полную силу целиком, отдых до полного восстановления","Та же сотня, но без пауз, и ощущается она совсем иначе. Чем ближе это ощущение к дробной, тем лучше скорость держится на дистанции."],[null,"300м откупка: 100м ноги брасс на спине, руки в стрелке + 200м кроль в лёгком темпе"],[null,"4х50м, отдых 60 сек: 25м максимум основным стилем + 25м кроль свободно","Короткий сброс после тяжёлой работы — напоминаем телу, что такое чистый максимум без накопленной усталости."],[null,"200м откупка: 100м кроль на минимальное число гребков + 100м спина, руки вдоль тела"]],cool:[[null,"200м спокойно: 100м спина + 100м брасс с долгим скольжением"],[null,"100м на спине двумя руками одновременно, спокойно"]]},
      {n:7,vol:2400,note:"Старт — единственные секунды заплыва, когда вы движетесь быстрее, чем способны плыть",story:"Старт — единственные секунды заплыва, когда вы движетесь быстрее, чем способны плыть. Дальше эта скорость только теряется, и вопрос лишь в том, как медленно. Сегодня разбираем её по частям: толчок от тумбочки, вход в воду, подводная часть и первые гребки. Считаем не время, а метры и гребки — это видно самому.",warm:[[null,"200м спокойно: 100м кроль + 100м брасс на длинное скольжение"],[null,"200м ноги дельфин в ластах на боку, смена стороны каждые 25м"],[null,"8х25м кроль i30: со старта — акцент на сильный толчок от тумбочки, дальше спокойно"]],main:[[null,"8х25м основным стилем со старта, отдых 60 сек: прыжок, подводная часть до 15 метров и 3 гребка в полную силу, дальше до 25 метров спокойно"],[null,"300м откупка: 100м на спине двумя руками одновременно + 100м брасс с долгим скольжением + 100м кроль длинным гребком"],[null,"6х50м основным стилем со старта, отдых 60 сек: прыжок, подводная часть до 15 метров и 7 гребков быстро, дальше доплываем спокойно"],[null,"300м откупка: 150м спина спокойно + 150м кроль в лёгком темпе"],[null,"4х50м основным стилем со старта, отдых 90 сек: 1-я — 15м подводная часть и 3 гребка быстро, 2-я — 25м быстро + 25м спокойно, 3-я — 35м быстро + 15м спокойно, 4-я — 50м быстро","Каждая следующая пятидесятка держит скорость дольше предыдущей. Если четвёртая разваливается — значит, третья уже была на пределе, и в следующий раз лесенку стоит начать спокойнее."],[null,"200м откупка: 100м ноги брасс на спине, руки в стрелке + 100м кроль в лёгком темпе"]],cool:[[null,"200м спокойно: 100м спина + 100м брасс с долгим скольжением"],[null,"4х25м скольжения от бортика до полной остановки, руки в стрелке"]]},
      {n:8,vol:2600,note:"Разогнаться умеют все, а вот менять скорость на ходу — почти никто",story:"Разогнаться умеют все, а вот менять скорость на ходу — почти никто. Сегодня три разных переключения: ступенями внутри серии, между быстрым и спокойным внутри одного отрезка и между стилями на полном ходу. Спокойные участки здесь не отдых — это проверка, умеете ли вы сбрасывать усилие, не разваливая положение тела.",warm:[[null,"200м спокойно: 50м дельфин + 50м спина + 50м брасс + 50м кроль"],[null,"200м ноги дельфин в ластах, i30"],[null,"8х25м i20: через одну — дельфин и кроль"]],main:[[null,"4 серии по 4х25м i30, каждая серия своим стилем — дельфин, спина, брасс, кроль: 1-й отрезок спокойно, 2-й средне, 3-й быстро, 4-й максимум","Ступени должны быть ровными: разница между соседними примерно одинаковая. Если первый отрезок уже быстрый, расти некуда — начинайте спокойнее, чем кажется нужным."],[null,"200м откупка: 100м на спине двумя руками одновременно + 100м кроль длинным гребком"],[null,"6х75м основным стилем, отдых 45 сек: 25м быстро / 25м спокойно / 25м быстро","Спокойный участок — не отдых, а удержание положения. Тело остаётся высоко, гребок длинный. Если провалились — второе ускорение уже не получится."],[null,"150м откупка: 50м брасс с долгим скольжением + 100м спина спокойно"],[null,"4х50м, отдых 45 сек: 25м дельфин в полную силу + 25м основным стилем спокойно"],[null,"200м откупка: 100м ноги брасс на спине, руки в стрелке + 100м кроль в лёгком темпе"]],cool:[[null,"200м спокойно: 100м спина + 100м брасс с долгим скольжением"],[null,"100м кроль на минимальное число гребков"],[null,"4х25м скольжения от бортика до полной остановки, руки в стрелке"]]},
      {n:9,vol:2400,note:"Каждый вдох в спринте стоит скорости: голова поворачивается, тело качается, гребок на эту дол…",story:"Каждый вдох в спринте стоит скорости: голова поворачивается, тело качается, гребок на эту долю секунды становится короче. Убрать дыхание совсем нельзя, а вот сделать его дешевле — можно. Сегодня четыре способа: реже дышать на коротком, дышать в обе стороны, не дышать на последних метрах и держать привычный ритм, когда тяжело. Задерживать дыхание надолго не нужно нигде — работаем на коротких отрезках, где это безопасно.",warm:[[null,"200м спокойно: 100м кроль, вдох в обе стороны + 100м спина"],[null,"4х50м кроль i30: через одну — дыхание 3/3 и дыхание 5/5"],[null,"8х25м кроль i20: через одну — на задержке дыхания и с произвольным дыханием"]],main:[[null,"8х25м основным стилем, отдых 40 сек: два вдоха на отрезок, в полную силу","На двадцати пяти метрах два вдоха — это немного, но выполнимо. Если к концу серии начали задыхаться, дышите три раза: терпеть здесь нечего, задача в скорости, а не в задержке."],[null,"200м откупка: 100м спина спокойно + 100м брасс с долгим скольжением"],[null,"6х50м основным стилем, отдых 45 сек: вдох строго в обе стороны, через три гребка, быстро","Слабая сторона вылезет сразу — на неё и смотрим. Если на одну сторону вдох получается длиннее, там теряется и гребок."],[null,"150м откупка: 50м ноги брасс на спине, руки в стрелке + 100м кроль в лёгком темпе"],[null,"6х50м основным стилем, отдых 45 сек: последние 10м без дыхания, в полную силу","Десять метров без вдоха перед стенкой — это всё, что нужно на финише. Вдох в последних метрах поднимает голову и стоит больше, чем даёт."],[null,"150м откупка: 50м брасс на скольжение + 100м спина спокойно"],[null,"4х50м основным стилем, отдых 60 сек: в полную силу, дыхание привычное, не задерживая","Последняя серия — без всяких условий на дыхание. Проверяем, осталась ли скорость, когда дышать можно свободно."]],cool:[[null,"200м спокойно: 100м спина + 100м брасс с долгим скольжением"],[null,"4х25м скольжения от бортика до полной остановки, руки в стрелке"]]},
      {n:10,vol:3000,note:"Заплыв выигрывается на последних метрах, а тренируют их реже всего: к концу тренировки сил уж…",story:"Заплыв выигрывается на последних метрах, а тренируют их реже всего: к концу тренировки сил уже нет, и финиш отрабатывается уставшим и вяло. Сегодня наоборот — финиш стоит в середине, на свежих руках. Четыре вещи, которые его решают: не сбавить перед стенкой, не вдохнуть в последних метрах, дотянуться до касания и уметь всё это на усталых руках.",warm:[[null,"200м спокойно: 100м кроль + 100м брасс на длинное скольжение"],[null,"200м кроль i30: последние 10м каждые 50 метров чуть быстрее"],[null,"200м ноги дельфин в ластах, i30"],[null,"4х25м основным стилем i20: финиш с ускорением"]],main:[[null,"8х50м, отдых 45 сек: 35м кроль свободно + 15м в полную силу основным стилем на финиш","Ускорение начинается не от стенки, а заранее: если включаться на последних трёх метрах, разгоняться уже некогда."],[null,"200м откупка: 100м спина спокойно + 100м брасс с долгим скольжением"],[null,"6х25м основным стилем, отдых 45 сек: в полную силу, последние 5м без дыхания","Вдох перед самой стенкой поднимает голову и тормозит сильнее, чем кажется. Касаемся вытянутой рукой, не подгребая под себя."],[null,"150м откупка: 50м ноги брасс на спине, руки в стрелке + 100м кроль в лёгком темпе"],[null,"4х100м, отдых 60 сек: 75м кроль ровно + 25м в полную силу основным стилем","Здесь финиш длиннее, и удержать его тяжелее."],[null,"200м откупка: 150м спина спокойно + 50м брасс на скольжение"],[null,"6х50м, отдых 30 сек: 35м кроль свободно + 15м в полную силу основным стилем на финиш","Та же серия, что в начале, но на уставших руках и с коротким отдыхом. Именно так финиш и выглядит в заплыве — в конце, а не на свежих силах."],[null,"100м откупка: кроль в лёгком темпе, дыхание свободное"]],cool:[[null,"200м спокойно: 100м спина + 100м брасс с долгим скольжением"],[null,"100м кроль на минимальное число гребков"],[null,"4х25м скольжения от бортика до полной остановки, руки в стрелке"]]},
      {n:11,vol:2400,note:"Колобашка выключает ноги, и вся скорость остаётся на плечах и предплечьях",story:"Колобашка выключает ноги, и вся скорость остаётся на плечах и предплечьях. Это самый честный способ понять, сколько на самом деле даёт ваш гребок: без ног обмануть себя не получится. Колобашка сегодня обязательна — без неё тренировки нет, ноги сами включатся на первом же быстром отрезке. В конце одна серия в полной координации: по разнице ощущений станет понятно, сколько добавляют ноги.",warm:[[null,"200м спокойно: 100м спина в полной координации + 100м брасс на минимальное число гребков"],[null,"200м руки кроль с колобашкой спокойно — настраиваем захват"],[null,"8х25м i20: через одну — упражнение на кроль «плавание на кулаках» и кроль свободно"]],main:[[null,"12х25м руки кроль с колобашкой, отдых 40 сек: каждая 3-я в полную силу, остальные спокойно","Без ног таз проваливается. Держите его у поверхности напряжением живота — если тело складывается, гребок начинает толкать воду вниз, а не назад."],[null,"200м откупка: 100м спина спокойно + 100м брасс с долгим скольжением"],[null,"6х50м руки кроль с колобашкой и в маленьких лопатках, отдых 45 сек: 25м максимум + 25м свободно","С лопатками легко протащить воду прямой рукой. Следите за высоким локтем: кисть всегда ниже локтя, иначе гребок держится на лопатке, а не на опоре."],[null,"200м откупка: 100м ноги брасс на спине, руки в стрелке + 100м кроль в лёгком темпе"],[null,"4х50м руки кроль с колобашкой без лопаток, отдых 60 сек, в полную силу","Ради этой серии лопатки и надевались. Опора должна чувствоваться такой же — если без них рука проскальзывает, значит захват держался на инвентаре."],[null,"100м откупка: кроль в лёгком темпе, дыхание свободное"],[null,"4х50м основным стилем в полной координации, отдых 60 сек, в полную силу","Колобашку снимаем. Разница с предыдущей серией — это и есть вклад ног. У большинства он меньше, чем кажется, и это хорошая новость: значит, работать есть над чем."]],cool:[[null,"200м спокойно: 100м спина + 100м брасс с долгим скольжением"],[null,"4х25м скольжения от бортика до полной остановки, руки в стрелке"]]},
      {n:12,vol:2600,note:"Чтобы плыть быстро, нервная система должна знать, что такое быстро",story:"Чтобы плыть быстро, нервная система должна знать, что такое быстро. Ласты дают скорость выше собственной, и тело успевает запомнить частоту гребка и положение на этой скорости. Но запоминает оно ненадолго: через несколько минут ощущение уходит. Поэтому сегодня отрезки чередуются — в ластах и сразу без них, ласты снимаются в паузе.",warm:[[null,"300м спокойно: 100м кроль + 100м спина + 100м брасс"],[null,"200м ноги дельфин в ластах на спине, руки в стрелке, i30"],[null,"4х50м основным стилем в ластах в прогресс, i30"],[null,"8х25м в ластах i20: через одну — проныр дельфином под водой и кроль"]],main:[[null,"8х25м основным стилем в ластах, отдых 40 сек: в полную силу с высокой частотой гребка"],[null,"200м откупка: 100м на спине двумя руками одновременно + 100м кроль длинным гребком"],[null,"8х50м, отдых 60 сек: нечётные в ластах, чётные без ласт, все в полную силу основным стилем"],[null,"200м откупка: 100м брасс с долгим скольжением + 100м спина спокойно"],[null,"4х50м основным стилем без ласт, отдых 60 сек: в полную силу"],[null,"100м откупка: на спине, руки вдоль тела, ноги мягко"]],cool:[[null,"200м в ластах спокойно: 100м на спине + 100м кроль"],[null,"100м руки кроль с колобашкой спокойно"],[null,"4х25м скольжения от бортика до полной остановки, руки в стрелке"]]},
      {n:13,vol:2900,note:"Скорость — это частота гребка, умноженная на его длину",story:"Скорость — это частота гребка, умноженная на его длину. Обычно пловец улучшает одно за счёт другого и стоит на месте: удлинил гребок — потерял темп, зачастил — потерял продвижение. Сегодня разводим их по разным сериям, а в конце сводим обратно. Считаем только гребки: их видно самому, часы для этого не нужны.",warm:[[null,"300м спокойно: 150м кроль с подсчётом гребков + 150м спина"],[null,"200м спокойно: 100м кроль + 100м ноги брасс с доской"],[null,"4х50м кроль i30 на минимальное число гребков"],[null,"8х25м кроль i20: через одну — на минимум гребков и на задержке дыхания"]],main:[[null,"8х50м основным стилем, режим 1:30: на минимальное число гребков","Запомните это число — оно понадобится в конце. Гребков должно стать меньше за счёт вытягивания вперёд, а не за счёт паузы после гребка: пауза замедляет и не удлиняет."],[null,"200м откупка: 100м спина спокойно + 100м брасс с долгим скольжением"],[null,"8х25м основным стилем, отдых 40 сек: через одну — на минимальное число гребков и максимально быстро, разгоняем темп","Два соседних отрезка про противоположное, и переключаться приходится сразу. На быстром продвижение упадёт — это нормально, сейчас важна только частота."],[null,"200м откупка: 100м ноги брасс на спине, руки в стрелке + 100м кроль в лёгком темпе"],[null,"8х50м основным стилем, режим 1:15: держим число гребков из первой серии","Вот здесь всё и сходится: то же число гребков, но в режиме, который заставляет торопиться. Не уложились в режим — проплывите следующую полтинник спокойно и возвращайтесь."],[null,"200м откупка: 100м брасс с долгим скольжением + 100м спина спокойно"]],cool:[[null,"4х50м кроль на минимальное число гребков, i20"],[null,"100м спокойно: 50м спина, руки вдоль тела + 50м спина в полной координации"],[null,"4х25м скольжения от бортика до полной остановки, руки в стрелке"]]},
      {n:14,vol:2600,note:"В комплексе секунды теряются не в стилях, а на переходах между ними",story:"В комплексе секунды теряются не в стилях, а на переходах между ними. Переход — это одно касание и один разворот, но делать его приходится уже уставшим и на скорости, а тренируют его почти никогда. Сегодня разбираем все три перехода по очереди: перед каждой сменой стиль разгоняется до максимума, чтобы переход приходилось делать не в спокойном темпе. В конце — сотня целиком, где все три перехода встречаются подряд.",warm:[[null,"400м комплекс по 100м, спокойно"],[null,"200м ноги комплекс без доски: дельфин — спина — брасс — кроль по 50м, i30"],[null,"8х25м i20: по два отрезка каждым стилем в порядке комплекса"]],main:[[null,"6х50м, режим 1:45: 25м дельфин в полную силу + 25м спина спокойно — работаем переход"],[null,"150м откупка: 50м брасс с долгим скольжением + 100м спина спокойно"],[null,"6х50м, режим 1:45: 25м спина в полную силу + 25м брасс спокойно — работаем переход"],[null,"150м откупка: 50м ноги брасс на спине, руки в стрелке + 100м кроль в лёгком темпе"],[null,"4х50м, режим 1:45: 25м брасс в полную силу + 25м кроль спокойно — работаем переход"],[null,"100м откупка: на спине, руки вдоль тела, ноги мягко"],[null,"2х100м комплекс, отдых 90 сек: последние 5м каждого стиля и первые 5м следующего — в полную силу","Три перехода подряд, и к третьему уже тяжело — там обычно и теряется больше всего."]],cool:[[null,"200м спокойно: 4х50м — брасс, спина, кроль, спина"],[null,"100м на спине двумя руками одновременно, между гребками длинное скольжение"],[null,"4х25м скольжения от бортика до полной остановки, руки в стрелке"]]},
      {n:15,vol:2400,note:"Четырнадцать тренировок подряд вы разгонялись на свежих силах — так и надо учиться скорости",story:"Четырнадцать тренировок подряд вы разгонялись на свежих силах — так и надо учиться скорости. Но в заплыве второй отрезок всегда начинается на неубранном дыхании, а третий и подавно. Сегодня отдых убывает: начинаем с сорока пяти секунд, заканчиваем пятнадцатью, и в самом конце обходимся вообще без пауз. Задача не в том, чтобы дотерпеть, а в том, чтобы скорость не просела, когда восстановиться уже негде.",warm:[[null,"300м спокойно: 100м кроль + 100м спина + 100м брасс"],[null,"200м ноги дельфин в ластах на спине, руки в стрелке, i30"],[null,"8х25м i20: через одну — кроль свободно и основным стилем с ускорением на последних 10м"]],main:[[null,"8х25м основным стилем, все в полную силу. Отдых убывает: первые две по 45 сек, вторые две по 30, третьи по 20, последние две по 15","Скорость должна остаться одинаковой, а отдыха становится всё меньше. К последней паре дыхание уже не возвращается — вот ради этого места всё и делается."],[null,"400м откупка: 100м спина спокойно + 100м брасс с долгим скольжением + 200м кроль в лёгком темпе"],[null,"3х100м, отдых 30 сек: 75м кроль ровно + 25м в полную силу основным стилем","Каждая сотня начинается на неубранном дыхании. Последние двадцать пять метров должны быть одинаковыми во всех трёх — если третья заметно тяжелее, темп на ровной части был слишком высоким."],[null,"200м откупка: 100м ноги брасс на спине, руки в стрелке + 100м кроль в лёгком темпе"],[null,"200м без отдыха: каждые 25м — первые 10м в полную силу основным стилем, дальше кроль свободно","Пауз нет вообще. Ускорение приходится включать из движения и на усталости — ближе всего к тому, что происходит на дистанции."],[null,"100м откупка: на спине, руки вдоль тела, ноги мягко"]],cool:[[null,"200м спокойно: 100м спина + 100м брасс с долгим скольжением"],[null,"4х25м скольжения от бортика до полной остановки, руки в стрелке"]]}
    ]}
  }},
  b_mo:{name:"Мощность",lede:"Длина гребка под нагрузкой. Судья здесь не секундомер, а число гребков.",levels:{
    mo_n:{level:"Новичок",vol:"1400–1500 м",w:[
      {n:1,vol:1500,note:"Мощность — это не скорость",story:"Мощность — это не скорость. Как только пловец начинает грести изо всех сил, он почти всегда начинает рвать воду: рука проскальзывает, гребков становится больше, а вперёд вы двигаетесь хуже. Поэтому показателем здесь будет не время, а число гребков: если усилие выросло, а гребков столько же — выросла мощность. Сегодня мы эту цифру измерим в начале занятия и в конце.",warm:[[200,"200м в трубке, чередуя по 50м: на кулаках и открытой ладонью"],[100,"100м ноги кроль с доской, спокойно"],[100,"4х25м кроль i20 в прогресс"]],main:[[100,"2х50м кроль i40 на минимальное число гребков, спокойно","Считать просто: гребок — это когда рука вошла в воду. Запомните число, оно понадобится в конце."],[200,"8х25м i25 — упражнение на кроль «на боку 6 ударов, смена рук через пронос и гребок»","Лежите на боку, одна рука впереди, вторая у бедра, ноги работают. Шесть ударов — и смена: задняя рука идёт на пронос, передняя гребёт. Если на боку держаться тяжело, считайте не шесть ударов, а четыре."],[300,"6х50м руки кроль с колобашкой, i30, мощно и плавно","Ноги выключены, вперёд вас двигают только руки. Если таз проваливается — подберите живот."],[100,"100м откупка: 50м брасс с долгим скольжением + 50м спина спокойно"],[100,"2х50м основным стилем i45 — то же число гребков, что в замере, но каждый активнее"],[100,"2х50м кроль i40 на минимальное число гребков","Ваша цифра на конец занятия."]],cool:[[100,"100м спина спокойно"],[100,"100м брасс с долгим скольжением"]]},
      {n:2,vol:1400,note:"Толчок от стенки разгоняет вас быстрее, чем вы способны плыть, и первые метры каждого отрезка…",story:"Толчок от стенки разгоняет вас быстрее, чем вы способны плыть, и первые метры каждого отрезка вы едете на чужой скорости. Сегодня стенку почти везде уберём: отрезки начинаются с места, из неподвижного положения. Стронуть стоящее тело можно только гребком — ни инерция, ни скольжение тут не помогут.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[100,"2х50м i20: 25м скольжение под водой после толчка + 25м кроль свободно"],[100,"100м ноги кроль с доской, спокойно"]],main:[[100,"2х50м кроль i40 на минимальное число гребков","Та же цифра, что в первой тренировке. Запомните её, в конце сравним."],[200,"8х25м ноги дельфин в ластах i20 — первые 10м под водой после толчка, дальше на поверхности","Работа от бедра, стопа расслаблена. Колени из воды не показываются."],[200,"8х25м кроль i30 — через одну с места и с толчка","На отрезке с места держитесь за бортик, ноги висят и не упираются. Отпустили — и поехали только на руках. Отрезок с толчка покажется вдвое легче: разница и есть то, что стенка делает за вас."],[100,"100м откупка: 50м брасс с долгим скольжением + 50м спина спокойно"],[100,"2х50м основным стилем i45 — с места, считаем гребки"],[100,"100м откупка: кроль в лёгком темпе, дыхание свободное"]],cool:[[100,"100м спина спокойно"],[100,"100м брасс с долгим скольжением"]]},
      {n:3,vol:1400,note:"Про мощность почти всегда думают руками",story:"Про мощность почти всегда думают руками. Между тем ноги в кроле дают не столько тягу, сколько опору: если таз провалился, даже очень сильный гребок разворачивает вас вверх, а не толкает вперёд. Сегодня ноги работают отдельно от рук, в том числе против сопротивления — доска, поставленная вертикально, идёт перед вами как парус.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[100,"100м ноги брасс на спине, руки в стрелке, спокойно"],[100,"4х25м кроль i20 в прогресс"]],main:[[100,"100м ноги дельфин на боку, меняя бок каждые 25м","Ложитесь на бок, нижняя рука вытянута вперёд, голова лежит на плече. Движение идёт от груди и таза. Если на боку держаться тяжело — заваливайтесь чуть ближе к спине, лицо останется над водой."],[200,"4х50м ноги кроль с доской, i40 — 25м доска вертикально + 25м доска как обычно","Первые 25 метров доска стоит широкой стороной против воды, и ехать вы почти перестанете — так и задумано. На повороте кладёте её плашмя, и вторые 25 покажутся отдыхом."],[100,"100м откупка: 50м брасс с долгим скольжением + 50м спина спокойно"],[200,"8х25м ноги брасс с доской, i25 — считаем толчки"],[100,"100м откупка: кроль в лёгком темпе, дыхание свободное"],[100,"4х25м кроль в ластах i25 — мощно, в полную силу","В ластах таз поднимается сам. Запомните это ощущение."]],cool:[[100,"100м спина спокойно"],[100,"100м брасс с долгим скольжением"]]},
      {n:4,vol:1500,note:"Захват — самая недооценённая часть гребка и то место, где мощность теряется целиком",story:"Захват — самая недооценённая часть гребка и то место, где мощность теряется целиком. Большинство любителей начинает тянуть сразу после входа, прямой рукой, и первая треть гребка уходит на то, чтобы протолкнуть воду вниз, а не назад. Сегодня мы этот момент растягиваем: вставляем в него паузу. И общее правило блока: гребки считаем на каждой серии, а не только там, где это написано.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[100,"100м руки кроль с колобашкой спокойно"],[100,"4х25м кроль i20 в прогресс"]],main:[[100,"4х25м i20 — упражнение на кроль «только первая фаза гребка, двумя руками одновременно»","Вперёд вы почти не поедете, и это правильно. Ищем положение, в котором ладонь уже смотрит назад, а локоть ещё наверху. Если есть трубка — наденьте, не придётся отвлекаться на вдох."],[200,"8х25м кроль в полной координации, i30 — пауза в точке захвата на счёт «раз», дальше гребок в полную силу","Рука вошла, вытянулась вперёд, ладонь развернулась вниз — остановка на счёт «раз», и только потом гребок. Плыть станет медленнее и тяжелее: инерции больше нет, каждый гребок начинается с нуля."],[100,"100м откупка: 50м брасс с долгим скольжением + 50м спина спокойно"],[200,"8х25м кроль в маленьких лопатках, i30 — считаем гребки"],[100,"100м откупка: кроль в лёгком темпе, дыхание свободное"],[200,"8х25м кроль без лопаток, i30 — держим то же число гребков"]],cool:[[100,"100м спина спокойно"],[100,"100м брасс с долгим скольжением"]]},
      {n:5,vol:1400,note:"У любого пловца одна рука работает лучше другой, и почти никто об этом не знает: в полной коо…",story:"У любого пловца одна рука работает лучше другой, и почти никто об этом не знает: в полной координации сильная рука прикрывает слабую, и разницы не видно. Развести их просто — проплыть 50 метров одной рукой, потом другой и сравнить число гребков. Сегодня мы разрыв измеряем, целую серию плывём с лопаткой только на слабой руке и в конце меряем снова.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[100,"4х25м i20: упражнение на кроль «гребок только одной рукой», вторая рука вытянута вперёд"],[100,"100м ноги кроль на боку, по 25м на каждый бок"]],main:[[100,"2х50м кроль одной рукой i45, считаем гребки","Свободная рука вытянута вперёд. Рука, которой гребков вышло больше, и есть слабая — на ней сегодня будет лопатка. Почти у всех такая разница есть, и почти никто о ней не догадывается."],[200,"8х25м кроль в полной координации с одной маленькой лопаткой на слабой руке, i30","Лопатка стоит только на слабой руке. Тело будет уводить в сторону — это нормально и само по себе показывает, насколько руки разные."],[100,"100м откупка: 50м брасс с долгим скольжением + 50м спина спокойно"],[200,"8х25м — упражнение на кроль «2 гребка правой, 2 гребка левой», вторая рука вытянута вперёд","Два гребка одной, сразу два другой, без пауз. Второй гребок должен быть таким же длинным, как первый."],[100,"100м откупка: кроль в лёгком темпе, дыхание свободное"],[100,"2х50м кроль одной рукой i45, считаем гребки","Сравните с началом занятия."]],cool:[[100,"100м спина спокойно"],[100,"100м брасс с долгим скольжением"]]},
      {n:6,vol:1400,note:"Вторая половина гребка — там, где создаётся основная тяга, и там же, где любители теряют боль…",story:"Вторая половина гребка — там, где создаётся основная тяга, и там же, где любители теряют больше всего. Рука выходит из воды у пояса, последние двадцать сантиметров пропадают, и с каждым гребком вы недобираете кусок продвижения. Сегодня мы сначала изолируем окончание, а потом держим одно число гребков на растущей дистанции.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[100,"100м руки кроль с колобашкой спокойно"],[100,"4х25м кроль i20 в прогресс"]],main:[[100,"4х25м i20 — упражнение на кроль «только окончание гребка»","Рука входит и сразу, без наплыва, выполняет вторую половину гребка: от груди до бедра. В локте угол 90 градусов — не больше и не меньше. Далеко не уедете: вы плывёте половиной гребка, так и должно быть."],[200,"8х25м кроль в маленьких лопатках, i30, с усилием на окончание гребка"],[100,"100м откупка: 50м брасс с долгим скольжением + 50м спина спокойно"],[100,"4х25м кроль i25 — запоминаем число гребков","Число с первых 25 метров должно продержаться до последних. Поехало вверх — значит рука снова начала выходить раньше."],[100,"2х50м кроль i40 — то же число на каждых 25 метрах"],[100,"100м откупка: кроль в лёгком темпе, дыхание свободное"],[100,"4х25м кроль i30 — то же число, но быстрее"]],cool:[[100,"100м спина спокойно"],[100,"100м брасс с долгим скольжением"]]},
      {n:7,vol:1400,note:"Всё, что вы делаете в воде, — это борьба с сопротивлением, и бо́льшая часть силы уходит не на…",story:"Всё, что вы делаете в воде, — это борьба с сопротивлением, и бо́льшая часть силы уходит не на продвижение, а на то, чтобы протащить тело сквозь воду. Значит, сопротивление можно использовать как нагрузку: увеличить его специально, поработать, а потом убрать. Самый доступный способ — поднять голову. Подбородок над водой, перед грудью встаёт волна, таз уходит вниз, и несколько гребков подряд превращаются в силовую работу без единого приспособления.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[100,"2х50м i20: 25м кроль на кулаках + 25м кроль свободно"],[100,"100м ноги кроль с доской, спокойно"]],main:[[100,"4х25м кроль i40 — первые 7 гребков с поднятой головой, дальше доплываем спокойно"],[200,"4х50м кроль i40 — на мощность, считаем гребки"],[100,"100м откупка: 50м брасс с долгим скольжением + 50м спина спокойно"],[200,"4х50м кроль i40 — первые 25м с головой над водой, дальше свободно","Вторые 25 метров покажутся невесомыми: тело опустилось, волна перед грудью пропала. Вот так и должно ощущаться нормальное плавание."],[100,"100м откупка: кроль в лёгком темпе, дыхание свободное"],[100,"2х50м основным стилем i45 — мощно"]],cool:[[100,"100м спина спокойно"],[100,"100м брасс с долгим скольжением"]]},
      {n:8,vol:1400,note:"Шесть тренировок подряд мы разбирали мощность на кроле, потому что там её проще измерить",story:"Шесть тренировок подряд мы разбирали мощность на кроле, потому что там её проще измерить. Но самый мощный элемент в плавании — не гребок рукой, а толчок ногами в брассе: одно движение, которое разгоняет тело сильнее любого другого в воде. Сегодня разбираем брасс, а в конце берём от дельфина самую полезную его часть — работу ног.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[100,"100м ноги дельфин на спине, руки в стрелке, спокойно"],[100,"100м брасс спокойно"]],main:[[200,"8х25м ноги брасс с доской, i25 — считаем толчки","После каждого толчка задержитесь, пока тело едет. Закончилось скольжение — только тогда следующий толчок."],[100,"4х25м — упражнение на брасс «руки брасс / ноги кроль», i30","Ноги кролем держат тело ровно, и весь результат отрезка — это работа рук. Гребок короткий и быстрый, локти остаются впереди плеч."],[200,"8х25м брасс i30 — мощно, считаем гребки"],[100,"100м откупка: 50м спина спокойно + 50м кроль в лёгком темпе"],[100,"4х25м ноги дельфин в ластах на спине, руки в стрелке, i25 — мощно"],[100,"2х50м основным стилем i45 — мощно, считаем гребки"]],cool:[[100,"100м спина спокойно"],[100,"100м брасс с долгим скольжением"]]},
      {n:9,vol:1500,note:"Тело быстро привыкает к любой нагрузке и перестаёт замечать разницу",story:"Тело быстро привыкает к любой нагрузке и перестаёт замечать разницу. Поэтому работаем контрастом: сначала лопатки утяжеляют каждый гребок, а сразу после мы их снимаем — и несколько минут вода кажется пустой. Именно в этот момент и запоминается ощущение свободного мощного гребка.",warm:[[200,"200м спокойно: 100м ноги дельфин на спине, руки в стрелке + 100м кроль"],[100,"4х25м i20: через одну — дельфин и кроль на минимальное число гребков"],[100,"100м упражнение на кроль «догонялки»"]],main:[[200,"8х25м ноги в ластах, i20","Амплитуда небольшая, движение от бедра. Ноги готовят тело к тому, что дальше руки будут перегружены."],[100,"4х25м i20: упражнение на кроль «плавание на кулаках»"],[200,"8х25м кроль со средними лопатками, i30, мощно и плавно","С лопатками тянет частить. Допустим рост до трёх гребков, больше — значит вы уже суетитесь."],[100,"100м откупка: 50м брасс с долгим скольжением + 50м на спине, ноги мягко"],[200,"8х25м без лопаток, i25: четыре отрезка кроль и четыре основным стилем, удержать ту же длину гребка","Вот ради этой серии всё и делалось. Ощущение лёгкости обманчиво — не разменивайте его на частоту."],[100,"4х25м основной стиль на минимальное число гребков, i30","Замер тренировки — сегодня на своём стиле. Записывайте это число отдельно от кролевого."]],cool:[[100,"100м спокойно: 50м спина + 50м кроль, кисть уходит у бедра"],[100,"100м произвольно — плыть так, чтобы можно было говорить"]]},
      {n:10,vol:1500,note:"Лопатки увеличивают площадь опоры настолько, что любая ошибка в технике усиливается вместе с…",story:"Лопатки увеличивают площадь опоры настолько, что любая ошибка в технике усиливается вместе с усилием. Поэтому правило простое: плывём медленнее, чем позволяют лопатки, и следим за локтем. Мощность здесь набирается не скоростью, а качеством опоры.",warm:[[200,"200м спокойно: 100м брасс + 100м спина, следим за длиной скольжения"],[100,"100м скайлинг спокойно"],[100,"100м ноги дельфин на боку, смена стороны каждые 25м"]],main:[[200,"8х25м ноги кроль на боку, i25","По четыре отрезка на каждый бок. Плечо вытянутой руки у уха, тело вытянуто — это положение потом нужно удержать под лопатками."],[100,"4х25м i20: упражнение на кроль «только первая фаза гребка двумя руками»"],[200,"8х25м кроль со средними лопатками, i30, мощно и плавно, без ускорения","Скорость руки ниже привычной. Если плечо начинает ныть или кисть уходит выше локтя — снимайте лопатки и доплывайте маленькими."],[100,"100м откупка: кроль в лёгком темпе, дыхание на 3 гребка — расслабить плечи"],[200,"8х25м основной стиль без инвентаря, i30","Своим стилем плывём без лопаток: собственная рука после большой площади опоры кажется маленькой, и это надо перебороть длиной гребка."],[100,"4х25м кроль без инвентаря на минимальное число гребков, i30","Замер тренировки. Ощущение опоры после лопаток держится минут десять — используйте его."]],cool:[[100,"100м на спине, руки вдоль тела, ноги почти без усилия"],[100,"100м кроль длинным гребком, между гребками короткая пауза впереди"]]},
      {n:11,vol:1500,note:"Прежде чем толкать воду, её нужно почувствовать",story:"Прежде чем толкать воду, её нужно почувствовать. Скайлинг — движение ладонью почти без продвижения — учит именно этому: находить плотную воду и удерживать её. Тренировка кажется лёгкой, но именно она чаще всего снимает лишний гребок с отрезка.",warm:[[200,"200м спокойно: 100м спина в полной координации + 100м брасс на минимальное число гребков"],[100,"100м: 50м скайлинг + 50м спокойно"],[100,"100м брасс на минимальное число гребков"]],main:[[200,"8х25м ноги в ластах, руки в стрелке, i20","Руки вытянуты, голова между ними. Задача — почувствовать, как тело едет ровно, без раскачивания."],[100,"4х25м i20: скайлинг, ладонь ищет опору"],[200,"8х25м кроль, i25: 12,5м скайлинг + доплывание мощно и плавно","Сразу после скайлинга ладонь чувствительнее всего. Первые гребки после него должны быть самыми длинными."],[100,"100м откупка: на спине, руки вдоль тела, ноги мягко — не разгоняться"],[200,"8х25м основной стиль, i30, считаем гребки","На брассе чувство воды проверяется в разведении рук, на спине — в постановке кисти сразу после входа."],[100,"4х25м кроль без инвентаря на минимальное число гребков, i30","Замер тренировки. Скайлинг обычно даёт эффект в тот же день — сравните с прошлым результатом."]],cool:[[100,"100м спокойно: 50м ноги дельфин на спине, руки в стрелке + 50м спина"],[100,"100м брасс на минимальное число гребков, мягко"]]},
      {n:12,vol:1500,note:"Держать мощный гребок двадцать пять метров умеет почти каждый",story:"Держать мощный гребок двадцать пять метров умеет почти каждый. Держать его сто — уже сложнее. Здесь отрезки длиннее, а требование то же: ровное число гребков от начала до конца. Это честная проверка того, настоящая у вас мощность или разовая.",warm:[[200,"200м спокойно: 8х25м — дельфин, спина, брасс, кроль, дальше по кругу"],[100,"100м в трубке спокойно, считаем гребки"],[100,"100м ноги кроль с доской"]],main:[[200,"8х25м ноги кроль с доской, i20","Ровная работа без рывков. Ноги нужны для того, чтобы на длинных отрезках таз не проваливался."],[100,"4х25м i20: плавание на минимальное число гребков"],[200,"2х100м кроль с колобашкой и в маленьких лопатках, i45: разброс гребков не больше трёх","Записывайте гребки по каждому полтиннику отдельно. Обычно разваливается вторая — именно там и начинается работа."],[100,"100м откупка: 50м ноги брасс на спине, руки в стрелке + 50м брасс на скольжение"],[200,"200м основной стиль без инвентаря: удерживаем число гребков всю дистанцию","Скорость свободная, приоритет один — длина. Если гребков стало больше чем на три, сбросьте темп, но не длину."],[100,"4х25м кроль на минимальное число гребков, i30","Замер тренировки. После длинной работы гребок обычно длиннее обычного — поймайте это состояние."]],cool:[[100,"100м спина спокойно, руки вдоль тела — плечи отпустить"],[100,"100м произвольно, дыхание свободное"]]},
      {n:13,vol:1500,note:"Мощность в кроле и мощность в других стилях — разные вещи",story:"Мощность в кроле и мощность в других стилях — разные вещи. В брассе тяга идёт от разведения и сведения рук, на спине — от постановки кисти сразу после входа. Проходим стили по очереди и в каждом ищем свою точку приложения силы.",warm:[[200,"200м спокойно: 100м кроль + 100м ноги брасс с доской"],[100,"100м ноги с доской: 50м кроль + 50м брасс"],[100,"4х25м i20: по одному отрезку спина и брассом, два отрезка кроль"]],main:[[200,"8х25м ноги в ластах, i20","Движение от бедра и таза. Ноги здесь готовят корпус к работе в разных стилях."],[100,"4х25м i20: упражнение на брасс «руки брасс / ноги кроль»"],[200,"8х25м по стилям с в маленьких лопатках, i30: 3 спина, 3 брасс, 2 кроль","Короткие серии на каждый стиль — так лопатки не успевают перегрузить плечо."],[100,"100м откупка: 50м кроль на минимальное число гребков + 50м спина спокойно"],[200,"8х25м основной стиль, i30, считаем гребки","Записывайте число гребков. Свой стиль после серии по стилям ощущается иначе — сравните с началом тренировки."],[100,"4х25м кроль без инвентаря на минимальное число гребков, i30","Замер тренировки. Кроль после других стилей всегда кажется лёгким — используйте это."]],cool:[[100,"100м брасс с долгим скольжением, гребок не тянем"],[100,"100м кроль на минимальное число гребков — без усилия, только за счёт длины"]]},
      {n:14,vol:1500,note:"На спине мощность строится иначе: тело держится только положением таза, а гребок идёт под вод…",story:"На спине мощность строится иначе: тело держится только положением таза, а гребок идёт под водой почти прямой траекторией. Начинающие на спине почти всегда гребут поверхностно и коротко. Разбираем это отдельно — заодно спина хорошо разгружает плечо после кролевых объёмов.",warm:[[200,"200м спокойно: 100м спина + 100м кроль"],[100,"100м на спине: 50м «одна рука работает, вторая у бедра» + 50м «6-1-6»"],[100,"100м ноги дельфин на спине, руки в стрелке"]],main:[[200,"8х25м ноги на спине в стрелочке, i25","Таз у поверхности, колени под водой. Если из воды показались колени, значит работа идёт вниз, а не назад."],[100,"4х25м i20: скайлинг на спине"],[200,"8х25м спина с в маленьких лопатках, i30, считаем гребки","Кисть входит мизинцем, локоть уходит под воду и сгибается — прямой рукой на спине протянуть воду невозможно."],[100,"100м откупка: спина двумя руками одновременно — плечи опустить, не тянуться"],[200,"8х25м основной стиль, i30","Возвращаемся к своему стилю: после спины плечи разгружены и гребок обычно получается длиннее."],[100,"4х25м спина без инвентаря на минимальное число гребков, i30","Замер тренировки — сегодня на спине. Записывайте его отдельно от кролевого, это разные цифры."]],cool:[[100,"100м кроль спокойно на минимальное число гребков"],[100,"100м ноги дельфин на спине, руки в стрелке, мягко"]]},
      {n:15,vol:1500,note:"Сборная тренировка: захват, окончание гребка, ноги, работа с инвентарём и без него — всё в од…",story:"Сборная тренировка: захват, окончание гребка, ноги, работа с инвентарём и без него — всё в одном занятии. Заканчивается контрольным замером: четыре отрезка по 25 м с фиксацией времени и числа гребков. Запишите обе цифры и вернитесь к ним через месяц.",warm:[[200,"200м спокойно: 150м кроль + 50м дельфин"],[100,"100м упражнение на брасс «руки брасс / ноги кроль»: 50м скайлинг + 50м на кулаках"],[100,"100м ноги брасс с доской"]],main:[[200,"8х25м ноги кроль с доской, i25: четыре отрезка в ластах, четыре без","Сравните ощущение. Без ласт задача не догнать скорость, а сохранить то же положение таза."],[100,"4х25м i20: два отрезка «только первая фаза», два отрезка «только окончание гребка»"],[200,"8х25м кроль с в маленьких лопатках и колобашкой, i25","Мощно и плавно, без ускорения. Это подготовка к замеру, а не соревнование с самим собой."],[100,"100м откупка: 50м на спине двумя руками одновременно + 50м кроль длинным гребком — вернуть дыхание"],[200,"8х25м основной стиль, i30, считаем гребки","Свой стиль перед замером. Если число гребков выросло больше чем на три по сравнению с началом тренировки, значит нагрузка была великовата."],[100,"4х25м кроль без инвентаря i60: контрольный замер — время и число гребков","Плывите мощно и плавно, а не изо всех сил. Показатель — это время при минимальном числе гребков."]],cool:[[100,"100м на спине двумя руками одновременно, спокойно"],[100,"4х25м скольжения от бортика до полной остановки, руки в стрелке"]]}
    ]},
    mo_s:{level:"Средний",vol:"2100–2200 м",w:[
      {n:1,vol:2200,note:"Мощность — это не скорость",story:"Мощность — это не скорость. Как только пловец уходит на максимум, он почти всегда начинает рвать воду: рука проскальзывает, гребков становится больше, а вперёд вы двигаетесь хуже. Поэтому судья здесь не секундомер, а число гребков: если усилие выросло, а гребков столько же — выросла мощность. Сегодня мы эту цифру измерим в начале, весь час будем добавлять усилие и в конце измерим снова.",warm:[[400,"400м в трубке, чередуя по 50м: на кулаках и открытой ладонью"],[100,"4х25м кроль i20 в прогресс"]],main:[[200,"4х50м кроль i30 на минимальное число гребков, спокойно","Это ваша цифра на сегодня. Всё остальное занятие — про то, чтобы она не выросла, когда добавится усилие."],[200,"4х50м кроль, режим 1:30 — 25м упражнение «на боку 6 ударов, смена рук через пронос и гребок» + 25м в полной координации, мощно и плавно","Каждый переход — один гребок, которым нужно провернуть всё тело с бока на бок. Слабый оставит вас на месте."],[400,"4х100м руки кроль с колобашкой и средними лопатками, режим 2:00, мощно и плавно","Кисть всегда ниже локтя. С лопаткой соблазн протащить воду прямой рукой самый сильный — именно этого не допускаем."],[100,"100м откупка: 50м ноги брасс на спине, руки в стрелке + 50м кроль в лёгком темпе"],[300,"3х100м основным стилем, режим 2:10 — считаем гребки на первых 50м каждой сотни, с каждой сотней на один-два гребка меньше","Режим держит скорость, поэтому убавить гребки можно одним способом — сделать каждый сильнее."],[100,"100м откупка: на спине, руки вдоль тела, ноги мягко"],[200,"4х50м кроль i30 на минимальное число гребков","Та же цифра, что в начале, или меньше."]],cool:[[100,"100м спина спокойно, руки вдоль тела"],[100,"4х25м скольжения от бортика до полной остановки, руки в стрелке"]]},
      {n:2,vol:2100,note:"Толчок от стенки разгоняет вас быстрее, чем вы способны плыть, и первые метры каждого отрезка…",story:"Толчок от стенки разгоняет вас быстрее, чем вы способны плыть, и первые метры каждого отрезка вы едете на чужой скорости. Поэтому обычная тренировка плохо показывает, сколько силы в самом гребке. Сегодня стенку почти везде уберём: отрезки начинаются с места, из неподвижного положения. Стронуть стоящее тело можно только гребком — ни инерция, ни скольжение тут не помогут.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[200,"4х50м i20: 25м проныр дельфином + 25м кроль свободно"],[100,"100м ноги брасс с доской, спокойно"]],main:[[200,"4х50м кроль i30 на минимальное число гребков","Та же цифра, что в первой тренировке, или меньше. Это ваш ориентир на весь блок."],[200,"4х50м ноги дельфин в ластах, режим 1:15 — первые 15м под водой, дальше на поверхности","Движение идёт от груди и таза, колени почти не сгибаются."],[300,"6х50м кроль, режим 1:40 — нечётные с места, чётные с обычного толчка","Вис у бортика, тело неподвижно, ноги не упираются. Разница между соседними отрезками — это то, что вам даёт стенка: обычно два-три гребка."],[100,"100м откупка: 50м ноги брасс на спине, руки в стрелке + 50м кроль в лёгком темпе"],[300,"3х100м основным стилем, режим 2:15 — каждая сотня начинается с места, первые 25м в полную силу, дальше ровно","К третьей сотне трогаться с места станет заметно тяжелее, чем к первой."],[100,"100м откупка: на спине, руки вдоль тела, ноги мягко"],[200,"4х50м основным стилем i45 — с места, считаем гребки"]],cool:[[100,"100м спина спокойно, руки вдоль тела"],[100,"4х25м скольжения от бортика до полной остановки, руки в стрелке"]]},
      {n:3,vol:2100,note:"Про мощность почти всегда думают руками",story:"Про мощность почти всегда думают руками. Между тем ноги в кроле дают не столько тягу, сколько опору: если таз провалился, даже очень сильный гребок разворачивает вас вверх, а не толкает вперёд. Сегодня ноги работают отдельно от рук, в том числе против сопротивления — доска, поставленная вертикально, идёт перед вами как парус и превращает обычные 50 метров в силовую работу.",warm:[[200,"200м спокойно: 100м кроль + 100м брасс"],[200,"200м ноги брасс на спине, руки в стрелке, i30"],[100,"4х25м кроль i20 в прогресс"]],main:[[200,"200м ноги дельфин на боку, меняя бок каждые 25м","Тело строго на боку, нижняя рука впереди, голова лежит на плече. Движение зарождается в груди и тазе, а не в коленях. Удар одинаково сильный в обе стороны."],[300,"6х50м ноги кроль с доской, i45 — 25м доска вертикально + 25м доска как обычно","Первые 25 метров доска идёт широкой стороной против воды, скорость падает примерно вдвое. На повороте разворачиваете её плашмя — и вторые 25 тело едет почти само."],[100,"100м откупка: 50м ноги брасс на спине, руки в стрелке + 50м кроль в лёгком темпе"],[200,"4х50м ноги брасс, режим 1:30 — считаем толчки"],[100,"100м откупка: на спине, руки вдоль тела, ноги мягко"],[300,"3х100м основным стилем, режим 2:15 — 50м ноги почти выключены + 50м ноги в полную силу, на второй половине гребков меньше","Скорость вырастет меньше, чем ожидаешь: ноги дают не столько тягу, сколько опору. Зато тело идёт выше, гребок цепляет больше воды — и те же 50 метров проходятся за меньшее число гребков."],[200,"4х50м кроль в ластах, режим 1:15 — мощно, в полную силу","Ласты поднимают таз за вас. Запомните это положение."]],cool:[[100,"100м спина спокойно, руки вдоль тела"],[100,"4х25м скольжения от бортика до полной остановки, руки в стрелке"]]},
      {n:4,vol:2200,note:"Захват — самая недооценённая часть гребка и то место, где мощность теряется целиком",story:"Захват — самая недооценённая часть гребка и то место, где мощность теряется целиком. Большинство любителей начинает тянуть сразу после входа, прямой рукой, и первая треть гребка уходит на то, чтобы протолкнуть воду вниз, а не назад. Сегодня мы этот момент растягиваем: вставляем в него паузу. Пока рука стоит в точке захвата, инерция пропадает, и тянуть приходится с нуля. И общее правило блока: гребки считаем на каждой серии, а не только там, где это написано.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[200,"200м руки кроль с колобашкой спокойно — настраиваем захват"],[100,"4х25м кроль i20 в прогресс"]],main:[[100,"4х25м i20 — упражнение на кроль «только первая фаза гребка, двумя руками одновременно»","Продвижение почти нулевое, и это нормально: задача не проплыть, а найти положение, в котором кисть уже смотрит назад, а локоть ещё наверху. Если есть трубка — наденьте, не придётся отвлекаться на вдох."],[300,"6х50м кроль в полной координации, режим 1:35 — пауза в точке захвата на счёт «раз», дальше гребок в полную силу","Рука входит, вытягивается вперёд, кисть разворачивается вниз, локоть остаётся высоко — и остановка на счёт «раз». Только потом гребок. Пауза съедает инерцию: каждый гребок начинается с нуля."],[100,"100м откупка: 50м ноги брасс на спине, руки в стрелке + 50м кроль в лёгком темпе"],[300,"6х50м кроль в маленьких лопатках, режим 1:25 — считаем гребки"],[100,"100м откупка: на спине, руки вдоль тела, ноги мягко"],[300,"6х50м кроль без лопаток, режим 1:25 — держим то же число гребков"],[100,"100м откупка: 50м брасс с долгим скольжением + 50м спина спокойно"],[200,"2х100м основным стилем, режим 2:15 — мощно, считаем гребки"]],cool:[[100,"100м спина спокойно, руки вдоль тела"],[100,"4х25м скольжения от бортика до полной остановки, руки в стрелке"]]},
      {n:5,vol:2100,note:"У любого пловца одна рука работает лучше другой, и почти никто об этом не знает: в полной коо…",story:"У любого пловца одна рука работает лучше другой, и почти никто об этом не знает: в полной координации сильная рука прикрывает слабую, и разницы не видно. Развести их просто — проплыть 50 метров одной рукой, потом другой и сравнить число гребков. Разрыв в один-два гребка есть у всех, три и больше — это уже потолок вашей мощности. Сегодня мы разрыв измеряем, целую серию плывём с лопаткой только на слабой руке и в конце меряем снова.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[200,"8х25м i20: упражнение на кроль «гребок только одной рукой», вторая рука прижата вдоль туловища"],[100,"100м ноги кроль на боку, по 25м на каждый бок"]],main:[[200,"4х50м кроль одной рукой i45, считаем гребки","Вот ваша асимметрия в числах. Рука, которой гребков больше, и есть слабая — на ней сегодня будет лопатка."],[300,"6х50м кроль в полной координации с одной средней лопаткой на слабой руке, режим 1:30","Лопатка стоит только на слабой руке и на время выравнивает ощущения между сторонами. Тело будет уводить в сторону — выравнивайте гребком, а не рулём."],[100,"100м откупка: 50м ноги брасс на спине, руки в стрелке + 50м кроль в лёгком темпе"],[300,"6х50м, режим 1:35 — упражнение на кроль «2 гребка правой, 2 гребка левой», вторая рука у бедра","Второй гребок подряд одной рукой — диагностический. Короче первого — значит рука не восстанавливает опору, а доезжает на инерции."],[100,"100м откупка: на спине, руки вдоль тела, ноги мягко"],[200,"2х100м кроль, режим 1:55 — на первых 50м считаем гребки только правой руки, на вторых только левой","Числа должны сойтись."],[200,"4х50м кроль одной рукой i45, считаем гребки","Сравните с началом занятия. Разрыв между руками должен стать меньше."]],cool:[[100,"100м спина спокойно, руки вдоль тела"],[100,"4х25м скольжения от бортика до полной остановки, руки в стрелке"]]},
      {n:6,vol:2100,note:"Вторая половина гребка — там, где создаётся основная тяга, и там же, где любители теряют боль…",story:"Вторая половина гребка — там, где создаётся основная тяга, и там же, где любители теряют больше всего. Рука выходит из воды у пояса, последние двадцать сантиметров пропадают, и с каждым гребком вы недобираете кусок продвижения. Сегодня мы сначала изолируем окончание, а потом проверяем его на растущей дистанции — недоведённый гребок разваливается первым, как только становится тяжело.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[200,"200м руки кроль с колобашкой спокойно"],[100,"4х25м кроль i20 в прогресс"]],main:[[100,"4х25м i20 — упражнение на кроль «только окончание гребка»","Рука входит и сразу, без наплыва и захвата, выполняет вторую половину: от груди до бедра, с ускорением кисти к концу. В локте угол 90 градусов — не больше и не меньше. Продвижение будет маленьким: вы плывёте половиной гребка."],[200,"4х50м кроль со средними лопатками, режим 1:25, с усилием на окончание гребка"],[100,"100м откупка: 50м ноги брасс на спине, руки в стрелке + 50м кроль в лёгком темпе"],[200,"4х50м кроль, режим 1:25 — запоминаем число гребков","Число с первых 50 метров должно продержаться до последних. Как только рука начнёт выходить раньше, оно поедет вверх — это и есть момент, когда гребок разваливается."],[200,"2х100м кроль, режим 2:20 — то же число на каждых 50 метрах"],[200,"200м кроль без остановки, отдых 60 сек — то же число"],[200,"4х50м кроль, режим 1:20 — то же число, но быстрее"],[100,"100м откупка: на спине, руки вдоль тела, ноги мягко"],[100,"2х50м основным стилем i40 — мощно"]],cool:[[100,"100м спина спокойно, руки вдоль тела"],[100,"4х25м скольжения от бортика до полной остановки, руки в стрелке"]]},
      {n:7,vol:2100,note:"Всё, что вы делаете в воде, — это борьба с сопротивлением, и бо́льшая часть силы уходит не на…",story:"Всё, что вы делаете в воде, — это борьба с сопротивлением, и бо́льшая часть силы уходит не на продвижение, а на то, чтобы протащить тело сквозь воду. Значит, сопротивление можно использовать как нагрузку: увеличить его специально, поработать, а потом убрать. Самый доступный способ — поднять голову. Подбородок над водой, перед грудью встаёт волна, таз уходит вниз, и несколько гребков подряд превращаются в силовую работу без единого приспособления. Долго так плыть не нужно: семи гребков хватает, чтобы загрузить, а дальше вы доплываете спокойно и чувствуете разницу.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[200,"4х50м i20: 25м кроль на кулаках + 25м кроль свободно"],[100,"100м ноги кроль с доской, спокойно"]],main:[[200,"8х25м кроль i30 — первые 7 гребков с поднятой головой, дальше доплываем спокойно","Подбородок над водой, взгляд вперёд, голова не крутится. К седьмому гребку плечи уже тянет вверх — и вот тогда голова опускается, а тело само проваливается в нормальное положение."],[300,"6х50м кроль, режим 1:30 — на мощность, считаем гребки"],[100,"100м откупка: 50м ноги брасс на спине, руки в стрелке + 50м кроль в лёгком темпе"],[300,"3х100м кроль, режим 2:05 — первые 25м с головой над водой, дальше свободно","Первая четверть грузит, остальные три снимают урожай."],[100,"100м откупка: на спине, руки вдоль тела, ноги мягко"],[400,"4х100м основным стилем, режим 2:10 — мощно","После работы с поднятой головой обычное плавание кажется лёгким, и это не иллюзия: тело действительно идёт выше."]],cool:[[100,"100м спина спокойно, руки вдоль тела"],[100,"4х25м скольжения от бортика до полной остановки, руки в стрелке"]]},
      {n:8,vol:2100,note:"Семь тренировок подряд мы разбирали мощность на кроле, потому что там её проще измерить",story:"Семь тренировок подряд мы разбирали мощность на кроле, потому что там её проще измерить. Но самый мощный элемент в плавании — не гребок рукой, а толчок ногами в брассе. А самый силовой гребок руками — дельфином, где тяга идёт от корпуса, а не от плеча. Сегодня занятие разделено пополам: сначала брасс, потом дельфин. Если ваш основной стиль кроль, это не потерянный день — и то и другое возвращается в кроль.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[200,"200м ноги дельфин на спине, руки в стрелке, i30"],[100,"100м брасс на минимальное число гребков"]],main:[[200,"8х25м ноги брасс, руки в стрелке, i30 — считаем толчки","После каждого толчка задержитесь в стрелке, пока тело едет. Закончилось скольжение — только тогда следующий толчок."],[100,"2х50м — упражнение на брасс «руки брасс / ноги кроль», i30","Ноги кролем держат тело ровно, и весь результат отрезка — это работа рук. Гребок короткий и быстрый, локти остаются впереди плеч."],[300,"6х50м брасс, режим 1:35 — мощно, считаем гребки"],[100,"100м откупка: 50м на спине двумя руками одновременно + 50м кроль в лёгком темпе"],[200,"8х25м ноги дельфин в ластах, i20 — мощно"],[100,"4х25м — упражнение на баттерфляй «гребок только одной рукой», вторая вытянута вперёд, i25","Нагрузка вдвое меньше, и освобождается внимание на детали: наплыв после входа, высокий локоть, доведение до бедра."],[100,"4х25м дельфин i40 — мощно"],[100,"100м откупка: 50м брасс с долгим скольжением + 50м спина спокойно"],[200,"2х100м основным стилем, режим 2:15 — мощно, считаем гребки","Вернитесь в свой стиль и перенесите ощущение: из брасса — вложиться в одно движение целиком, из дельфина — тянуть корпусом."]],cool:[[100,"100м спина спокойно, руки вдоль тела"],[100,"4х25м скольжения от бортика до полной остановки, руки в стрелке"]]},
      {n:9,vol:2200,note:"Тело быстро привыкает к любой нагрузке и перестаёт замечать разницу",story:"Тело быстро привыкает к любой нагрузке и перестаёт замечать разницу. Поэтому работаем контрастом: сначала чашечки утяжеляют каждый гребок, а сразу после мы их снимаем — и несколько минут вода кажется пустой. Именно в этот момент и запоминается ощущение мощного, свободного гребка.",warm:[[200,"200м спокойно: 100м кроль + 100м ноги брасс с доской"],[200,"200м в трубке: 100м на кулаках + 100м в полной координации основным стилем"],[100,"100м кроль с подсчётом гребков — запомнить число на сегодня"]],main:[[300,"6х50м ноги дельфин в ластах, режим 1:15","Амплитуда небольшая, движение от груди. Ноги готовят тело к тому, что дальше руки будут перегружены."],[100,"4х25м i20: упражнение на кроль «плавание на кулаках»"],[300,"6х50м кроль с чашечками, режим 1:25, мощно и плавно","С сопротивлением тянет частить. Допустим рост до трёх гребков на полтиннике, больше — значит вы уже суетитесь."],[150,"150м откупка: 150м спина спокойно, руки вдоль тела — плечи отпустить"],[300,"6х50м кроль без чашечек, режим 1:20: удержать ту же длину гребка","Вот ради этой серии всё и делалось. Ощущение лёгкости обманчиво — не разменивайте его на частоту, держите длину."],[100,"100м откупка: 50м брасс с долгим скольжением + 50м на спине, ноги мягко"],[200,"8х25м основной стиль на минимальное число гребков, i30","Замер тренировки — сегодня на своём стиле. Записывайте это число отдельно от кролевого."]],cool:[[100,"100м спокойно: 50м брасс + 50м спина"],[150,"150м спокойно: 50м ноги дельфин на спине, руки в стрелке + 100м спина"]]},
      {n:10,vol:2200,note:"Лопатки увеличивают площадь опоры настолько, что любая ошибка в технике усиливается вместе с…",story:"Лопатки увеличивают площадь опоры настолько, что любая ошибка в технике усиливается вместе с усилием. Поэтому правило простое: плывём медленнее, чем позволяют лопатки, и следим за локтем. Мощность здесь набирается не скоростью, а качеством опоры.",warm:[[200,"200м спокойно: 150м кроль + 50м дельфин"],[200,"200м спокойно: 4х25м скольжения от бортика до полной остановки, руки в стрелке + 100м спина, руки вдоль тела"],[100,"4х25м скольжения от бортика до полной остановки, руки в стрелке"]],main:[[300,"6х50м ноги кроль без доски на боку, режим 1:35","По 25 м на каждый бок. Плечо вытянутой руки у уха, тело вытянуто — это положение потом нужно удержать под лопатками."],[100,"4х25м i20: упражнение на кроль «только первая фаза гребка двумя руками»"],[300,"6х50м кроль со средними лопатками, режим 1:25, мощно и плавно, без ускорения","Скорость руки должна быть ниже привычной. Если плечо начинает ныть или кисть уходит выше локтя — снимайте лопатки."],[150,"150м откупка: 50м на спине двумя руками одновременно + 100м кроль в лёгком темпе"],[300,"6х50м основной стиль без инвентаря, режим 1:30","Своим стилем плывём без лопаток: после большой площади опоры собственная рука кажется маленькой, и это ощущение надо перебороть длиной гребка."],[100,"100м откупка: кроль в лёгком темпе, дыхание на 3 гребка — расслабить плечи"],[200,"8х25м кроль без инвентаря на минимальное число гребков, i30","Замер тренировки. Ощущение опоры после лопаток держится минут десять — используйте его."]],cool:[[150,"150м в трубке ноги кроль спокойно"],[100,"100м кроль в лёгком темпе — рука доходит до бедра, усилия не добавляем"]]},
      {n:11,vol:2200,note:"Прежде чем толкать воду, её нужно почувствовать",story:"Прежде чем толкать воду, её нужно почувствовать. Скайлинг — движение ладонью почти без продвижения — учит именно этому: находить плотную воду и удерживать её. Тренировка получается обманчиво лёгкой, но именно она чаще всего снимает пару гребков с полтинника.",warm:[[200,"200м спокойно: 100м кроль, вдох в обе стороны + 100м брасс на скольжение"],[200,"200м: 100м скайлинг + 100м спокойно"],[100,"4х25м i20: через одну — дельфин и кроль на минимальное число гребков"]],main:[[300,"6х50м ноги в ластах, руки в стрелке, режим 1:15","Руки вытянуты, голова между ними. Задача — почувствовать, как тело едет ровно, без раскачивания."],[100,"4х25м i20: скайлинг, ладонь ищет опору"],[300,"6х50м кроль, режим 1:30: 12,5м скайлинг + доплывание мощно и плавно","Сразу после скайлинга ладонь чувствительнее всего. Первые гребки после него должны быть самыми длинными на отрезке."],[150,"150м откупка: 50м брасс с долгим скольжением + 50м спина + 50м кроль длинным гребком"],[300,"6х50м основной стиль, режим 1:30, считаем гребки","На брассе чувство воды проверяется в разведении рук, на спине — в постановке кисти сразу после входа."],[100,"100м откупка: на спине, руки вдоль тела, ноги мягко — не разгоняться"],[200,"8х25м кроль без инвентаря на минимальное число гребков, i30","Замер тренировки. Скайлинг обычно даёт эффект в тот же день — сравните с прошлым результатом."]],cool:[[150,"150м спокойно: 50м брасс + 50м спина + 50м кроль"],[100,"100м спина в полной координации, считаем гребки — число должно упасть"]]},
      {n:12,vol:2200,note:"Держать мощный гребок двадцать пять метров умеет почти каждый",story:"Держать мощный гребок двадцать пять метров умеет почти каждый. Держать его двести — почти никто. Здесь отрезки длиннее, а требование то же: ровное число гребков от первого полтинника до последней. Это честная проверка того, настоящая у вас мощность или разовая.",warm:[[200,"200м спокойно: 100м кроль с подсчётом гребков + 100м спина"],[200,"200м в трубке спокойно, считаем гребки на каждом полтиннике"],[100,"100м упражнение на кроль «догонялки»"]],main:[[300,"6х50м ноги кроль с доской, режим 1:30","Ровная работа без рывков. Ноги нужны для того, чтобы на длинных отрезках таз не проваливался."],[100,"4х25м i20: плавание на минимальное число гребков"],[300,"3х100м кроль с колобашкой и средними лопатками, режим 2:10: разброс гребков не больше трёх","Записывайте гребки по каждому полтиннику отдельно. Обычно разваливается вторая — именно там и начинается настоящая работа."],[150,"150м откупка: 150м спина спокойно, руки вдоль тела — плечи отпустить"],[300,"300м основной стиль без инвентаря: удерживаем число гребков всю дистанцию","Скорость свободная, приоритет один — длина. Если число гребков выросло больше чем на три, сбросьте темп, но не длину."],[100,"100м откупка: 50м ноги брасс на спине, руки в стрелке + 50м брасс на скольжение"],[200,"8х25м кроль на минимальное число гребков, i30","Замер тренировки. После длинной работы гребок обычно длиннее обычного — поймайте это состояние."]],cool:[[100,"100м брасс: гребок, пауза, толчок — торопиться некуда"],[150,"150м произвольно, дыхание свободное"]]},
      {n:13,vol:2200,note:"Мощность в кроле и мощность в комплексе — разные вещи",story:"Мощность в кроле и мощность в комплексе — разные вещи. В дельфине тяга идёт от корпуса, в брассе — от разведения и сведения рук, на спине — от постановки кисти сразу после входа. Проходим все четыре стиля и в каждом ищем свою точку приложения силы.",warm:[[200,"200м на руках с колобашкой: 100м кроль + 100м спина (без колобашки — просто не работайте ногами)"],[200,"200м в маленьких лопатках спокойно: 100м кроль + 100м спина"],[100,"100м ноги дельфин на боку, смена стороны каждые 25м"]],main:[[300,"6х50м ноги дельфин в ластах, режим 1:15","Волна идёт от груди через таз к стопам. Это базовое движение для дельфина и заодно подготовка спины к работе."],[100,"4х25м i20: упражнение на баттерфляй «руки дельфин / ноги кроль»"],[300,"6х50м по стилям со средними лопатками, режим 1:40: 2 спина, 2 брасс, 2 кроль","Короткие серии на каждый стиль — так лопатки не успевают перегрузить плечо. Дельфин с лопатками здесь не берём."],[150,"150м откупка: 50м на спине двумя руками одновременно + 100м кроль в лёгком темпе"],[300,"3х100м комплекс, режим 2:20, считаем гребки на каждой 25","Записывайте четыре числа. Стиль с самым большим числом гребков — ваша слабая точка в комплексе, ей и будете заниматься отдельно."],[100,"100м откупка: 50м кроль на минимальное число гребков + 50м спина спокойно"],[200,"8х25м основной стиль на минимальное число гребков, i30","Замер тренировки — сегодня на своём стиле. После комплекса он ощущается легче обычного, используйте это и постарайтесь снять лишний гребок."]],cool:[[150,"150м спокойно: 100м на спине двумя руками одновременно + 50м брасс на скольжение"],[100,"100м кроль, вдох в обе стороны через три гребка"]]},
      {n:14,vol:2200,note:"На спине мощность строится иначе: нет опоры на дыхании, тело держится только положением таза…",story:"На спине мощность строится иначе: нет опоры на дыхании, тело держится только положением таза, а гребок идёт под водой почти прямой траекторией. Любители на спине почти всегда гребут поверхностно и коротко. Разбираем это отдельно — заодно спина хорошо разгружает плечо после кролевых объёмов.",warm:[[200,"200м спокойно: 100м спина + 100м кроль"],[200,"200м на спине: 100м «одна рука работает, вторая у бедра» + 100м «6-1-6»"],[100,"100м брасс на минимальное число гребков"]],main:[[300,"6х50м ноги на спине в стрелочке, режим 1:30","Таз у поверхности, колени под водой. Если из воды показались колени, значит работа идёт вниз, а не назад."],[100,"4х25м i20: скайлинг на спине"],[300,"6х50м спина со средними лопатками, режим 1:30, считаем гребки","Кисть входит мизинцем, локоть уходит под воду и сгибается — прямой рукой на спине протянуть воду невозможно, лопатка это только подчеркнёт."],[150,"150м откупка: 50м брасс с долгим скольжением + 50м спина + 50м кроль длинным гребком"],[300,"6х50м основной стиль, режим 1:30","Возвращаемся к своему стилю: после спины плечи разгружены и гребок обычно получается длиннее."],[100,"100м откупка: спина двумя руками одновременно — плечи опустить, не тянуться"],[200,"8х25м спина без инвентаря на минимальное число гребков, i30","Замер тренировки — сегодня на спине. Записывайте его отдельно от кролевого, это разные цифры."]],cool:[[150,"150м кроль спокойно на минимальное число гребков"],[100,"100м ноги брасс на спине, руки в стрелке"]]},
      {n:15,vol:2200,note:"Сборная тренировка: захват, окончание гребка, ноги, работа с сопротивлением и без него — всё…",story:"Сборная тренировка: захват, окончание гребка, ноги, работа с сопротивлением и без него — всё в одном занятии. Заканчивается контрольным замером: четыре полтинника с фиксацией времени и числа гребков. Запишите обе цифры и вернитесь к ним через месяц — именно эта пара чисел показывает, растёт ли мощность.",warm:[[200,"200м спокойно: 100м брасс на минимальное число гребков + 100м кроль длинным гребком"],[200,"200м упражнение на кроль «один гребок правой, один левой, один двумя руками»: 100м скайлинг + 100м на кулаках"],[100,"100м ноги кроль с доской"]],main:[[300,"6х50м ноги кроль с доской, режим 1:25: три отрезка в ластах, три без","Сравните ощущение. Без ласт задача не догнать скорость, а сохранить то же положение таза."],[100,"4х25м i20: два отрезка «только первая фаза», два отрезка «только окончание гребка»"],[300,"6х50м кроль со средними лопатками и колобашкой, режим 1:25","Мощно и плавно, без ускорения. Это подготовка к замеру, а не соревнование с самим собой."],[150,"150м откупка: 150м спина спокойно, руки вдоль тела — плечи отпустить"],[300,"6х50м основной стиль, режим 1:30, считаем гребки","Свой стиль перед замером. Если число гребков выросло больше чем на три по сравнению с началом тренировки, значит нагрузка была великовата — сбавьте усилие."],[100,"100м откупка: 50м на спине двумя руками одновременно + 50м кроль длинным гребком — вернуть дыхание"],[200,"4х50м кроль без инвентаря i60: контрольный замер — время и число гребков","Плывите мощно и плавно, а не на максимум. Показатель — это время при минимальном числе гребков, а не время любой ценой."]],cool:[[150,"150м кроль в лёгком темпе, дыхание на 5 гребков"],[100,"100м спокойно: 50м спина + 50м кроль, кисть уходит у бедра"]]}
    ]},
    mo_p:{level:"Продвинутый",vol:"2800–3000 м",w:[
      {n:1,vol:3000,note:"Мощность — это не скорость",story:"Мощность — это не скорость. Как только пловец уходит на максимум, он почти всегда начинает рвать воду: рука проскальзывает, гребков становится больше, а вперёд вы двигаетесь хуже. Поэтому судья здесь не секундомер, а число гребков: если усилие выросло, а гребков столько же — выросла мощность. Сегодня мы эту цифру измерим в начале, весь час будем добавлять усилие и в конце измерим снова.",warm:[[500,"500м в трубке, чередуя по 50м: на кулаках и открытой ладонью"],[200,"4х50м кроль i20 в прогресс: гребок с каждым отрезком активнее, число гребков то же"]],main:[[200,"4х50м кроль i30 на минимальное число гребков, спокойно","Это ваша цифра на сегодня. Всё остальное занятие — про то, чтобы она не выросла, когда добавится усилие."],[400,"8х50м кроль, режим 1:20 — 25м упражнение «на боку 6 ударов, смена рук через пронос и гребок» + 25м в полной координации, мощно и плавно","Каждый переход — это один гребок, которым нужно провернуть всё тело с бока на бок. Слабый здесь просто не сработает: вы останетесь на месте. Гребок начинается ровно в момент входа второй руки, не раньше."],[600,"6х100м руки кроль с колобашкой и средними лопатками, режим 1:50, мощно и плавно","Кисть всегда ниже локтя. Лопатка увеличивает площадь, и соблазн протащить воду прямой рукой здесь самый сильный — именно этого не допускаем."],[100,"100м откупка: 50м ноги брасс на спине, руки в стрелке + 50м кроль в лёгком темпе"],[400,"4х100м основным стилем, режим 2:00 — считаем гребки на первых 50м каждой сотни, с каждой сотней на один-два гребка меньше","Режим держит скорость, поэтому убавить гребки можно одним способом — сделать каждый сильнее. Это и есть мощность одной строкой. Если на последней сотне держать уже нечего, лучше убрать один гребок, чем два и развалить гребок совсем."],[100,"100м откупка: на спине, руки вдоль тела, ноги мягко"],[200,"4х50м кроль i30 на минимальное число гребков","Та же цифра, что в начале, или меньше. Выросла — значит усилие ушло в рывок, а не в опору."]],cool:[[200,"200м спокойно: 100м спина + 100м брасс с долгим скольжением"],[100,"4х25м скольжения от бортика до полной остановки, руки в стрелке"]]},
      {n:2,vol:2800,note:"Толчок от стенки разгоняет вас быстрее, чем вы способны плыть, и первые метры каждого отрезка…",story:"Толчок от стенки разгоняет вас быстрее, чем вы способны плыть, и первые метры каждого отрезка вы едете на чужой скорости. Поэтому обычная тренировка плохо показывает, сколько силы в самом гребке. Сегодня стенку почти везде уберём: отрезки начинаются с места, из неподвижного положения. Стронуть стоящее тело можно только гребком — ни инерция, ни скольжение тут не помогут. Это самый честный тест на мощность, который делается без единого приспособления.",warm:[[300,"300м спокойно: 150м кроль + 150м спина"],[200,"4х50м i20: 25м проныр дельфином + 25м кроль свободно"],[100,"100м ноги брасс с доской, спокойно"]],main:[[200,"4х50м кроль i30 на минимальное число гребков","Та же цифра, что в первой тренировке, или меньше. Это ваш ориентир на весь блок: дальше усилие растёт, а число гребков стоит на месте."],[300,"6х50м ноги дельфин в ластах, режим 1:10 — первые 15м под водой, дальше на поверхности","Под водой сопротивление меньше, но и подтолкнуть себя руками нечем. Движение идёт от груди и таза, колени почти не сгибаются."],[400,"8х50м кроль, режим 1:30 — нечётные с места, чётные с обычного толчка","Вис у бортика, тело неподвижно, ноги не упираются. Разница между соседними отрезками и есть то, что вам даёт стенка: обычно два-три гребка. Если больше — вы сильно зависите от толчка и плохо разгоняетесь сами."],[100,"100м откупка: 50м ноги брасс на спине, руки в стрелке + 50м кроль в лёгком темпе"],[500,"5х100м основным стилем, режим 2:00 — каждая сотня начинается с места, первые 25м в полную силу, дальше ровно","К третьей сотне трогаться с места станет заметно тяжелее, чем к первой. Это и есть та выносливость, которой мощность меряется на дистанции."],[100,"100м откупка: на спине, руки вдоль тела, ноги мягко"],[300,"6х50м основным стилем i40 — с места, считаем гребки"]],cool:[[200,"200м спокойно: 100м спина + 100м брасс с долгим скольжением"],[100,"4х25м скольжения от бортика до полной остановки, руки в стрелке"]]},
      {n:3,vol:2900,note:"Про мощность почти всегда думают руками",story:"Про мощность почти всегда думают руками. Между тем ноги в кроле дают не столько тягу, сколько опору: если таз провалился, даже очень сильный гребок разворачивает вас вверх, а не толкает вперёд. Сегодня ноги работают отдельно от рук, в том числе против сопротивления — доска, поставленная вертикально, идёт перед вами как парус и превращает обычные 50 метров в силовую работу. В конце ласты, чтобы почувствовать, какой становится опора, когда ног хватает.",warm:[[200,"200м спокойно: 100м кроль + 100м брасс"],[200,"200м ноги брасс на спине, руки в стрелке, i30"],[200,"4х50м кроль i20 в прогресс"]],main:[[200,"200м ноги дельфин на боку, меняя бок каждые 25м","Тело строго на боку, нижняя рука впереди, голова лежит на плече. На боку волна становится видимой: движение зарождается в груди и тазе и прокатывается к стопам. Удар должен быть одинаково сильным в обе стороны — слабую здесь не спрятать."],[400,"8х50м ноги кроль с доской, i45 — 25м доска вертикально + 25м доска как обычно","Первые 25 метров доска идёт широкой стороной против воды, как парус, и скорость падает примерно вдвое. На повороте разворачиваете её плашмя — и вторые 25 тело едет почти само. Разница и есть та работа, которую делают ноги."],[100,"100м откупка: 50м ноги брасс на спине, руки в стрелке + 50м кроль в лёгком темпе"],[300,"6х50м ноги брасс, режим 1:20 — считаем толчки"],[100,"100м откупка: на спине, руки вдоль тела, ноги мягко"],[400,"4х100м основным стилем, режим 2:00 — 50м ноги почти выключены + 50м ноги в полную силу, на второй половине гребков меньше","Скорость вырастет меньше, чем ожидаешь: ноги в кроле дают не столько тягу, сколько опору. Зато тело сразу идёт выше, гребок цепляет больше воды — и те же 50 метров проходятся за меньшее число гребков."],[100,"100м откупка: 50м брасс с долгим скольжением + 50м спина спокойно"],[400,"8х50м кроль в ластах, режим 1:05 — мощно, в полную силу","Ласты поднимают таз за вас. Запомните это положение — именно его вы весь остальной год пытаетесь удержать без них."]],cool:[[200,"200м спокойно: 100м спина + 100м брасс с долгим скольжением"],[100,"4х25м скольжения от бортика до полной остановки, руки в стрелке"]]},
      {n:4,vol:3000,note:"Захват — самая недооценённая часть гребка и то место, где мощность теряется целиком",story:"Захват — самая недооценённая часть гребка и то место, где мощность теряется целиком. Большинство любителей начинает тянуть сразу после входа, прямой рукой, и первая треть гребка уходит на то, чтобы протолкнуть воду вниз, а не назад. Сегодня мы этот момент растягиваем: вставляем в него паузу. Пока рука стоит в точке захвата, инерция пропадает, и тянуть приходится с нуля — та же идея, что во второй тренировке, только внутри одного гребка. И общее правило блока: гребки считаем на каждой серии, а не только там, где это написано. Это единственный прибор, который у вас есть.",warm:[[300,"300м спокойно: 100м кроль + 100м спина + 100м брасс"],[200,"200м руки кроль с колобашкой спокойно — настраиваем захват"],[100,"100м ноги кроль с доской, спокойно"]],main:[[200,"8х25м i20 — упражнение на кроль «только первая фаза гребка, двумя руками одновременно»","Продвижение почти нулевое, и это нормально: задача не проплыть, а найти положение, в котором кисть уже смотрит назад, а локоть ещё наверху. Если есть трубка — наденьте, не придётся отвлекаться на вдох."],[400,"8х50м кроль в полной координации, режим 1:25 — пауза в точке захвата на счёт «раз», дальше гребок в полную силу","Рука входит, вытягивается вперёд, кисть разворачивается вниз, локоть остаётся высоко — и в этом положении остановка на счёт «раз». Только потом гребок. Пауза съедает инерцию: каждый гребок приходится начинать с нуля."],[100,"100м откупка: 50м ноги брасс на спине, руки в стрелке + 50м кроль в лёгком темпе"],[400,"8х50м кроль в маленьких лопатках, режим 1:15 — считаем гребки"],[100,"100м откупка: на спине, руки вдоль тела, ноги мягко"],[400,"8х50м кроль без лопаток, режим 1:15 — держим то же число гребков"],[100,"100м откупка: 50м брасс с долгим скольжением + 50м спина спокойно"],[400,"4х100м основным стилем, режим 2:00 — мощно, считаем гребки"]],cool:[[200,"200м спокойно: 100м спина + 100м брасс с долгим скольжением"],[100,"4х25м скольжения от бортика до полной остановки, руки в стрелке"]]},
      {n:5,vol:2800,note:"У любого пловца одна рука работает лучше другой, и почти никто об этом не знает: в полной коо…",story:"У любого пловца одна рука работает лучше другой, и почти никто об этом не знает: в полной координации сильная рука прикрывает слабую, и разницы не видно. Развести их просто — проплыть 50 метров одной рукой, потом другой и сравнить число гребков. Разрыв в один-два гребка есть у всех, три и больше — это уже потолок вашей мощности: сколько бы вы ни усиливали сильную сторону, скорость упрётся в слабую. Сегодня мы разрыв измеряем, целую серию плывём с лопаткой только на слабой руке — чтобы запомнить, как она должна чувствоваться, — и в конце меряем снова.",warm:[[300,"300м спокойно: 100м кроль + 100м спина + 100м брасс"],[200,"8х25м i20: упражнение на кроль «гребок только одной рукой», вторая рука прижата вдоль туловища"],[100,"100м ноги кроль на боку, по 25м на каждый бок"]],main:[[200,"4х50м кроль одной рукой i45, считаем гребки","Вот ваша асимметрия в числах. Рука, которой гребков больше, и есть слабая — на ней сегодня будет лопатка. Разница в один-два гребка нормальна, три и больше — то, ради чего это занятие."],[400,"8х50м кроль в полной координации с одной средней лопаткой на слабой руке, режим 1:20","Лопатка стоит только на слабой руке и на время выравнивает ощущения между сторонами. Тело будет уводить в сторону — не боритесь рулём, выравнивайте гребком. Задача одна: запомнить, как должна чувствоваться слабая рука."],[100,"100м откупка: 50м ноги брасс на спине, руки в стрелке + 50м кроль в лёгком темпе"],[400,"8х50м, режим 1:25 — упражнение на кроль «2 гребка правой, 2 гребка левой», вторая рука у бедра","Второй гребок подряд одной рукой — диагностический. Если он короче первого, рука не восстанавливает опору, а доезжает на инерции, и на слабой стороне это будет заметнее."],[100,"100м откупка: на спине, руки вдоль тела, ноги мягко"],[400,"4х100м кроль, режим 1:45 — на первых 50м считаем гребки только правой руки, на вторых только левой","Числа должны сойтись. Если на второй половине рука делает больше — вы плывёте на одной стороне, а вторую просто переставляете."],[100,"100м откупка: 50м брасс с долгим скольжением + 50м спина спокойно"],[200,"4х50м кроль одной рукой i45, считаем гребки","Сравните с началом занятия. Разрыв между руками должен стать меньше — обычно за счёт того, что слабая вспомнила опору, а не потому, что сильная устала."]],cool:[[200,"200м спокойно: 100м спина + 100м брасс с долгим скольжением"],[100,"4х25м скольжения от бортика до полной остановки, руки в стрелке"]]},
      {n:6,vol:2900,note:"Вторая половина гребка — там, где создаётся основная тяга, и там же, где любители теряют боль…",story:"Вторая половина гребка — там, где создаётся основная тяга, и там же, где любители теряют больше всего. Рука выходит из воды у пояса, последние двадцать сантиметров пропадают, и с каждым гребком вы недобираете кусок продвижения. Заметить это самому почти невозможно: усилие-то вы прикладываете. Поэтому сегодня мы сначала изолируем окончание, а потом проверяем его на растущей дистанции — недоведённый гребок разваливается первым, как только становится тяжело. Число гребков держим одно и то же от 50 метров до 150.",warm:[[300,"300м спокойно: 150м кроль + 150м спина"],[200,"200м руки кроль с колобашкой спокойно"],[100,"100м ноги брасс с доской, спокойно"]],main:[[200,"8х25м i20 — упражнение на кроль «только окончание гребка»","Рука входит и сразу, без наплыва и захвата, выполняет вторую половину: от груди до бедра, с ускорением кисти к концу. В локте угол 90 градусов — не больше и не меньше. Продвижение будет маленьким: вы плывёте половиной гребка."],[300,"6х50м кроль со средними лопатками, режим 1:20, с усилием на окончание гребка"],[100,"100м откупка: 50м ноги брасс на спине, руки в стрелке + 50м кроль в лёгком темпе"],[200,"4х50м кроль, режим 1:15 — запоминаем число гребков","Число с первых 50 метров должно продержаться до последних. Как только рука начнёт выходить раньше, оно поедет вверх — это и есть момент, когда гребок разваливается. Сам он потом не чинится, приходится возвращать сознательно."],[300,"3х100м кроль, режим 2:05 — то же число на каждых 50 метрах"],[300,"2х150м кроль, режим 3:05 — то же число"],[200,"4х50м кроль, режим 1:10 — то же число, но быстрее"],[100,"100м откупка: на спине, руки вдоль тела, ноги мягко"],[300,"6х50м основным стилем i40 — мощно"]],cool:[[200,"200м спокойно: 100м спина + 100м брасс с долгим скольжением"],[100,"4х25м скольжения от бортика до полной остановки, руки в стрелке"]]},
      {n:7,vol:2800,note:"Всё, что вы делаете в воде, — это борьба с сопротивлением, и бо́льшая часть силы уходит не на…",story:"Всё, что вы делаете в воде, — это борьба с сопротивлением, и бо́льшая часть силы уходит не на продвижение, а на то, чтобы протащить тело сквозь воду. Значит, сопротивление можно использовать как нагрузку: увеличить его специально, поработать, а потом убрать. Самый доступный способ — поднять голову. Подбородок над водой, перед грудью встаёт волна, таз уходит вниз, и несколько гребков подряд превращаются в силовую работу без единого приспособления. Долго так плыть не нужно: семи гребков хватает, чтобы загрузить, а дальше вы доплываете спокойно и чувствуете разницу. Если есть старая свободная футболка и правила бассейна это позволяют, наденьте её на всё занятие.",warm:[[300,"300м спокойно: 100м кроль + 100м спина + 100м брасс"],[200,"4х50м i20: 25м кроль на кулаках + 25м кроль свободно"],[100,"100м ноги кроль с доской, спокойно"]],main:[[200,"8х25м кроль i30 — первые 7 гребков с поднятой головой, дальше доплываем спокойно","Подбородок над водой, взгляд вперёд, голова не крутится. К седьмому гребку плечи уже тянет вверх — и вот тогда голова опускается, а тело само проваливается в нормальное положение."],[400,"8х50м кроль, режим 1:20 — на мощность, считаем гребки"],[100,"100м откупка: 50м ноги брасс на спине, руки в стрелке + 50м кроль в лёгком темпе"],[500,"5х100м кроль, режим 1:50 — первые 25м с головой над водой, дальше свободно","Первая четверть грузит, остальные три снимают урожай. К четвёртой сотне разница станет не такой яркой — тело привыкает, и это сигнал, что серию пора заканчивать."],[100,"100м откупка: на спине, руки вдоль тела, ноги мягко"],[600,"6х100м основным стилем, режим 1:55 — мощно","После работы с поднятой головой обычное плавание кажется лёгким, и это не иллюзия: тело действительно идёт выше. Держите гребок длинным, пока держится ощущение."]],cool:[[200,"200м спокойно: 100м спина + 100м брасс с долгим скольжением"],[100,"4х25м скольжения от бортика до полной остановки, руки в стрелке"]]},
      {n:8,vol:2900,note:"Семь тренировок подряд мы разбирали мощность на кроле, потому что там её проще измерить",story:"Семь тренировок подряд мы разбирали мощность на кроле, потому что там её проще измерить. Но самый мощный элемент в плавании — не гребок рукой, а толчок ногами в брассе: одно движение, которое разгоняет тело сильнее любого другого в воде. А самый силовой гребок руками — дельфином, где тяга идёт от корпуса, а не от плеча. Сегодня занятие разделено пополам: сначала брасс, потом дельфин. Если ваш основной стиль кроль, это не потерянный день — и то и другое возвращается в кроль, потому что учит тянуть корпусом и вкладываться в одно движение целиком.",warm:[[200,"200м спокойно: 100м кроль + 100м спина"],[200,"200м ноги дельфин на спине, руки в стрелке, i30"],[200,"200м брасс на минимальное число гребков"]],main:[[200,"8х25м ноги брасс, руки в стрелке, i30 — считаем толчки","После каждого толчка задержитесь в стрелке, пока тело едет. Закончилось скольжение — только тогда следующий толчок."],[200,"4х50м — упражнение на брасс «руки брасс / ноги кроль», i30","Ноги кролем держат тело ровно, и весь результат отрезка — это работа рук. Гребок короткий и быстрый, локти остаются впереди плеч."],[400,"8х50м брасс, режим 1:30 — мощно, считаем гребки"],[100,"100м откупка: 50м на спине двумя руками одновременно + 50м кроль в лёгком темпе"],[200,"8х25м ноги дельфин в ластах, i20 — мощно"],[200,"4х50м — упражнение на баттерфляй «гребок только одной рукой», вторая вытянута вперёд, i30","Нагрузка вдвое меньше, и освобождается внимание на детали: наплыв после входа, высокий локоть, доведение до бедра. Ноги работают непрерывно, два удара на цикл руки."],[200,"8х25м дельфин i35 — мощно"],[100,"100м откупка: 50м брасс с долгим скольжением + 50м спина спокойно"],[400,"4х100м основным стилем, режим 2:00 — мощно, считаем гребки","Вернитесь в свой стиль и перенесите ощущение: из брасса — вложиться в одно движение целиком, из дельфина — тянуть корпусом, а не плечом."]],cool:[[200,"200м спокойно: 100м спина + 100м брасс с долгим скольжением"],[100,"4х25м скольжения от бортика до полной остановки, руки в стрелке"]]},
      {n:9,vol:3000,note:"Тело быстро привыкает к любой нагрузке и перестаёт замечать разницу",story:"Тело быстро привыкает к любой нагрузке и перестаёт замечать разницу. Поэтому здесь мы работаем контрастом: сначала чашечки утяжеляют каждый гребок, а сразу после мы их снимаем — и несколько минут вода кажется пустой. Именно в этот момент и запоминается ощущение мощного, свободного гребка.",warm:[[300,"300м спокойно: 100м кроль с подсчётом гребков + 100м брасс на скольжение + 100м спина"],[200,"200м в трубке: 100м на кулаках + 100м в полной координации основным стилем"],[100,"100м кроль с подсчётом гребков — запомнить число на сегодня"]],main:[[300,"6х50м ноги дельфин в ластах, режим 1:10","Амплитуда небольшая, движение от груди. Ноги здесь готовят тело к тому, что дальше руки будут перегружены."],[100,"4х25м i20: упражнение на кроль «плавание на кулаках»"],[400,"8х50м кроль с чашечками, режим 1:20, мощно и плавно","С сопротивлением тянет частить. Считайте гребки: с чашечками допустим рост до трёх на полтиннике, больше — значит вы частите."],[200,"200м откупка: 200м спина спокойно — единственная задача вернуть дыхание"],[400,"8х50м кроль без чашечек, режим 1:15: удержать ту же длину гребка","Вот ради этой серии всё и делалось. Ощущение лёгкости обманчиво — не разменивайте его на частоту, держите длину."],[400,"8х50м основной стиль, режим 1:20: четыре отрезка с чашечками, четыре без","Тот же контраст на своём стиле. На брассе и дельфине чашечки особенно наглядно показывают, доводите ли вы гребок до конца."],[100,"100м откупка: 50м на спине двумя руками одновременно + 50м кроль длинным гребком — вернуть дыхание"],[200,"8х25м кроль без инвентаря на минимальное число гребков, i30","Замер тренировки. После контраста число гребков обычно лучшее за неделю — запишите его."]],cool:[[100,"100м спокойно: 50м брасс + 50м спина"],[200,"200м спокойно: 100м спина + 100м брасс с долгим скольжением"]]},
      {n:10,vol:3000,note:"Большие лопатки — самый мощный инструмент в бассейне и самый опасный",story:"Большие лопатки — самый мощный инструмент в бассейне и самый опасный. Они увеличивают площадь опоры настолько, что любая ошибка в технике усиливается вместе с усилием. Поэтому правило тренировки простое: плывём медленнее, чем позволяют лопатки, и следим за локтем. Мощность здесь набирается не скоростью, а качеством опоры.",warm:[[300,"300м спокойно: 100м кроль + 100м спина + 100м брасс"],[200,"200м комплекс по 50м в порядке комплекса: дельфин — спина — брасс — кроль, спокойно"],[100,"4х25м скольжения от бортика до полной остановки, руки в стрелке"]],main:[[300,"6х50м ноги кроль без доски на боку, режим 1:25","По 25 м на каждый бок. Плечо вытянутой руки у уха, тело вытянуто — это положение потом нужно будет удержать под лопатками."],[100,"4х25м i20: упражнение на кроль «только первая фаза гребка двумя руками»"],[400,"8х50м кроль с большими лопатками, режим 1:20, мощно и плавно, без ускорения","Скорость руки должна быть ниже привычной. Если плечо начинает ныть или кисть уходит выше локтя — снимайте лопатки и доплывайте серию средними."],[200,"200м откупка: 100м на спине двумя руками одновременно + 100м кроль длинным гребком — дыхание свободное"],[400,"4х100м кроль с большими лопатками и колобашкой, режим 2:10: число гребков ровное: разброс не больше трёх","Самая тяжёлая серия тренировки. Если второй полтинник даёт больше трёх лишних гребков, серия закончена — доплывайте откуп."],[400,"8х50м основной стиль без инвентаря, режим 1:20","Своим стилем плывём без лопаток: после большой площади опоры собственная рука кажется маленькой, и это ровно то ощущение, которое нужно перебороть длиной гребка."],[100,"100м откупка: 50м брасс с долгим скольжением + 50м на спине, ноги мягко"],[200,"8х25м кроль без инвентаря на минимальное число гребков, i30","Замер тренировки. Ощущение опоры после больших лопаток держится минут десять — используйте его."]],cool:[[200,"200м в трубке ноги кроль спокойно"],[100,"100м кроль в лёгком темпе — рука доходит до бедра, усилия не добавляем"]]},
      {n:11,vol:3000,note:"Прежде чем толкать воду, её нужно почувствовать",story:"Прежде чем толкать воду, её нужно почувствовать. Скайлинг — движение ладонью почти без продвижения — учит именно этому: находить плотную воду и удерживать её. Тренировка получается обманчиво лёгкой, но именно она чаще всего снимает пару гребков с полтинника.",warm:[[300,"300м спокойно: 150м кроль + 150м спина"],[200,"200м: 100м скайлинг + 100м спокойно"],[100,"4х25м i20: через одну — дельфин и кроль на минимальное число гребков"]],main:[[300,"6х50м ноги в ластах, руки в стрелке, режим 1:10","Руки вытянуты, голова между ними. Задача — почувствовать, как тело едет ровно, без раскачивания."],[100,"4х25м i20: скайлинг, ладонь ищет опору"],[400,"8х50м кроль, режим 1:20: 12,5м скайлинг + доплывание мощно и плавно","Сразу после скайлинга ладонь чувствительнее всего. Первые гребки после него должны быть самыми длинными на отрезке."],[200,"200м откупка: 100м брасс с долгим скольжением + 100м спина, ноги мягко"],[400,"8х50м руки с колобашкой и средними лопатками, режим 1:15","Лопатка убирает чувствительность ладони, поэтому опору теперь ищет предплечье. Локоть высоко, кисть ниже локтя."],[400,"8х50м основной стиль, режим 1:20, считаем гребки","На брассе чувство воды проверяется в разведении рук, на спине — в постановке кисти сразу после входа."],[100,"100м откупка: кроль в лёгком темпе, дыхание на 3 гребка — расслабить плечи"],[200,"8х25м кроль без инвентаря на минимальное число гребков, i30","Замер тренировки. Скайлинг обычно даёт эффект в тот же день — сравните с прошлым результатом."]],cool:[[200,"200м произвольно, дыхание свободное"],[100,"100м спина в полной координации, считаем гребки — число должно упасть"]]},
      {n:12,vol:3000,note:"Держать мощный гребок двадцать пять метров умеет почти каждый",story:"Держать мощный гребок двадцать пять метров умеет почти каждый. Держать его четыреста — почти никто. Здесь отрезки длиннее, а требование то же: одинаковое число гребков от первого полтинника до последней. Это самая честная проверка того, настоящая у вас мощность или разовая.",warm:[[300,"300м комплекс по 75м, спокойно: дельфин — спина — брасс — кроль"],[200,"200м в трубке спокойно, считаем гребки на каждом полтиннике"],[100,"100м упражнение на кроль «догонялки»"]],main:[[300,"6х50м ноги кроль с доской, режим 1:20","Ровная работа без рывков. Ноги здесь нужны для того, чтобы на длинных отрезках таз не проваливался."],[100,"4х25м i20: плавание на минимальное число гребков"],[400,"2х200м кроль с колобашкой и средними лопатками, режим 3:40: число гребков ровное: разброс не больше трёх","Записывайте гребки по каждому полтиннику отдельно. Обычно разваливается третья — именно там и начинается настоящая работа."],[200,"200м откупка: 50м ноги брасс на спине, руки в стрелке + 150м кроль в лёгком темпе"],[400,"400м кроль без инвентаря: удерживаем число гребков всю дистанцию","Скорость свободная, приоритет один — длина. Если число гребков выросло больше чем на три, сбросьте темп, но не длину."],[400,"8х50м основной стиль, режим 1:20","На своём стиле держать длину на серии сложнее всего. Не гонитесь за режимом: лучше отдохнуть лишние десять секунд, чем частить."],[100,"100м откупка: на спине, руки вдоль тела, ноги мягко — не разгоняться"],[200,"8х25м кроль на минимальное число гребков, i30","Замер тренировки. После длинной работы гребок обычно длиннее обычного — поймайте это состояние."]],cool:[[100,"100м брасс: гребок, пауза, толчок — торопиться некуда"],[200,"200м спокойно: 100м на спине двумя руками одновременно + 100м кроль длинным гребком"]]},
      {n:13,vol:3000,note:"Мощность в кроле и мощность в комплексе — разные вещи",story:"Мощность в кроле и мощность в комплексе — разные вещи. В дельфине тяга идёт от корпуса, в брассе — от разведения и сведения рук, на спине — от постановки кисти сразу после входа. Здесь мы проходим все четыре стиля и в каждом ищем свою точку приложения силы.",warm:[[300,"300м комплекс по 75м, спокойно"],[200,"200м спокойно: 4х50м — кроль, спина, брасс, кроль, дыхание свободное"],[100,"100м ноги дельфин на боку, смена стороны каждые 25м"]],main:[[300,"6х50м ноги дельфин в ластах, режим 1:10","Волна идёт от груди через таз к стопам. Это базовое движение для дельфина и заодно лучшая подготовка спины к работе."],[100,"4х25м i20: упражнение на баттерфляй «руки дельфин / ноги кроль»"],[400,"8х50м по стилям со средними лопатками, режим 1:30: 2 дельфин, 2 спина, 2 брасс, 2 кроль","Короткие серии на каждый стиль — так лопатки не успевают перегрузить плечо. На дельфине следите, чтобы руки выходили из воды мимо бёдер, а не через сторону."],[200,"200м откупка: 100м кроль на минимальное число гребков + 100м спина, руки вдоль тела"],[400,"4х100м комплекс, режим 2:15, считаем гребки на каждой 25","Записывайте четыре числа. Стиль с самым большим числом гребков — ваша слабая точка в комплексе, ей и будете заниматься отдельно."],[400,"8х50м основной стиль, режим 1:20","Свой стиль на свежую голову после комплекса ощущается иначе. Сравните число гребков с тем, что было в серии по стилям."],[100,"100м откупка: 50м ноги брасс на спине, руки в стрелке + 50м брасс на скольжение"],[200,"8х25м кроль без инвентаря на минимальное число гребков, i30","Замер тренировки. Кроль после комплекса всегда кажется лёгким — используйте это и постарайтесь снять лишний гребок."]],cool:[[200,"200м спокойно: 4х50м — брасс, спина, кроль, спина"],[100,"100м кроль, вдох в обе стороны через три гребка"]]},
      {n:14,vol:3000,note:"На спине мощность строится иначе: нет опоры на дыхании, тело держится только положением таза…",story:"На спине мощность строится иначе: нет опоры на дыхании, тело держится только положением таза, а гребок идёт под водой почти прямой траекторией. Любители на спине почти всегда гребут поверхностно и коротко. Разбираем это отдельной тренировкой — заодно спина хорошо разгружает плечо после кролевых объёмов.",warm:[[300,"300м спокойно: 150м спина + 150м кроль"],[200,"200м на спине: 100м «одна рука работает, вторая у бедра» + 100м «6-1-6»"],[100,"100м брасс на минимальное число гребков"]],main:[[300,"6х50м ноги на спине в стрелочке, режим 1:20","Таз у поверхности, колени под водой. Если из воды показались колени, значит работа идёт вниз, а не назад."],[100,"4х25м i20: скайлинг на спине"],[400,"8х50м спина со средними лопатками, режим 1:20, считаем гребки","Кисть входит мизинцем, локоть уходит под воду и сгибается — прямой рукой на спине протянуть воду невозможно, лопатка это только подчеркнёт."],[200,"200м откупка: 200м спина спокойно — единственная задача вернуть дыхание"],[400,"8х50м спина с колобашкой, режим 1:20, мощно и плавно","Без ног на спине таз проваливается сразу. Держите его напряжением живота, взгляд строго вверх."],[400,"8х50м основной стиль, режим 1:20","Возвращаемся к своему стилю: после спины плечи разгружены и гребок обычно получается длиннее."],[100,"100м откупка: 50м кроль на минимальное число гребков + 50м спина спокойно"],[200,"8х25м спина без инвентаря на минимальное число гребков, i30","Замер тренировки — сегодня на спине. Записывайте его отдельно от кролевого, это разные цифры."]],cool:[[200,"200м кроль спокойно на минимальное число гребков"],[100,"100м ноги брасс на спине, руки в стрелке"]]},
      {n:15,vol:3000,note:"Сборная тренировка: захват, окончание гребка, ноги, работа с сопротивлением и без него — всё…",story:"Сборная тренировка: захват, окончание гребка, ноги, работа с сопротивлением и без него — всё в одном занятии. Заканчивается она контрольным замером: четыре полтинника с фиксацией времени и числа гребков. Запишите обе цифры и вернитесь к ним через месяц — именно эта пара чисел показывает, растёт ли мощность.",warm:[[300,"300м спокойно: 100м кроль + 100м ноги дельфин на спине, руки в стрелке + 100м брасс"],[200,"200м упражнение на кроль «плавание на кулаках»: 100м скайлинг + 100м на кулаках"],[100,"100м ноги кроль с доской"]],main:[[300,"6х50м ноги кроль с доской, режим 1:20: три отрезка в ластах, три без","Сравните ощущение. Без ласт задача не догнать скорость, а сохранить то же положение таза."],[100,"4х25м i20: два отрезка «только первая фаза», два отрезка «только окончание гребка»"],[400,"8х50м кроль с чашечками, режим 1:20","Работа с сопротивлением перед замером. Держите число гребков, не разменивая длину на скорость."],[200,"200м откупка: 100м на спине двумя руками одновременно + 100м кроль длинным гребком — дыхание свободное"],[400,"8х50м кроль со средними лопатками и колобашкой, режим 1:15","Мощно и плавно, без ускорения. Это подготовка к замеру, а не соревнование с самим собой."],[400,"8х50м основной стиль, режим 1:20, считаем гребки","Свой стиль перед замером. Если число гребков здесь выросло больше чем на три по сравнению с началом тренировки, значит нагрузка была великовата — сбавьте усилие."],[100,"100м откупка: спина двумя руками одновременно — плечи опустить, не тянуться"],[200,"4х50м кроль без инвентаря i60: контрольный замер — время и число гребков","Плывите мощно и плавно, а не на максимум. Показатель — это время при минимальном числе гребков, а не время любой ценой."]],cool:[[200,"200м спокойно: 100м кроль на минимальное число гребков + 100м спина, руки вдоль тела"],[100,"100м спокойно: 50м спина + 50м кроль, кисть уходит у бедра"]]}
    ]}
  }},
  b_vo:{name:"Восстановление",lede:"Пульс 20–22 удара за десять секунд. Лопаток и чашечек здесь нет сознательно.",levels:{
    vo_n:{level:"Новичок",vol:"1000 м",w:[
      {n:1,vol:1000,note:"После тяжёлой тренировки гребок остаётся коротким и суетливым — тело помнит вчерашнее напряжение",story:"После тяжёлой тренировки гребок остаётся коротким и суетливым — тело помнит вчерашнее напряжение. Сегодня задача вернуть длину: плывём медленно и следим только за тем, чтобы рука доходила до конца. Никакого секундомера, пульс 20–22 удара за десять секунд.",warm:[[100,"100м спокойно: 50м кроль + 50м спина, п:20-22"],[100,"100м спина спокойно, руки вдоль тела, п:20-22"]],main:[[200,"200м кроль непрерывно, п:20-22, на минимальное число гребков — время не смотрим","Длина берётся из вытягивания вперёд и доведения руки до бедра, а не из усилия. Если начали уставать, вы плывёте слишком быстро."],[100,"100м упражнение на кроль «догонялки»: гребок начинается только после того, как вторая рука коснулась вытянутой руки впереди"],[200,"4х50м кроль i30, п:21: на первом полтиннике считаем гребки, дальше стараемся проплыть на один гребок меньше","Как только удержать число не выходит, оставайтесь на нём. Экономить за счёт задержки дыхания нельзя."],[100,"4х25м основной стиль i30, спокойно","На своём стиле плывите так, чтобы могли говорить. Сегодня скорость не нужна вообще."]],cool:[[100,"100м произвольно, дыхание свободное"],[100,"100м брасс с долгим скольжением"]]},
      {n:2,vol:1000,note:"После тренировки с лопатками и колобашкой плечо устаёт больше всего",story:"После тренировки с лопатками и колобашкой плечо устаёт больше всего. Здесь мы его разгружаем: трубка убирает поворот головы, спина разворачивает плечо в другую сторону, а ноги дают телу поработать без участия рук.",warm:[[100,"100м брасс на длинное скольжение, п:20-22"],[100,"100м ноги дельфин на спине, руки в стрелке, мягко"]],main:[[200,"200м в трубке спокойно, п:20-21 — голова не поворачивается, шея отдыхает","Без вращения корпуса легко провалить таз. Держите живот подобранным, тело в одну линию."],[100,"100м ноги на спине в стрелочке, спокойно"],[200,"4х50м спина i30, п:21, гребок длинный и мягкий","Кисть входит мизинцем, локоть сгибается под водой. Тянуть не нужно — движение мягкое."],[100,"4х25м основной стиль i30, спокойно","Если плечо ещё забито, замените эту серию на спину — сегодня это не потеря."]],cool:[[100,"100м кроль на минимальное число гребков, п:20-22"],[100,"100м на спине двумя руками одновременно, спокойно"]]},
      {n:3,vol:1000,note:"После тренировки с большим количеством работы ногами забиваются стопа и икра",story:"После тренировки с большим количеством работы ногами забиваются стопа и икра. Сегодня ноги почти отдыхают: колобашка между ног, тело держат руки, темп мягкий от начала до конца.",warm:[[100,"100м упражнение на кроль «плавание на кулаках»"],[100,"100м упражнение на спину «одна рука работает, вторая у бедра»"]],main:[[200,"200м руки кроль с колобашкой, п:20-22 — ноги отдыхают","Никаких лопаток. Гребок мягкий, задача не тянуть воду, а прокачать плечи движением."],[100,"100м упражнение на кроль «плавание с паузой в момент входа руки»"],[200,"4х50м кроль i30, п:21, ноги работают едва заметно","Ноги нужны только для того, чтобы держать таз у поверхности. Любое усилие сверх этого сегодня лишнее."],[100,"4х25м основной стиль i30, спокойно","В брассе следите, чтобы колено не уходило под живот — там чаще всего появляется дискомфорт."]],cool:[[100,"4х25м скольжения от бортика до полной остановки, руки в стрелке"],[100,"100м кроль с дыханием на 5 гребков, плечи расслаблены"]]},
      {n:4,vol:1000,note:"Тренировка для дня между двумя обычными занятиями",story:"Тренировка для дня между двумя обычными занятиями. Здесь нет ни одной задачи на технику и ничего, что требует внимания: просто ровное спокойное плавание со сменой стилей. Такие занятия чаще всего пропускают — и зря, именно они и дают восстановиться.",warm:[[100,"100м упражнение на брасс «два гребка руками, один толчок ногами»"],[100,"4х25м i20: через одну — дельфин и спина, спокойно"]],main:[[200,"200м кроль непрерывно, п:20-21","Единственный ориентир — пульс. Если после отрезка он выше 22, следующие метры плывите медленнее."],[100,"100м упражнение на кроль «2 гребка правой, 2 гребка левой»"],[200,"200м спина непрерывно, п:20-21","Смена стиля работает как отдых: другие мышцы, другое положение плеча."],[100,"4х25м основной стиль i30, спокойно","Своим стилем в спокойном темпе плавать непривычно и полезно: техника видна лучше, чем на скорости."]],cool:[[100,"100м спокойно: 50м брасс + 50м спина"],[100,"100м ноги брасс на спине, руки в стрелке, мягко"]]},
      {n:5,vol:1000,note:"Иногда тренировка оказывается тяжелее, чем планировалось: непривычная серия, много быстрых от…",story:"Иногда тренировка оказывается тяжелее, чем планировалось: непривычная серия, много быстрых отрезков, усталость на следующий день. Это занятие как раз для такого случая — спина, трубка и мягкий кроль, никаких требований к себе.",warm:[[100,"4х25м скольжения от бортика до полной остановки, руки в стрелке"],[100,"100м ноги брасс на спине, руки в стрелке"]],main:[[200,"200м спина непрерывно, п:20-21","Спина раскрывает грудной отдел и возвращает плечу нормальную амплитуду после нагрузки."],[100,"100м в трубке спокойно"],[200,"4х50м кроль i30, п:21","Гребок мягкий, дыхание свободное. Не проверяйте сегодня, «как идёт» — это будет в следующий раз."],[100,"4х25м основной стиль i30, очень спокойно","Свой стиль плывём в половину привычного усилия. Это не тренировка стиля, это восстановление."]],cool:[[100,"100м спина в полной координации, п:20-22"],[100,"100м брасс: гребок, длинная пауза, толчок"]]},
      {n:6,vol:1000,note:"Дыхание — то, чем можно управлять сознательно, и через него проще всего успокоить организм",story:"Дыхание — то, чем можно управлять сознательно, и через него проще всего успокоить организм. Вся тренировка построена вокруг длинного полного выдоха: он снимает напряжение, выравнивает пульс и заодно улучшает положение тела в воде.",warm:[[100,"100м спокойно, дыхание через 3 гребка"],[100,"100м кроль на минимальное число гребков, п:20-22"]],main:[[200,"200м кроль непрерывно, п:20-22, дыхание через 3 гребка, выдох длинный и полный","Выдох занимает всё время, пока лицо в воде. Задержка воздуха поднимает пульс и заставляет тело напрягаться."],[100,"100м спина: дыхание в ритме гребка, без задержек"],[200,"200м в трубке: выдох полностью в воду, вдох спокойный","В трубке дыхание слышно — используйте это как обратную связь. Вдох не должен быть жадным."],[100,"4х25м основной стиль i30, дыхание свободное","На брассе выдох короче по времени — начинайте его сразу, как голова уходит в воду."]],cool:[[100,"100м произвольно — плыть так, чтобы можно было говорить"],[100,"100м кроль, вдох на каждый третий гребок, плечи опущены"]]},
      {n:7,vol:1000,note:"Восстановительная тренировка — лучшее время для работы над положением тела: нет усталости, не…",story:"Восстановительная тренировка — лучшее время для работы над положением тела: нет усталости, нет спешки, можно чувствовать каждый метр. Сегодня много скольжений и спокойного плавания в вытянутом положении.",warm:[[100,"100м в ластах спокойно: 50м ноги дельфин на спине + 50м кроль"],[100,"100м на руках с колобашкой: 50м кроль + 50м спина (без колобашки — просто не работайте ногами)"]],main:[[200,"8х25м i20: толчок, длинное скольжение, дальше спокойно до бортика","Тело в стрелке: одна кисть на другой, голова между руками, взгляд вниз. Любой излом гасит скольжение мгновенно."],[100,"100м упражнение на кроль «ноги кроль на боку»"],[200,"200м кроль непрерывно, п:20-22, тело вытянуто, взгляд вниз","Голова продолжает линию позвоночника. Если смотрите вперёд, таз уходит вниз."],[100,"4х25м основной стиль i30, акцент на скольжение","В брассе скольжение — половина цикла. Не начинайте следующий гребок, пока тело ещё едет вперёд."]],cool:[[100,"100м спокойно: 50м спина + 50м кроль, п:20-22"],[100,"100м ноги дельфин на спине в ластах, мягко"]]},
      {n:8,vol:1000,note:"Считать гребки на восстановительной тренировке приятно: нет ни времени, ни соперника, есть то…",story:"Считать гребки на восстановительной тренировке приятно: нет ни времени, ни соперника, есть только собственная длина. Сегодня это число нужно не для рекорда, а чтобы удерживать внимание на технике.",warm:[[100,"100м кроль спокойно с подсчётом гребков"],[100,"100м упражнение на кроль «догонялки»"]],main:[[200,"200м кроль непрерывно на минимальное число гребков, п:20-22 — время не смотрим","Если ради экономии гребков вы начали задерживать дыхание, это уже не восстановление. Дышите свободно."],[100,"100м упражнение на кроль «догонялки»: гребок начинается только после того, как вторая рука коснулась вытянутой руки впереди"],[200,"4х50м кроль i30 на минимальное число гребков, п:21","Число будет чуть хуже, чем на свежих силах. Это нормальная цена усталости, не расстраивайтесь."],[100,"4х25м основной стиль i30 на минимум гребков, спокойно","На своём стиле считайте циклы, а не движения рук — так проще не сбиться."]],cool:[[100,"100м на спине, руки вдоль тела, ноги почти без усилия"],[100,"100м кроль длинным гребком — кисть доходит до бедра"]]},
      {n:9,vol:1000,note:"Упражнения обычно делают в разминке, наспех",story:"Упражнения обычно делают в разминке, наспех. Здесь наоборот: вся тренировка состоит из упражнений в спокойном темпе. Это единственный день, когда можно разобраться в движении, а не отработать его между сериями.",warm:[[100,"100м спокойно: 50м кроль + 50м спина, п:20-22"],[100,"100м спина спокойно, руки вдоль тела, п:20-22"]],main:[[200,"200м упражнения на кроль: 100м «плавание на кулаках» + 100м «плавание с паузой в момент входа руки»"],[100,"100м упражнение на брасс «два гребка руками, один толчок ногами» на спине «одна рука работает, вторая у бедра»"],[200,"200м кроль непрерывно, п:20-22 — собираем ощущения вместе","Не старайтесь применить всё сразу. Выберите одну мысль и держите её до конца отрезка."],[100,"4х25м основной стиль i30, спокойно","Проверяем, перенеслось ли что-то из упражнений в обычное плавание. Если нет — это работа не одного дня."]],cool:[[100,"100м спокойно: 50м ноги брасс с доской + 50м брасс на скольжение"],[100,"100м спина двумя руками одновременно, между гребками длинное скольжение"]]},
      {n:10,vol:1000,note:"Спина — самый недооценённый стиль у начинающих и при этом лучший восстановительный",story:"Спина — самый недооценённый стиль у начинающих и при этом лучший восстановительный. Плечо работает в другой плоскости, шея не крутится, дыхание полностью свободное. Если после тяжёлой недели хочется просто поплавать — плавайте на спине.",warm:[[100,"100м брасс на длинное скольжение, п:20-22"],[100,"100м ноги дельфин на спине, руки в стрелке, мягко"]],main:[[200,"200м спина непрерывно, п:20-22","Таз у поверхности, взгляд строго вверх. Если из воды показались колени, работа ног пошла вниз, а не назад."],[100,"100м упражнение на спину «одна рука работает, вторая вытянута за головой»"],[200,"200м ноги на спине в стрелочке, спокойно","Руки за головой, живот подобран. Движение мягкое, от бедра, без попытки разогнаться."],[100,"4х25м основной стиль i30, спокойно","После спины плечо разгружено, и гребок обычно получается длиннее, чем в начале тренировки."]],cool:[[100,"100м кроль спокойно"],[100,"100м спина спокойно, руки вдоль тела, п:20-22"]]},
      {n:11,vol:1000,note:"Трубка убирает из плавания одно движение — поворот головы",story:"Трубка убирает из плавания одно движение — поворот головы. Кажется мелочью, но именно на нём держится половина напряжения в шее. Плавание в трубке ощущается непривычно спокойным, и это ровно то, что нужно в день восстановления.",warm:[[100,"100м упражнение на кроль «плавание на кулаках»"],[100,"100м упражнение на спину «одна рука работает, вторая у бедра»"]],main:[[200,"200м в трубке непрерывно, п:20-22","Без вращения головы легко провалить таз. Живот подобран, тело в одну линию, взгляд вниз."],[100,"100м в трубке руки с колобашкой, спокойно"],[200,"200м спина спокойно, без трубки","Обратите внимание, насколько привычнее стало дыхание после трубки — это и есть эффект тренировки."],[100,"4х25м основной стиль i30, спокойно"]],cool:[[100,"100м произвольно, дыхание свободное"],[100,"100м брасс с долгим скольжением"]]},
      {n:12,vol:1000,note:"Иногда лучшее восстановление — просто плыть в одном темпе и ни о чём не думать",story:"Иногда лучшее восстановление — просто плыть в одном темпе и ни о чём не думать. Триста метров без остановок со сменой стиля каждые сто, пульс не выше 22. Для начинающего это ещё и хорошая проверка: получается ли плыть долго и спокойно.",warm:[[100,"100м упражнение на брасс «два гребка руками, один толчок ногами»"],[100,"4х25м i20: упражнение на кроль «один гребок правой, один левой, один двумя руками»"]],main:[[300,"300м непрерывно, п:20-22: каждые 100м смена стиля кроль / спина","Останавливаться нельзя, но и терпеть не нужно: если пульс пополз вверх, снижайте темп прямо на ходу."],[100,"100м откупка: 50м на спине двумя руками одновременно + 50м брасс на скольжение"],[100,"100м кроль на минимальное число гребков"],[100,"4х25м основной стиль i30, спокойно","После длинной работы свой стиль ощущается тяжелее. Плывите мягко, задача — закончить тренировку свежим."]],cool:[[100,"100м кроль на минимальное число гребков, п:20-22"],[100,"100м ноги дельфин на спине, руки в стрелке, мягко"]]},
      {n:13,vol:1000,note:"Смена стилей сама по себе восстанавливает: каждая группа мышц отдыхает, пока работает другая",story:"Смена стилей сама по себе восстанавливает: каждая группа мышц отдыхает, пока работает другая. Сегодня плаваем всеми доступными стилями в спокойном темпе и без единого требования к технике переходов.",warm:[[100,"4х25м i20: через одну — дельфин и спина, спокойно"],[100,"4х25м i20: по одному отрезку спина, брассом и кролем"]],main:[[200,"4х50м i40, п:20-22: 25м спина + 25м кроль, спокойно","Переход плывём как получится. Следим только за тем, чтобы дыхание оставалось свободным."],[100,"100м ноги с доской: 50м кроль + 50м брасс"],[200,"200м: 100м брасс + 100м кроль, спокойно","В брассе не форсируйте толчок — сегодня он мягкий, с длинным скольжением."],[100,"4х25м основной стиль i30","Свой стиль в конце всегда ощущается как отдых. Значит, остальные вы плыли не напрягаясь."]],cool:[[100,"100м на спине двумя руками одновременно, спокойно"],[100,"4х25м скольжения от бортика до полной остановки, руки в стрелке"]]},
      {n:14,vol:1000,note:"Чувство воды тренируется вниманием, а не нагрузкой",story:"Чувство воды тренируется вниманием, а не нагрузкой. Здесь мы намеренно убираем внешние ориентиры: не смотрим на часы, не считаем метры по разметке, а на коротких отрезках закрываем глаза. Странно ровно до первого раза.",warm:[[100,"4х25м скольжения от бортика до полной остановки, руки в стрелке"],[100,"100м ноги брасс на спине, руки в стрелке"]],main:[[200,"200м кроль: считаем гребки до стенки и ориентируемся на счёт, а не на разметку дна","Обычно пловец подстраивается под дно и бортик. Здесь — только под собственный счёт."],[100,"4х25м i30: 12,5м с закрытыми глазами + 12,5м спокойно с открытыми","Только на свободной дорожке и вдоль разделительной, чтобы её можно было коснуться рукой. Теряете направление — открывайте глаза."],[200,"200м кроль непрерывно, п:20-22, внимание на ощущение воды в ладони","Ищите момент, когда ладонь «упирается». Это тот навык, который на скорости теряется первым."],[100,"4х25м основной стиль i30, спокойно"]],cool:[[100,"100м кроль с дыханием на 5 гребков, плечи расслаблены"],[100,"100м спокойно: 50м брасс + 50м спина"]],safe:"Отрезки с закрытыми глазами выполняются только на свободной дорожке, вдоль разделительной, чтобы её можно было коснуться рукой. Если рядом плывут люди — эту серию заменяем на обычное спокойное плавание."},
      {n:15,vol:1000,note:"У человека, который работает сидя и плавает в основном кролем, грудной отдел закрывается, а п…",story:"У человека, который работает сидя и плавает в основном кролем, грудной отдел закрывается, а плечо привыкает к одному положению. Эта тренировка возвращает амплитуду: брасс на спине, вытянутые положения, работа двумя руками одновременно.",warm:[[100,"100м кроль на минимальное число гребков, п:20-22"],[100,"100м в ластах спокойно: 50м ноги дельфин на спине + 50м кроль"]],main:[[200,"200м брасс на спине спокойно","Руки идут через стороны в широкой амплитуде — именно это раскрывает грудной отдел. Если движение тугое, уменьшите размах, но не бросайте."],[100,"100м спина: работа двумя руками одновременно","Движение требует полного выноса плеча за голову. Двигайтесь медленно и не через боль."],[200,"200м кроль непрерывно, п:20-22","После работы на раскрытие пронос обычно идёт выше и свободнее. Не форсируйте, просто отметьте разницу."],[100,"4х25м основной стиль i30, спокойно","Заканчиваем своим стилем в мягком темпе. Тренировка про амплитуду, а не про метры."]],cool:[[100,"100м ноги брасс на спине, руки в стрелке, мягко"],[100,"100м спина в полной координации, п:20-22"]]}
    ]},
    vo_s:{level:"Средний",vol:"1500 м",w:[
      {n:1,vol:1500,note:"После скоростной тренировки гребок остаётся коротким и частым — тело помнит вчерашнюю суету",story:"После скоростной тренировки гребок остаётся коротким и частым — тело помнит вчерашнюю суету. Задача сегодня вернуть длину: плывём медленно, следим только за тем, чтобы рука доходила до конца. Секундомер не нужен, пульс держим на 20–22 ударах за десять секунд.",warm:[[200,"200м спокойно: 100м кроль + 100м спина, п:20-22"],[100,"100м спокойно: 50м кроль + 50м спина, п:20-22"]],main:[[300,"300м кроль непрерывно, п:20-22, на минимальное число гребков — время не смотрим","Длина берётся из вытягивания вперёд и доведения руки до бедра, а не из усилия. Если начали уставать, вы плывёте слишком быстро."],[100,"100м упражнение на кроль «догонялки»: гребок начинается только после того, как вторая рука коснулась вытянутой руки впереди"],[200,"4х50м кроль i30, п:21: на первом полтиннике считаем гребки, дальше стараемся проплыть на один гребок меньше","Как только удержать число не выходит, оставайтесь на нём до конца серии. Экономить за счёт задержки дыхания нельзя."],[200,"200м спина спокойно"],[200,"4х50м основной стиль i30, спокойно, без требований к темпу","На своём стиле после скоростной особенно тянет ускориться. Плывите так, чтобы могли говорить."]],cool:[[100,"100м спина спокойно, руки вдоль тела, п:20-22"],[100,"100м произвольно, дыхание свободное"]]},
      {n:2,vol:1500,note:"Мощностная тренировка бьёт по плечу сильнее всего: лопатки, колобашка, длинные серии на руки",story:"Мощностная тренировка бьёт по плечу сильнее всего: лопатки, колобашка, длинные серии на руки. Здесь плечо разгружается полностью — трубка, спина и ноги. Кроль в координации сегодня почти не появляется, и это осознанно.",warm:[[200,"200м спокойно: 100м кроль + 100м спина, п:20-22"],[100,"100м спина спокойно, руки вдоль тела, п:20-22"]],main:[[300,"300м в трубке спокойно, п:20-21 — голова не поворачивается, шея отдыхает","Без вращения корпуса легко провалить таз. Держите живот подобранным, тело в одну линию."],[200,"200м ноги кроль: 100м с доской + 100м на спине без доски, спокойно","Ноги здесь не тренируются, а прокачивают кровь через уставшие мышцы. Работа мягкая, без ускорений."],[100,"100м упражнение на баттерфляй «руки кроль / ноги дельфин» на спине «одна рука работает, вторая у бедра»"],[200,"4х50м спина i30, п:21, гребок длинный и мягкий","Спина разворачивает плечо в другую сторону, чем кроль — именно поэтому она и восстанавливает."],[200,"4х50м основной стиль i30, спокойно","Если ваш стиль брасс или дельфин и плечо ещё забито, замените серию на спину — сегодня это не потеря."]],cool:[[100,"100м брасс с долгим скольжением"],[100,"100м кроль на минимальное число гребков, п:20-22"]]},
      {n:3,vol:1500,note:"После объёмной тренировки первыми забиваются ноги: стопа, икра, передняя поверхность бедра",story:"После объёмной тренировки первыми забиваются ноги: стопа, икра, передняя поверхность бедра. Сегодня ноги почти не работают — колобашка между ног, тело держат руки, темп мягкий от начала до конца.",warm:[[200,"200м спокойно: 50м дельфин + 50м спина + 50м брасс + 50м кроль"],[100,"100м брасс на длинное скольжение, п:20-22"]],main:[[300,"300м руки кроль с колобашкой, п:20-22 — ноги полностью отдыхают","Никаких лопаток. Гребок мягкий, задача не тянуть воду, а прокачать плечи движением."],[100,"100м упражнение на кроль «плавание с паузой в момент входа руки»"],[200,"4х50м кроль i30, п:21, ноги работают едва заметно","Ноги нужны только для того, чтобы держать таз у поверхности. Любое усилие сверх этого сегодня лишнее."],[200,"200м спина спокойно"],[200,"4х50м основной стиль i30, спокойно","В брассе следите, чтобы колено не уходило под живот: после объёмной именно там появляется дискомфорт."]],cool:[[100,"100м ноги дельфин на спине, руки в стрелке, мягко"],[100,"100м на спине двумя руками одновременно, спокойно"]]},
      {n:4,vol:1500,note:"Тренировка для середины тяжёлой недели, когда впереди ещё одна серьёзная работа",story:"Тренировка для середины тяжёлой недели, когда впереди ещё одна серьёзная работа. Здесь нет ни одной задачи на технику: просто ровное спокойное плавание со сменой стилей. Именно такие занятия чаще всего пропускают — и зря, они и делают неделю рабочей.",warm:[[200,"200м спокойно: 100м брасс на длинное скольжение + 100м спина"],[100,"100м ноги дельфин на спине, руки в стрелке, мягко"]],main:[[200,"200м кроль непрерывно, п:20-21","Единственный ориентир — пульс. Если после отрезка он выше 22, следующие метры плывите медленнее."],[100,"100м упражнение на кроль «2 гребка правой, 2 гребка левой»"],[200,"200м спина непрерывно, п:20-21","Смена стиля работает как отдых: другие мышцы, другое положение плеча."],[200,"200м в трубке спокойно"],[300,"6х50м основной стиль i30, спокойно","Своим стилем в спокойном темпе плавать непривычно и полезно: техника видна лучше, чем на скорости."]],cool:[[100,"4х25м скольжения от бортика до полной остановки, руки в стрелке"],[100,"100м кроль с дыханием на 5 гребков, плечи расслаблены"]]},
      {n:5,vol:1500,note:"После контрольного заплыва или просто очень тяжёлой тренировки главное — не добавить ещё",story:"После контрольного заплыва или просто очень тяжёлой тренировки главное — не добавить ещё. Занятие построено вокруг спины и трубки: они разгружают плечо и шею лучше всего. Никаких выводов о результате сегодня не делаем, просто плаваем.",warm:[[200,"200м спокойно: 100м спина, руки вдоль тела + 100м кроль на минимальное число гребков"],[100,"100м упражнение на кроль «плавание на кулаках»"]],main:[[200,"200м спина непрерывно, п:20-21","После максимальной работы плечо перегружено спереди. Спина раскрывает грудной отдел и возвращает амплитуду."],[200,"200м в трубке спокойно"],[100,"100м упражнение на кроль «плавание на прямых руках», спокойно"],[300,"6х50м кроль i30, п:21","Гребок мягкий, дыхание свободное. Если тянет проверить, «а как сейчас идёт» — не проверяйте, это будет завтра."],[200,"4х50м основной стиль i30, очень спокойно","Свой стиль плывём в половину привычного усилия. Это не тренировка стиля, это восстановление."]],cool:[[100,"100м спокойно: 50м брасс + 50м спина"],[100,"100м ноги брасс на спине, руки в стрелке, мягко"]]},
      {n:6,vol:1500,note:"Дыхание — единственная система, которой можно управлять сознательно, и через неё проще всего…",story:"Дыхание — единственная система, которой можно управлять сознательно, и через неё проще всего успокоить организм. Вся тренировка построена вокруг длинного полного выдоха: он снимает напряжение, выравнивает пульс и заодно улучшает положение тела в воде.",warm:[[200,"200м спокойно, дыхание через 3 гребка"],[100,"100м упражнение на спину «одна рука работает, вторая у бедра»"]],main:[[300,"300м кроль непрерывно, п:20-22, дыхание через 3 гребка, выдох длинный и полный","Выдох занимает всё время, пока лицо в воде. Задержка воздуха поднимает пульс и заставляет тело напрягаться."],[100,"100м спина: дыхание в ритме гребка, без задержек"],[200,"200м в трубке: выдох полностью в воду, вдох спокойный","В трубке дыхание слышно — используйте это как обратную связь. Вдох не должен быть жадным."],[200,"200м упражнение на кроль «плавание на кулаках»"],[200,"4х50м основной стиль i30, дыхание свободное","На брассе выдох короче по времени — начинайте его сразу, как голова уходит в воду."]],cool:[[100,"100м спина в полной координации, п:20-22"],[100,"100м брасс: гребок, длинная пауза, толчок"]]},
      {n:7,vol:1500,note:"Восстановительная тренировка — лучшее время, чтобы поработать над положением тела: нет устало…",story:"Восстановительная тренировка — лучшее время, чтобы поработать над положением тела: нет усталости, нет спешки, можно чувствовать каждый метр. Сегодня много скольжений и длинного плавания в вытянутом положении.",warm:[[200,"200м комплекс по 50м в порядке комплекса: дельфин — спина — брасс — кроль, спокойно"],[100,"100м упражнение на брасс «два гребка руками, один толчок ногами»"]],main:[[200,"8х25м i20: толчок, скольжение примерно до середины бассейна, дальше спокойно","Тело в стрелке: одна кисть на другой, голова между руками, взгляд вниз. Любой излом гасит скольжение мгновенно."],[100,"100м упражнение на кроль «ноги кроль на боку»"],[300,"300м кроль непрерывно, п:20-22, тело вытянуто, взгляд вниз","Голова продолжает линию позвоночника. Если смотрите вперёд, таз уходит вниз."],[200,"200м ноги на спине в стрелочке, спокойно"],[200,"4х50м основной стиль i30, акцент на скольжение","В брассе скольжение — половина цикла. Не начинайте следующий гребок, пока тело ещё едет вперёд."]],cool:[[100,"100м произвольно — плыть так, чтобы можно было говорить"],[100,"100м кроль, вдох на каждый третий гребок, плечи опущены"]]},
      {n:8,vol:1500,note:"Считать гребки на восстановительной тренировке приятно: нет ни времени, ни соперника, есть то…",story:"Считать гребки на восстановительной тренировке приятно: нет ни времени, ни соперника, есть только собственная длина. Число будет хуже, чем на свежих силах, и это нормально — сегодня оно нужно не для рекорда, а чтобы удерживать внимание на технике.",warm:[[200,"200м в ластах спокойно: 100м ноги дельфин на спине, руки в стрелке + 100м кроль"],[100,"4х25м i20: через одну — дельфин и спина, спокойно"]],main:[[300,"300м кроль непрерывно на минимальное число гребков, п:20-22 — время не смотрим","Если ради экономии гребков вы начали задерживать дыхание или зависать в скольжении, это уже не восстановление."],[100,"100м упражнение на кроль «догонялки»: гребок начинается только после того, как вторая рука коснулась вытянутой руки впереди"],[200,"4х50м кроль i30 на минимальное число гребков, п:21","Разница с вашим лучшим результатом сегодня будет два-три гребка. Это нормальная цена усталости."],[200,"200м спина на минимальное число гребков"],[200,"4х50м основной стиль i30 на минимум гребков, спокойно","На своём стиле считайте циклы, а не движения рук — так проще не сбиться."]],cool:[[100,"100м спокойно: 50м спина + 50м кроль, п:20-22"],[100,"100м ноги дельфин на спине в ластах, мягко"]]},
      {n:9,vol:1500,note:"Упражнения обычно делают в разминке, наспех и уставшими",story:"Упражнения обычно делают в разминке, наспех и уставшими. Здесь наоборот: вся тренировка состоит из упражнений в спокойном темпе. Это единственный день, когда можно разобраться в движении, а не отработать его между сериями.",warm:[[200,"200м спокойно: 100м кроль + 100м на спине двумя руками одновременно"],[100,"4х25м скольжения от бортика до полной остановки, руки в стрелке"]],main:[[300,"300м упражнения на кроль: 100м «плавание на кулаках» + 100м с акцентом на высокий локоть + 100м «плавание с паузой в момент входа руки»"],[200,"200м упражнения на спину: 100м «6-1-6» + 100м «одна рука работает, вторая у бедра»"],[100,"100м упражнение на брасс «руки брасс / ноги кроль»"],[200,"200м кроль непрерывно, п:20-22 — собираем ощущения вместе","Не старайтесь применить всё сразу. Выберите одну мысль и держите её до конца отрезка."],[200,"4х50м основной стиль i30, спокойно","Здесь проверяем, перенеслось ли что-то из упражнений в обычное плавание. Если нет — это работа не одного дня."]],cool:[[100,"100м на спине, руки вдоль тела, ноги почти без усилия"],[100,"100м кроль длинным гребком — кисть доходит до бедра"]]},
      {n:10,vol:1500,note:"Спина — самый недооценённый стиль у любителей и при этом лучший восстановительный",story:"Спина — самый недооценённый стиль у любителей и при этом лучший восстановительный. Плечо работает в другой плоскости, шея не крутится, дыхание полностью свободное. Если после тяжёлой недели хочется просто поплавать — плавайте на спине.",warm:[[200,"200м спокойно: 100м ноги брасс с доской + 100м брасс на скольжение"],[100,"100м ноги брасс на спине, руки в стрелке"]],main:[[300,"300м спина непрерывно, п:20-22","Таз у поверхности, взгляд строго вверх. Если из воды показались колени, работа ног пошла вниз, а не назад."],[100,"100м упражнение на спину «одна рука работает, вторая вытянута за головой»"],[200,"4х50м спина i30, п:21, гребок длинный и мягкий","Кисть входит мизинцем, локоть сгибается под водой. Прямой рукой на спине протянуть воду невозможно."],[200,"200м ноги на спине в стрелочке"],[200,"4х50м основной стиль i30, спокойно","После спины плечо разгружено, и обычно гребок получается длиннее, чем в начале тренировки."]],cool:[[100,"100м кроль спокойно"],[100,"100м спокойно: 50м ноги брасс с доской + 50м брасс на скольжение"]]},
      {n:11,vol:1500,note:"Трубка убирает из плавания одно движение — поворот головы",story:"Трубка убирает из плавания одно движение — поворот головы. Кажется мелочью, но именно на нём держится половина напряжения в шее и плече. Тренировка в трубке ощущается непривычно спокойной, и это ровно то, что нужно после тяжёлой недели.",warm:[[200,"200м спокойно: 100м кроль + 100м спина, п:20-22"],[100,"100м кроль на минимальное число гребков, п:20-22"]],main:[[300,"300м в трубке непрерывно, п:20-22","Без вращения головы легко провалить таз. Живот подобран, тело в одну линию, взгляд вниз."],[200,"200м в трубке: 100м руки кроль с колобашкой + 100м в полной координации основным стилем","Колобашка плюс трубка — самое разгруженное положение в бассейне. Гребок мягкий, без попытки тянуть."],[100,"100м ноги кроль с доской и в трубке, спокойно"],[200,"200м спина спокойно, без трубки"],[200,"4х50м основной стиль i30, спокойно","Трубку снимаем. Обратите внимание, насколько привычнее стало дыхание — это и есть эффект тренировки."]],cool:[[100,"100м спина двумя руками одновременно, между гребками длинное скольжение"],[100,"100м спина спокойно, руки вдоль тела, п:20-22"]]},
      {n:12,vol:1500,note:"Иногда лучшее восстановление — просто долго плыть в одном темпе и ни о чём не думать",story:"Иногда лучшее восстановление — просто долго плыть в одном темпе и ни о чём не думать. Шестьсот метров без остановок, смена стиля каждые сто пятьдесят, пульс не выше 22. Голова разгружается не хуже мышц.",warm:[[200,"200м спокойно: 50м дельфин + 50м спина + 50м брасс + 50м кроль"],[100,"100м в ластах спокойно: 50м ноги дельфин на спине + 50м кроль"]],main:[[600,"600м непрерывно, п:20-22: каждые 150м смена стиля кроль / спина","Останавливаться нельзя, но и терпеть не нужно: если пульс пополз вверх, снижайте темп прямо на ходу."],[200,"200м откупка: 100м спина спокойно + 100м брасс с долгим скольжением"],[200,"4х50м основной стиль i30, спокойно","После длинной работы свой стиль ощущается тяжело. Плывите мягко, задача — закончить тренировку свежим."]],cool:[[100,"100м произвольно, дыхание свободное"],[100,"100м брасс с долгим скольжением"]]},
      {n:13,vol:1500,note:"Комплекс обычно означает работу: переходы, скорость, требования к технике",story:"Комплекс обычно означает работу: переходы, скорость, требования к технике. Сегодня всё наоборот — стили в спокойном темпе, без единого требования к стыкам. Смена стилей сама по себе восстанавливает: каждая группа мышц отдыхает, пока работает другая.",warm:[[200,"200м спокойно: 100м брасс на длинное скольжение + 100м спина"],[100,"100м на руках с колобашкой: 50м кроль + 50м спина (без колобашки — просто не работайте ногами)"]],main:[[300,"3х100м комплекс i40, п:20-22, без требований к переходам","Переходы плывём как получится. Следим только за тем, чтобы дыхание оставалось свободным на всех стилях."],[200,"200м ноги комплекс без доски (дельфин — спина — брасс — кроль по 25м), спокойно"],[200,"200м: 100м спина + 100м брасс, спокойно"],[100,"100м упражнение на кроль «только окончание гребка» на самый неудобный для вас стиль"],[200,"4х50м основной стиль i30","Свой стиль в конце комплекса всегда ощущается как отдых. Значит, остальные вы плыли не напрягаясь."]],cool:[[100,"100м кроль на минимальное число гребков, п:20-22"],[100,"100м ноги дельфин на спине, руки в стрелке, мягко"]]},
      {n:14,vol:1500,note:"Чувство воды тренируется вниманием, а не нагрузкой",story:"Чувство воды тренируется вниманием, а не нагрузкой. Здесь мы намеренно убираем внешние ориентиры: не смотрим на часы, не считаем метры по разметке, а на коротких отрезках закрываем глаза. Странно ровно до первого раза.",warm:[[200,"200м спокойно: 100м спина, руки вдоль тела + 100м кроль на минимальное число гребков"],[100,"100м упражнение на кроль «догонялки»"]],main:[[200,"200м кроль: считаем гребки до стенки и ориентируемся на счёт, а не на разметку дна","Обычно пловец подстраивается под дно и бортик. Здесь — только под собственный счёт."],[100,"4х25м i30: 12,5м с закрытыми глазами + 12,5м спокойно с открытыми","Только на свободной дорожке и вдоль разделительной, чтобы её можно было коснуться рукой. Теряете направление — открывайте глаза."],[300,"300м кроль непрерывно, п:20-22, внимание на ощущение воды в ладони","Ищите момент, когда ладонь «упирается». Это тот навык, который на скорости теряется первым."],[200,"200м спина спокойно"],[200,"4х50м основной стиль i30, спокойно"]],cool:[[100,"100м на спине двумя руками одновременно, спокойно"],[100,"4х25м скольжения от бортика до полной остановки, руки в стрелке"]],safe:"Отрезки с закрытыми глазами выполняются только на свободной дорожке, вдоль разделительной, чтобы её можно было коснуться рукой. Если рядом плывут люди — эту серию заменяем на обычное спокойное плавание."},
      {n:15,vol:1500,note:"У любителя, который много плавает кролем и работает сидя, грудной отдел закрывается, а плечо…",story:"У любителя, который много плавает кролем и работает сидя, грудной отдел закрывается, а плечо привыкает к одному положению. Эта тренировка возвращает амплитуду: брасс на спине, длинные вытянутые положения, работа двумя руками одновременно.",warm:[[200,"200м комплекс по 50м в порядке комплекса: дельфин — спина — брасс — кроль, спокойно"],[100,"100м спокойно: 50м кроль + 50м спина, п:20-22"]],main:[[200,"200м брасс на спине спокойно","Руки идут через стороны в широкой амплитуде — именно это раскрывает грудной отдел. Если движение тугое, уменьшите размах, но не бросайте."],[100,"100м упражнение на спину «скольжение на спине в стрелочке»"],[300,"300м на спине: 150м двумя руками одновременно + 150м обычно","Работа двумя руками требует полного выноса плеча за голову. Двигайтесь медленно и не через боль."],[200,"200м кроль непрерывно, п:20-22","После работы на раскрытие пронос обычно идёт выше и свободнее. Не форсируйте, просто отметьте разницу."],[200,"4х50м основной стиль i30, спокойно","Заканчиваем своим стилем в мягком темпе. Тренировка про амплитуду, а не про метры."]],cool:[[100,"100м кроль с дыханием на 5 гребков, плечи расслаблены"],[100,"100м спокойно: 50м брасс + 50м спина"]]}
    ]},
    vo_p:{level:"Продвинутый",vol:"2000 м",w:[
      {n:1,vol:2000,note:"После скоростной тренировки гребок остаётся коротким и частым — тело помнит вчерашнюю суету",story:"После скоростной тренировки гребок остаётся коротким и частым — тело помнит вчерашнюю суету. Задача этой тренировки вернуть длину: плывём медленно, спокойно, следим только за тем, чтобы рука доходила до конца. Секундомер сегодня не нужен, а пульс держим на 20–22 ударах за десять секунд.",warm:[[200,"200м спокойно: 100м кроль + 100м спина, п:20-22"],[100,"100м спокойно: 50м кроль + 50м спина, п:20-22"],[100,"100м спина спокойно, руки вдоль тела, п:20-22"]],main:[[400,"400м кроль непрерывно, п:20-22, на минимальное число гребков — время не смотрим","Длина берётся из вытягивания вперёд и доведения руки до бедра, а не из усилия. Если начали уставать, вы плывёте слишком быстро."],[200,"200м упражнение на кроль «догонялки»: гребок начинается только после того, как вторая рука коснулась вытянутой руки впереди"],[300,"6х50м кроль i30, п:21: на первом полтиннике считаем гребки, дальше стараемся проплыть на один гребок меньше — и так, пока получается","Как только удержать число не выходит, оставайтесь на нём до конца серии. Экономить гребки за счёт задержки дыхания или зависания в скольжении нельзя — темп остаётся спокойным."],[200,"200м спина спокойно"],[200,"4х50м основной стиль i30, спокойно, без требований к темпу","На своём стиле после скоростной особенно тянет ускориться. Плывите так, чтобы могли говорить."]],cool:[[200,"200м спокойно: 100м спина + 100м брасс с долгим скольжением"],[100,"100м произвольно, дыхание свободное"]]},
      {n:2,vol:2000,note:"Мощностная тренировка бьёт по плечу сильнее всего: лопатки, колобашка, длинные серии на руки",story:"Мощностная тренировка бьёт по плечу сильнее всего: лопатки, колобашка, длинные серии на руки. Здесь мы плечо разгружаем полностью — трубка, спина и ноги. Кроль в координации сегодня почти не появляется, и это осознанно.",warm:[[200,"200м спокойно: 100м кроль + 100м спина, п:20-22"],[100,"100м брасс на длинное скольжение, п:20-22"],[100,"100м ноги дельфин на спине, руки в стрелке, мягко"]],main:[[400,"400м в трубке спокойно, п:20-21 — голова не поворачивается, шея отдыхает","В трубке легко провалить таз, потому что нет вращения корпуса. Держите живот подобранным, тело в одну линию."],[300,"300м ноги кроль: 150м с доской + 150м на спине без доски, спокойно","Ноги здесь не тренируются, а прокачивают кровь через уставшие мышцы. Работа мягкая, без ускорений."],[200,"200м упражнение на спину «одна рука работает, вторая вытянута за головой» на спине «одна рука работает, вторая у бедра»"],[200,"4х50м спина i30, п:21, гребок длинный и мягкий","Спина физиологически разворачивает плечо в другую сторону, чем кроль — именно поэтому она и восстанавливает."],[200,"4х50м основной стиль i30, спокойно","Если ваш стиль дельфин или брасс и плечо ещё забито, замените эту серию на спину — сегодня это не потеря."]],cool:[[200,"200м произвольно, дыхание свободное"],[100,"100м брасс с долгим скольжением"]]},
      {n:3,vol:2000,note:"После объёмной тренировки первыми забиваются ноги: стопа, икра, передняя поверхность бедра",story:"После объёмной тренировки первыми забиваются ноги: стопа, икра, передняя поверхность бедра. Сегодня ноги почти не работают — колобашка между ног, тело держат руки, а вся тренировка идёт в мягком темпе.",warm:[[200,"200м спокойно: 50м дельфин + 50м спина + 50м брасс + 50м кроль"],[100,"100м руки кроль с колобашкой спокойно"],[100,"100м упражнение на кроль «плавание на кулаках»"]],main:[[400,"400м руки кроль с колобашкой, п:20-22 — ноги полностью отдыхают","Никаких лопаток. Гребок мягкий, задача не тянуть воду, а прокачать плечи движением."],[200,"200м упражнение на кроль «плавание с паузой в момент входа руки»"],[300,"6х50м кроль i30, п:21, ноги работают едва заметно","Ноги нужны только для того, чтобы держать таз у поверхности. Любое усилие сверх этого сегодня лишнее."],[200,"200м спина спокойно"],[200,"4х50м основной стиль i30, спокойно","В брассе следите, чтобы колено не уходило под живот: после объёмной именно там чаще всего появляется дискомфорт."]],cool:[[100,"100м кроль на минимальное число гребков, п:20-22"],[200,"200м спокойно: 100м на спине двумя руками одновременно + 100м кроль длинным гребком"]]},
      {n:4,vol:2000,note:"Тренировка для середины тяжёлой недели, когда впереди ещё одна серьёзная работа",story:"Тренировка для середины тяжёлой недели, когда впереди ещё одна серьёзная работа. Здесь нет ни одной задачи на технику и ни одного элемента, требующего внимания: просто ровное спокойное плавание со сменой стилей. Именно такие занятия чаще всего пропускают — и зря, они и делают неделю рабочей.",warm:[[200,"200м спокойно: 100м брасс на длинное скольжение + 100м спина"],[200,"200м ноги кроль с доской спокойно"]],main:[[300,"300м кроль непрерывно, п:20-21","Единственный ориентир — пульс. Если после отрезка он выше 22, следующие метры плывите медленнее."],[200,"200м упражнение на кроль «2 гребка правой, 2 гребка левой»"],[300,"300м спина непрерывно, п:20-21","Смена стиля здесь работает как отдых: другие мышцы, другое положение плеча."],[200,"200м в трубке спокойно"],[300,"6х50м основной стиль i30, спокойно","Своим стилем в спокойном темпе плавать непривычно и полезно: техника видна лучше, чем на скорости."]],cool:[[200,"200м произвольно, дыхание свободное"],[100,"100м ноги дельфин на спине, руки в стрелке, мягко"]]},
      {n:5,vol:2000,note:"После контрольного заплыва или соревнований организм получил максимальную нагрузку, и главное…",story:"После контрольного заплыва или соревнований организм получил максимальную нагрузку, и главное сейчас — не добавить ещё. Эта тренировка построена вокруг спины и трубки: они разгружают плечо и шею лучше всего. Никаких выводов о результате сегодня не делаем, просто плаваем.",warm:[[200,"200м спокойно: 100м спина, руки вдоль тела + 100м кроль на минимальное число гребков"],[100,"100м упражнение на спину «одна рука работает, вторая у бедра»"],[100,"100м упражнение на брасс «два гребка руками, один толчок ногами»"]],main:[[300,"300м спина непрерывно, п:20-21","После стартов плечо перегружено спереди. Спина раскрывает грудной отдел и возвращает нормальную амплитуду."],[300,"300м в трубке спокойно"],[200,"200м упражнение на брасс «руки брасс / ноги кроль», спокойно"],[300,"6х50м кроль i30, п:21","Гребок мягкий, дыхание свободное. Если тянет проверить, «а как сейчас идёт» — не проверяйте, это будет завтра."],[200,"4х50м основной стиль i30, очень спокойно","Свой стиль сегодня плывём в половину привычного усилия. Это не тренировка стиля, это восстановление."]],cool:[[200,"200м спокойно: 4х50м — брасс, спина, кроль, спина"],[100,"100м на спине двумя руками одновременно, спокойно"]]},
      {n:6,vol:2000,note:"Дыхание — единственная система, которой можно управлять сознательно, и через неё проще всего…",story:"Дыхание — единственная система, которой можно управлять сознательно, и через неё проще всего успокоить организм. Вся тренировка построена вокруг длинного полного выдоха: он снимает напряжение, выравнивает пульс и заодно улучшает положение тела в воде.",warm:[[200,"200м спокойно, дыхание через 3 гребка"],[100,"4х25м i20: через одну — дельфин и спина, спокойно"],[100,"4х25м скольжения от бортика до полной остановки, руки в стрелке"]],main:[[400,"400м кроль непрерывно, п:20-22, дыхание через 3 гребка, выдох длинный и полный","Выдох должен занимать всё время, пока лицо в воде. Задержка воздуха поднимает пульс и заставляет тело напрягаться."],[200,"200м спина: дыхание в ритме гребка, без задержек"],[300,"300м в трубке: выдох полностью в воду, вдох спокойный","В трубке дыхание слышно — используйте это как обратную связь. Вдох не должен быть жадным."],[200,"200м упражнение на кроль «плавание на кулаках»"],[200,"4х50м основной стиль i30, дыхание свободное","На брассе и дельфине выдох короче по времени — начинайте его сразу, как голова уходит в воду."]],cool:[[200,"200м спокойно: 100м кроль на минимальное число гребков + 100м спина, руки вдоль тела"],[100,"4х25м скольжения от бортика до полной остановки, руки в стрелке"]]},
      {n:7,vol:2000,note:"Восстановительная тренировка — лучшее время, чтобы поработать над положением тела: нет устало…",story:"Восстановительная тренировка — лучшее время, чтобы поработать над положением тела: нет усталости, нет спешки, можно чувствовать каждый метр. Сегодня много скольжений и длинного плавания в вытянутом положении. Скорость не нужна вообще.",warm:[[200,"200м комплекс по 50м в порядке комплекса: дельфин — спина — брасс — кроль, спокойно"],[100,"100м ноги брасс на спине, руки в стрелке"],[100,"100м кроль на минимальное число гребков, п:20-22"]],main:[[300,"12х25м i20: толчок, скольжение примерно до середины бассейна, дальше спокойно","Тело в стрелке: одна кисть на другой, голова между руками, взгляд вниз. Любой излом гасит скольжение мгновенно."],[200,"200м упражнение на кроль «ноги кроль на боку», по 25м на каждый бок"],[400,"400м кроль непрерывно, п:20-22, тело вытянуто, взгляд вниз","Голова продолжает линию позвоночника. Если смотрите вперёд, таз уходит вниз и вы тащите за собой воду."],[200,"200м ноги на спине в стрелочке, спокойно"],[200,"4х50м основной стиль i30, акцент на скольжение","В брассе скольжение — половина цикла. Не начинайте следующий гребок, пока тело ещё едет вперёд."]],cool:[[200,"200м спокойно: 4х25м скольжения от бортика до полной остановки, руки в стрелке + 100м брасс на длинное скольжение"],[100,"100м кроль с дыханием на 5 гребков, плечи расслаблены"]]},
      {n:8,vol:2000,note:"Считать гребки на восстановительной тренировке приятно: нет ни времени, ни соперника, есть то…",story:"Считать гребки на восстановительной тренировке приятно: нет ни времени, ни соперника, есть только собственная длина. Число будет хуже, чем на свежих силах, и это нормально — сегодня оно нужно не для рекорда, а чтобы удерживать внимание на технике.",warm:[[200,"200м в ластах спокойно: 100м ноги дельфин на спине, руки в стрелке + 100м кроль"],[100,"100м в ластах спокойно: 50м ноги дельфин на спине + 50м кроль"],[100,"100м на руках с колобашкой: 50м кроль + 50м спина (без колобашки — просто не работайте ногами)"]],main:[[400,"400м кроль непрерывно на минимальное число гребков, п:20-22 — время не смотрим","Если ради экономии гребков вы начали задерживать дыхание или зависать в скольжении — это уже не восстановление. Дышите свободно."],[200,"200м упражнение на кроль «догонялки»: гребок начинается только после того, как вторая рука коснулась вытянутой руки впереди"],[300,"6х50м кроль i30 на минимальное число гребков, п:21","Разница с вашим лучшим результатом сегодня будет два-три гребка. Это нормальная цена усталости, не расстраивайтесь."],[200,"200м спина на минимальное число гребков"],[200,"4х50м основной стиль i30 на минимум гребков, спокойно","На своём стиле считать сложнее — считайте циклы, а не движения рук, так проще не сбиться."]],cool:[[200,"200м спокойно: 100м спина + 100м брасс с долгим скольжением"],[100,"100м спокойно: 50м брасс + 50м спина"]]},
      {n:9,vol:2000,note:"Упражнения обычно делают в разминке, наспех и уставшими",story:"Упражнения обычно делают в разминке, наспех и уставшими. Здесь наоборот: вся тренировка состоит из упражнений в спокойном темпе, по всем стилям. Это единственный день, когда можно спокойно разобраться в движении, а не отработать его между сериями.",warm:[[200,"200м спокойно: 100м кроль + 100м на спине двумя руками одновременно"],[100,"100м упражнение на кроль «догонялки»"],[100,"100м спокойно: 50м кроль + 50м спина, п:20-22"]],main:[[300,"300м упражнения на кроль: 100м «плавание на кулаках» + 100м с акцентом на высокий локоть + 100м «плавание с паузой в момент входа руки»"],[300,"300м упражнения на спину: 100м «6-1-6» + 100м «часы» + 100м «одна рука работает, вторая у бедра»"],[200,"200м упражнения на брасс: 100м «руки брасс / ноги кроль» + 100м ноги брасс, руки в стрелке"],[300,"300м кроль непрерывно, п:20-22 — собираем ощущения вместе","После упражнений гребок ощущается иначе. Не старайтесь применить всё сразу, выберите одну мысль и держите её."],[200,"4х50м основной стиль i30, спокойно","Здесь проверяем, перенеслось ли что-то из упражнений в обычное плавание. Если нет — ничего страшного, это работа не одного дня."]],cool:[[200,"200м произвольно, дыхание свободное"],[100,"100м на минимальное число гребков"]]},
      {n:10,vol:2000,note:"Спина — самый недооценённый стиль у любителей и при этом лучший восстановительный",story:"Спина — самый недооценённый стиль у любителей и при этом лучший восстановительный. Плечо работает в другой плоскости, шея не крутится, дыхание полностью свободное. Если после тяжёлой недели хочется просто поплавать — плавайте на спине.",warm:[[200,"200м спокойно: 100м ноги брасс с доской + 100м брасс на скольжение"],[100,"100м ноги на спине с руками вдоль тела"],[100,"100м спина спокойно, руки вдоль тела, п:20-22"]],main:[[400,"400м спина непрерывно, п:20-22","Таз у поверхности, взгляд строго вверх. Если из воды показались колени, работа ног пошла вниз, а не назад."],[200,"200м упражнение на спину «одна рука работает, вторая вытянута за головой»"],[300,"6х50м спина i30, п:21, гребок длинный и мягкий","Кисть входит мизинцем, локоть сгибается под водой. Прямой рукой на спине протянуть воду невозможно — и сегодня не нужно."],[200,"200м ноги на спине в стрелочке"],[200,"4х50м основной стиль i30, спокойно","Возврат к своему стилю после спины: плечо разгружено, и обычно гребок получается длиннее, чем в начале тренировки."]],cool:[[200,"200м кроль спокойно"],[100,"100м ноги брасс на спине, руки в стрелке, мягко"]]},
      {n:11,vol:2000,note:"Трубка убирает из плавания одно движение — поворот головы",story:"Трубка убирает из плавания одно движение — поворот головы. Кажется мелочью, но именно на нём держится половина напряжения в шее и плече. Целая тренировка в трубке ощущается непривычно спокойной, и это ровно то, что нужно после тяжёлой недели.",warm:[[200,"200м спокойно: 100м кроль + 100м спина, п:20-22"],[100,"100м брасс на длинное скольжение, п:20-22"],[100,"100м ноги дельфин на спине, руки в стрелке, мягко"]],main:[[400,"400м в трубке непрерывно, п:20-22","Без вращения головы легко провалить таз. Живот подобран, тело в одну линию, взгляд вниз."],[300,"300м в трубке: 150м руки кроль с колобашкой + 150м в полной координации основным стилем","Колобашка плюс трубка — самое разгруженное положение в бассейне. Гребок мягкий, без попытки тянуть."],[200,"200м ноги кроль с доской и в трубке, спокойно"],[200,"200м спина спокойно, без трубки"],[200,"4х50м основной стиль i30, спокойно","Трубку снимаем. Обратите внимание, насколько привычнее стало дыхание — это и есть эффект тренировки."]],cool:[[200,"200м спокойно: 100м на спине двумя руками одновременно + 100м кроль длинным гребком"],[100,"100м спина в полной координации, п:20-22"]]},
      {n:12,vol:2000,note:"Иногда лучшее восстановление — просто долго плыть в одном темпе и ни о чём не думать",story:"Иногда лучшее восстановление — просто долго плыть в одном темпе и ни о чём не думать. Тысяча метров без остановок, смена стиля каждые двести, пульс не выше 22. Голова разгружается не хуже мышц, а это после тяжёлой недели важно не меньше.",warm:[[200,"200м спокойно: 50м дельфин + 50м спина + 50м брасс + 50м кроль"],[100,"100м упражнение на кроль «плавание на кулаках»"],[100,"4х25м i20: упражнение на спину «одна рука работает, вторая вытянута за головой»"]],main:[[1000,"1000м непрерывно, п:20-22: каждые 200м смена стиля кроль / спина","Останавливаться нельзя, но и терпеть не нужно: если пульс пополз вверх, снижайте темп прямо на ходу. Дистанция важнее скорости."],[100,"100м откупка: 50м на спине двумя руками одновременно + 50м брасс на скольжение"],[200,"4х50м основной стиль i30, спокойно","После длинной работы свой стиль ощущается тяжело. Плывите мягко, задача — закончить тренировку свежим."]],cool:[[200,"200м спокойно: 4х50м — брасс, спина, кроль, спина"],[100,"100м брасс: гребок, длинная пауза, толчок"]]},
      {n:13,vol:2000,note:"Комплекс обычно означает работу: переходы, скорость, требования к технике",story:"Комплекс обычно означает работу: переходы, скорость, требования к технике. Сегодня всё наоборот — четыре стиля в спокойном темпе, без единого требования к стыкам. Смена стилей сама по себе восстанавливает: каждая группа мышц отдыхает, пока работает другая.",warm:[[200,"200м спокойно: 100м брасс на длинное скольжение + 100м спина"],[100,"100м ноги комплекс без доски (дельфин — спина — брасс — кроль по 25м)"],[100,"100м упражнение на спину «одна рука работает, вторая у бедра»"]],main:[[400,"4х100м комплекс i40, п:20-22, без требований к переходам","Переходы плывём как получится. Единственное, за чем следим, — чтобы дыхание оставалось свободным на всех четырёх стилях."],[200,"200м ноги комплекс без доски (дельфин — спина — брасс — кроль по 25м), спокойно"],[300,"300м: 100м спина + 100м брасс + 100м кроль, спокойно"],[200,"200м упражнение на брасс «два гребка руками, один толчок ногами»: по 100м на два самых неудобных для вас стиля"],[200,"4х50м основной стиль i30","Свой стиль в конце комплекса всегда ощущается как отдых. Это хороший знак: значит, остальные три вы плыли не напрягаясь."]],cool:[[200,"200м спокойно: 100м кроль на минимальное число гребков + 100м спина, руки вдоль тела"],[100,"100м произвольно — плыть так, чтобы можно было говорить"]]},
      {n:14,vol:2000,note:"Чувство воды тренируется вниманием, а не нагрузкой",story:"Чувство воды тренируется вниманием, а не нагрузкой. Здесь мы намеренно убираем внешние ориентиры: не смотрим на часы, не считаем метры по разметке, а на коротких отрезках закрываем глаза. Тренировка кажется странной ровно до первого раза — а потом становится любимой.",warm:[[200,"200м спокойно: 100м спина, руки вдоль тела + 100м кроль на минимальное число гребков"],[100,"100м упражнение на брасс «два гребка руками, один толчок ногами»"],[100,"4х25м i20: через одну — дельфин и спина, спокойно"]],main:[[300,"300м кроль: считаем гребки до стенки и ориентируемся на счёт, а не на разметку дна","Обычно пловец подстраивается под дно и бортик. Здесь — только под собственный счёт, и стенка каждый раз оказывается там, где вы её не ждали."],[200,"8х25м i30: 12,5м с закрытыми глазами + 12,5м спокойно с открытыми","Только на свободной дорожке и вдоль разделительной, чтобы её можно было коснуться рукой. Как только теряете направление — открывайте глаза."],[400,"400м кроль непрерывно, п:20-22, внимание на ощущение воды в ладони","Ищите момент, когда ладонь «упирается». Это тот самый навык, который на скорости теряется первым."],[200,"200м спина спокойно"],[200,"4х50м основной стиль i30, спокойно","На своём стиле повторите то же наблюдение: где именно рука находит опору и в какой момент теряет её."]],cool:[[200,"200м спокойно: 4х25м скольжения от бортика до полной остановки, руки в стрелке + 100м брасс на длинное скольжение"],[100,"100м кроль, вдох на каждый третий гребок, плечи опущены"]],safe:"Отрезки с закрытыми глазами выполняются только на свободной дорожке, вдоль разделительной, чтобы её можно было коснуться рукой. Если рядом плывут люди — эту серию заменяем на обычное спокойное плавание."},
      {n:15,vol:2000,note:"У любителя, который много плавает кролем и работает сидя, грудной отдел закрывается, а плечо…",story:"У любителя, который много плавает кролем и работает сидя, грудной отдел закрывается, а плечо привыкает к одному положению. Эта тренировка возвращает амплитуду: брасс на спине, длинные вытянутые положения, работа двумя руками одновременно. После неё гребок обычно ощущается свободнее.",warm:[[200,"200м комплекс по 50м в порядке комплекса: дельфин — спина — брасс — кроль, спокойно"],[100,"4х25м скольжения от бортика до полной остановки, руки в стрелке"],[100,"100м ноги брасс на спине, руки в стрелке"]],main:[[300,"300м брасс на спине спокойно","Руки идут через стороны в широкой амплитуде — именно это раскрывает грудной отдел. Если движение тугое, уменьшите размах, но не бросайте."],[200,"200м упражнение на спину «скольжение на спине в стрелочке»"],[300,"300м на спине: 150м двумя руками одновременно + 150м обычно","Работа двумя руками требует полного выноса плеча за голову. Двигайтесь медленно и не через боль."],[300,"300м кроль непрерывно, п:20-22","После работы на раскрытие пронос обычно идёт выше и свободнее. Не форсируйте, просто отметьте разницу."],[200,"4х50м основной стиль i30, спокойно","Заканчиваем своим стилем в мягком темпе. Никаких требований к скорости — тренировка про амплитуду, а не про метры."]],cool:[[200,"200м спокойно: 100м спина + 100м брасс с долгим скольжением"],[100,"100м спокойно: 50м спина + 50м кроль, п:20-22"]]}
    ]}
  }}
};
